import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Merges all records from a duplicate customer ID into a master customer ID. Updates minerName to match the master profile name.',
  inputSchema: z.object({
    duplicateCustomerId: z.string(),
    masterCustomerId: z.string(),
    masterMinerName: z.string(),
  }),
  outputSchema: z.object({
    updatedCount: z.number(),
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input }) => {
    const { duplicateCustomerId, masterCustomerId, masterMinerName } = input;

    if (duplicateCustomerId === masterCustomerId) {
      return { updatedCount: 0, success: false, message: 'Duplicate and master cannot be the same profile.' };
    }

    // Find all records with the duplicate customer ID
    const allRecords = await Database.findAll({ limit: 50000 });
    const targets = (allRecords ?? []).filter(r => r.customerId === duplicateCustomerId);

    if (targets.length === 0) {
      return { updatedCount: 0, success: false, message: `No records found for Customer ID: ${duplicateCustomerId}` };
    }

    // Update each record: overwrite customerId and normalize minerName to master
    let updatedCount = 0;
    for (const record of targets) {
      await Database.update({
        rowId: record.id,
        row: {
          customerId: masterCustomerId,
          minerName: masterMinerName,
        },
      });
      updatedCount++;
    }

    return {
      updatedCount,
      success: true,
      message: `Successfully merged ${updatedCount} record(s) from ${duplicateCustomerId} → ${masterCustomerId}`,
    };
  },
});

