    existingRecord: z.record(z.unknown()).optional(),
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const ts = new Date().toISOString();
    console.log(`[updateRecord][${ts}] START spreadsheet=${TARGET_SPREADSHEET_ID} rowId=${input.rowId} eventId=${input.eventId ?? 'none'} user=${context?.user?.email} fields=${Object.keys(input.fields).join(',')}`);

    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    // ── Validate rowId is a positive integer ──
    if (!Number.isInteger(input.rowId) || input.rowId <= 0) {
      throw new Error(`Invalid rowId: ${input.rowId}. Must be a positive integer.`);
    }

    const sanitized: Partial<DatabaseRowType> = {};
    let needsProfitRecalc = false;

    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        const sfStr = String(value ?? '');
        if (sfStr.toUpperCase().startsWith('PROMO:')) {
          (sanitized as Record<string, unknown>).freeSf = sfStr;
        } else {
          sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? true : false;
        }
        needsProfitRecalc = true;
      } else if (key === 'profit') {
        continue;
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
        if (PROFIT_FIELDS.has(key)) needsProfitRecalc = true;
      }
    }

    // Use existingRecord from frontend if provided — avoids expensive Database.findAll()
    const getExistingRecord = async (): Promise<Record<string, unknown>> => {
      if (input.existingRecord) return input.existingRecord;
      const allRows = await Database.findAll({});
      return allRows?.find(r => r.id === input.rowId) ?? {};
    };

    let computedProfit: number | undefined;
    if (needsProfitRecalc) {
      const existingRecord = await getExistingRecord();
      const mergedForProfit = { ...existingRecord, ...sanitized };
      computedProfit = Number(
        calculateServerProfit(mergedForProfit, {
          phpRate: input.phpRate,
          silverSellRate: input.silverSellRate,
          silverBrandedSellRate: input.silverBrandedSellRate,
          silverCostRate: input.silverCostRate,
          silverBrandedCostRate: input.silverBrandedCostRate,
        })
      );
      (sanitized as Record<string, unknown>).profit = computedProfit;
    }

    // Server-side layaway validation
    const LAYAWAY_FIELDS = new Set(['la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment', 'downpayment']);
    const touchingLayaway = Object.keys(input.fields).some(k => LAYAWAY_FIELDS.has(k));
    if (touchingLayaway) {
      const existingForValidation = await getExistingRecord();
      const merged: any = { ...existingForValidation, ...sanitized };
      const mop = String(merged.modeOfPayment || '').toLowerCase();
      if (mop === 'layaway') {
        const USD_AED = 3.67;
        const grams = parseFloat(String(merged.grams ?? '')) || 0;
        const clientRate = parseFloat(String(merged.clientRate ?? '')) || 0;
        const currency = String(merged.currency || 'AED').toUpperCase();
        const qty = parseFloat(String(merged.qty ?? '')) || 1;
        let rateAED = clientRate;
        if (currency === 'PHP') rateAED = clientRate / input.phpRate;
        else if (currency === 'USD') rateAED = clientRate * USD_AED;
        const cat = String(merged.category || '').toLowerCase();
        let totalSales = 0;
        if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('diamond')) {
          totalSales = rateAED * qty;
        } else {
          totalSales = rateAED * grams;
        }
        const shippingAED = 25;
        const totalAED = totalSales + shippingAED;
        const dpRaw = parseFloat(String(merged.downpayment ?? '')) || 0;
        const dpAED = currency === 'PHP' ? dpRaw / input.phpRate : currency === 'USD' ? dpRaw * USD_AED : dpRaw;
        const maxLayaway = Math.max(0, totalAED - dpAED);
        const laRaw = ['la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment']
          .reduce((s, k) => s + (parseFloat(String(merged[k] ?? '')) || 0), 0);
        const laAED = currency === 'PHP' ? laRaw / input.phpRate : currency === 'USD' ? laRaw * USD_AED : laRaw;
        if (laAED > maxLayaway + 0.01) {
          throw new Error(`Layaway total (AED ${laAED.toFixed(2)}) exceeds remaining balance (AED ${maxLayaway.toFixed(2)}). Please reduce the installment amounts.`);
        }
      }
    }

    await Database.update({ rowId: input.rowId, row: sanitized });

    console.log(`[updateRecord][${ts}] WRITTEN spreadsheet=${TARGET_SPREADSHEET_ID} rowId=${input.rowId} eventId=${input.eventId ?? 'none'} fields=${Object.keys(sanitized).join(',')}${computedProfit !== undefined ? ` computedProfit=${computedProfit}` : ''}`);

    return { success: true };
  },
});

