src/components/InvoiceModal.tsx.content:
import { useRef, useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, Copy, Loader2, CreditCard } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

// Statuses that mean the item is completed/on-the-way — shown on a SEPARATE invoice
const DISPATCHED_STATUSES = new Set(['Dispatched', 'Delivered', 'Given to Shop']);
// Statuses fully excluded from all invoices
const EXCLUDED_STATUSES = new Set(['Cancelled', 'Returned Item']);

function sortByDate(list: DatabaseRowType[]) {
  return [...list].sort((a, b) => {
    const ta = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
    const tb = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
    return ta - tb;
  });
}

type InvoiceTab = 'active' | 'layaway' | 'dispatched';

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);
  const [tab, setTab] = useState<InvoiceTab>('active');
  const [ccIncludeShipping, setCcIncludeShipping] = useState(false);

  useEffect(() => {
    if (!document.getElementById('html2canvas-script') && !(window as any).html2canvas) {
      const script = document.createElement('script');
      script.id = 'html2canvas-script';
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  // LAYAWAY: items with Layaway status
  const layawayRecords = useMemo(() =>
    sortByDate(records.filter(r => r.status === 'Layaway')),
    [records]
  );

  // ACTIVE: pending/waiting/payment — NOT dispatched/delivered/cancelled/layaway
  const activeRecords = useMemo(() =>
    sortByDate(records.filter(r => {
      const s = r.status || '';
      return !EXCLUDED_STATUSES.has(s) && !DISPATCHED_STATUSES.has(s) && s !== 'Layaway';
    })),
    [records]
  );

  // DISPATCHED / COMPLETED: items on-the-way or already delivered
  const dispatchedRecords = useMemo(() =>
    sortByDate(records.filter(r => DISPATCHED_STATUSES.has(r.status || ''))),
    [records]
  );

  const visibleRecords =
    tab === 'active' ? activeRecords :
    tab === 'layaway' ? layawayRecords :
    dispatchedRecords;

  const baseRecord = visibleRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  // Show "Include Shipping in CC" toggle only when there are CC items AND shipping applies
  const hasCcItems = visibleRecords.some(r => (r.modeOfPayment || '') === 'Credit Card');
  const hasShipping = visibleRecords.length > 0 && !visibleRecords.every(r => isFreeSf(r)) && calcShippingFee(visibleRecords[0]) > 0;
  const showCcShippingToggle = hasCcItems && hasShipping;

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleCopyImage = async () => {
    if (visibleRecords.length === 0 || !printRef.current) return;

    const html2canvas = (window as any).html2canvas;
    if (!html2canvas) {
      toast.error('The image tool is still loading. Please try again in a few seconds.');
      return;
    }

    setIsCopying(true);
    toast.info('Generating image, please wait...');

    try {
      const makeImagePromise = async (): Promise<Blob> => {
        const canvas = await html2canvas(printRef.current!, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          scrollY: 0,
          windowHeight: printRef.current?.scrollHeight || window.innerHeight
        });
        return new Promise<Blob>((resolve, reject) => {
          canvas.toBlob((blob: Blob | null) => {
            if (blob) resolve(blob);
            else reject(new Error('Failed to generate image blob'));
          }, 'image/png');
        });
      };

      await navigator.clipboard.write([
        new ClipboardItem({ 'image/png': makeImagePromise() })
      ]);
      toast.success('Invoice image copied! You can now paste it into Meta Business Suite.');
    } catch (error: any) {
      console.error(error);
      if (error.name === 'NotAllowedError') {
        toast.error('Clipboard permission denied. Please allow clipboard access in your browser settings.');
      } else {
        toast.error('Failed to copy image. Try again.');
      }
    } finally {
      setIsCopying(false);
    }
  };

  const tabConfig: { key: InvoiceTab; label: string; count: number; color: string }[] = [
    { key: 'active', label: 'Active Orders', count: activeRecords.length, color: 'bg-primary text-primary-foreground' },
    { key: 'layaway', label: 'Layaway', count: layawayRecords.length, color: 'bg-violet-600 text-white' },
    { key: 'dispatched', label: 'Dispatched / Delivered', count: dispatchedRecords.length, color: 'bg-primary text-primary-foreground' },
  ];

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0" aria-describedby={undefined}>
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between gap-4">
              <DialogTitle className="text-base font-bold text-foreground">
                Statement of Account
              </DialogTitle>
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                  <Select value={currency} onValueChange={setCurrency}>
                    <SelectTrigger className="h-8 w-24 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CURRENCIES.map(c => (
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button
                  onClick={handleCopyImage}
                  size="sm"
                  variant="outline"
                  className="h-8 border-border text-foreground"
                  disabled={visibleRecords.length === 0 || isCopying}
                >
                  {isCopying ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Copy className="h-3.5 w-3.5 mr-1.5" />}
                  {isCopying ? 'Copying...' : 'Copy Image'}
                </Button>
                <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={visibleRecords.length === 0}>
                  <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
                </Button>
              </div>
            </div>

            {/* CC Shipping Toggle */}
            {showCcShippingToggle && (
              <div className="flex items-center gap-2 px-1 py-1.5 rounded-lg bg-muted border border-border">
                <CreditCard className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                <span className="text-xs text-muted-foreground font-medium">CC Surcharge on:</span>
                <div className="flex rounded-md overflow-hidden border border-border text-xs font-semibold">
                  <button
                    onClick={() => setCcIncludeShipping(false)}
                    className={`px-2.5 py-1 transition-colors ${!ccIncludeShipping ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}
                  >
                    Items only
                  </button>
                  <button
                    onClick={() => setCcIncludeShipping(true)}
                    className={`px-2.5 py-1 transition-colors ${ccIncludeShipping ? 'bg-primary text-primary-foreground' : 'bg-card text-muted-foreground hover:bg-muted'}`}
                  >
                    Items + Shipping
                  </button>
                </div>
                {ccIncludeShipping && (
                  <span className="text-xs text-amber-600 font-medium">5% applied on subtotal + shipping</span>
                )}
              </div>
            )}

            {/* Tab switcher */}
            <div className="flex gap-1 flex-wrap">
              {tabConfig.map(t => (
                <button
                  key={t.key}
                  onClick={() => setTab(t.key)}
                  className={`px-3 py-1 rounded text-xs font-semibold transition-colors ${
                    tab === t.key
                      ? t.color
                      : 'bg-muted text-muted-foreground hover:bg-muted/80'
                  }`}
                >
                  {t.label}
                  {t.count > 0 && (
                    <span className={`ml-1.5 text-xs rounded-full px-1.5 ${tab === t.key ? 'bg-white/20' : 'bg-muted-foreground/20'}`}>
                      {t.count}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </DialogHeader>

        {visibleRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Items</p>
            <p className="text-xs">
              {tab === 'active'
                ? 'No active/pending items. Check the other tabs.'
                : tab === 'layaway'
                ? 'No layaway items for this customer.'
                : 'No dispatched or delivered items.'}
            </p>
          </div>
        )}

        {visibleRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4 bg-white">
              <InvoicePrintContent records={visibleRecords} currency={currency} ccIncludeShipping={ccIncludeShipping} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

src/api/generateInvoiceNumber.ts.content:
import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType } from 'zite-integrations-backend-sdk';

/**
 * SPLIT IDENTITY FIX: Normalizes a name by stripping all spaces, hyphens,
 * and non-alphanumeric characters, then lowercasing.
 *
 * Examples:
 *   "JING-JING DOMINGGO" → "jingjingdominggo"
 *   "JING JING DOMINGGO " → "jingjingdominggo"  (same person!)
 *   "Jing-Jing  Dominggo" → "jingjingdominggo"  (same person!)
 */
function normalizeName(name: string): string {
  return name.replace(/[\s\-_]/g, '').replace(/[^a-z0-9]/gi, '').toLowerCase();
}

export default createEndpoint({
  description: 'Generate a deterministic invoice number safely without memory exhaustion',
  authenticated: true,
  inputSchema: z.object({
    prefix: z.string().length(6),
    recordId: z.number(),
    dateOfLive: z.string(),
    minerName: z.string(),
  }),
  outputSchema: z.object({
    invoiceNumber: z.string(),
  }),
  execute: async ({ input }) => {
    const { prefix, dateOfLive, minerName } = input;

    // Memory Crash Prevention: Fetch in constrained chunks and discard unrelated rows
    const BATCH_SIZE = 500;
    const sameDateRecords: DatabaseRowType[] = [];
    let offset = 0;

    while (true) {
      const batch = await Database.findAll({ offset, limit: BATCH_SIZE });
      if (!batch || batch.length === 0) break;

      for (const r of batch) {
        if (r.dateOfLive === dateOfLive) {
          sameDateRecords.push(r);
        }
      }

      if (batch.length < BATCH_SIZE) break;
      offset += BATCH_SIZE;
    }

    // SPLIT IDENTITY FIX: Group by normalized name so typos don't create ghost profiles.
    // "JING-JING" and "JING JING" both normalize to "jingjing" → same client slot.
    const clientMap = new Map<string, { minId: number }>();
    for (const r of sameDateRecords) {
      const key = normalizeName(r.minerName || '');
      if (!key) continue;

      const existing = clientMap.get(key);
      if (!existing) {
        clientMap.set(key, { minId: r.id });
      } else if (r.id < existing.minId) {
        existing.minId = r.id;
      }
    }

    // Sort clients deterministically by their earliest record ID
    const sortedClients = Array.from(clientMap.entries())
      .sort((a, b) => a[1].minId - b[1].minId);

    const myKey = normalizeName(minerName);
    const clientIndex = sortedClients.findIndex(([key]) => key === myKey);

    const seq = clientIndex === -1 ? sortedClients.length + 1 : clientIndex + 1;
    return { invoiceNumber: `${prefix}${String(seq).padStart(3, '0')}` };
  },
});

