import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, Users, Layout, Crown, BookOpen, XCircle, PauseCircle, ShieldCheck, CheckCircle2, AlertTriangle, CreditCard, ChevronDown, Share2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';
import LayawayPaymentAlert from './LayawayPaymentAlert';
import { parseDateRobust } from '@/lib/calculations';

function agingHours(dateStr?: string): number {
  if (!dateStr) return 0;
  const d = parseDateRobust(dateStr);
  if (!d) return 0;
  return Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60));
}

function AgingLabel({ dateStr, warnAfterHours }: { dateStr?: string; warnAfterHours: number }) {
  const hours = agingHours(dateStr);
  const days = Math.floor(hours / 24);
  const isUrgent = hours >= warnAfterHours;
  if (!dateStr) return null;
  return (
    <span className={`inline-flex items-center gap-0.5 text-[9px] font-bold px-1.5 py-0.5 rounded-full border ml-1 ${isUrgent ? 'bg-destructive/20 text-destructive border-destructive/30' : 'bg-secondary text-muted-foreground border-border'}`}>
      {isUrgent && <AlertTriangle className="h-2.5 w-2.5" />}
      {days === 0 ? 'today' : `${days}d`}
    </span>
  );
}

function hasLayawayAlerts(records: DatabaseRowType[]): boolean {
  const n = (v: unknown) => parseFloat(String(v ?? '0')) || 0;
  for (const r of records) {
    if (r.status !== 'Layaway') continue;
    const d = parseDateRobust(r.dateOfLive);
    if (!d) continue;
    const payments = [n(r.la1MonthPayment), n(r.la2MonthPayment), n(r.la3MonthPayment), n(r.la4MonthPayment)];
    for (let i = 0; i < payments.length; i++) {
      if (payments[i] > 0) continue;
      const due = new Date(d.getTime() + (i + 1) * 30 * 24 * 60 * 60 * 1000);
      const days = Math.ceil((due.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
      if (days <= 5 && days >= -3) return true;
      break;
    }
  }
  return false;
}

interface SectionProps {
  icon: React.ReactNode;
  label: string;
  count: number;
  colorClass: string;
  borderClass: string;
  badgeClass: string;
  open: boolean;
  onToggle: () => void;
  children: React.ReactNode;
  urgent?: boolean;
}

function StatusSection({ icon, label, count, colorClass, borderClass, badgeClass, open, onToggle, children, urgent }: SectionProps) {
  return (
    <div className={`mb-3 rounded-xl border overflow-hidden transition-colors ${urgent ? 'border-destructive/40 bg-destructive/5' : 'border-border bg-card/50'}`}>
      <button
        className="w-full flex items-center gap-2.5 px-4 py-3 text-left focus:outline-none"
        onClick={onToggle}
      >
        <span className={colorClass}>{icon}</span>
        <span className={`font-cinzel text-xs font-bold tracking-widest uppercase ${colorClass}`}>{label}</span>
        {count > 0 && (
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${badgeClass}`}>{count}</span>
        )}
        {urgent && count > 0 && (
          <span className="text-[9px] font-bold text-destructive bg-destructive/10 border border-destructive/20 px-1.5 py-0.5 rounded-full animate-pulse">
            ACTION NEEDED
          </span>
        )}
        <div className={`h-px flex-1 ${borderClass} opacity-30`} />
        <ChevronDown className={`h-4 w-4 ${colorClass} transition-transform duration-200 ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <div className="px-3 pb-3 animate-in fade-in slide-in-from-top-2 duration-200">
          {children}
        </div>
      )}
    </div>
  );
}

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  // For Pullout is open by default — it's the most urgent section
  const [showPullout, setShowPullout] = useState(true);
  const [showHold, setShowHold] = useState(false);
  const [showPaymentVerif, setShowPaymentVerif] = useState(false);
  const [showReseller, setShowReseller] = useState(false);
  const [showOutsource, setShowOutsource] = useState(false);
  const [showDispatched, setShowDispatched] = useState(false);
  const [showDelivered, setShowDelivered] = useState(false);
  const [showCancelled, setShowCancelled] = useState(false);
  const [showLayaway, setShowLayaway] = useState(false);
  const [showLayawayAlert, setShowLayawayAlert] = useState(true);

  const { forPullout, onHold, paymentVerif, reseller, outsource, dispatched, delivered, cancelled, layaway } = useMemo(() => {
    const filtered = records.filter(r => {
      const s = r.status || '';
      if (!['For Pullout', 'Dispatch', 'Dispatched', 'Delivered', 'Given to Shop', 'Paid/DP but Item Hold', 'Payment for Verification', 'Reseller', 'Outsource', 'Cancelled', 'Layaway'].includes(s)) return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      return true;
    });
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByPageDateMiner(searched.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch')),
      onHold: groupByPageDateMiner(searched.filter(r => r.status === 'Paid/DP but Item Hold')),
      paymentVerif: groupByPageDateMiner(searched.filter(r => r.status === 'Payment for Verification')),
      reseller: groupByPageDateMiner(searched.filter(r => r.status === 'Reseller')),
      outsource: groupByPageDateMiner(searched.filter(r => r.status === 'Outsource')),
      dispatched: groupByPageDateMiner(searched.filter(r => r.status === 'Dispatched')),
      delivered: groupByPageDateMiner(searched.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop')),
      cancelled: groupByPageDateMiner(searched.filter(r => r.status === 'Cancelled')),
      layaway: groupByPageDateMiner(searched.filter(r => r.status === 'Layaway')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch').length, [records]);

  const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
    Array.from(g.values()).reduce((s, dm) =>
      s + Array.from(dm.values()).reduce((ss, mm) =>
        ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

  const getPageIcon = (page: string) => {
    if (page === 'MYK') return <Crown className="h-4 w-4 text-yellow-500" />;
    if (page === 'Empire Gold By ETG') return <BookOpen className="h-4 w-4 text-primary" />;
    return <Layout className="h-4 w-4 text-muted-foreground" />;
  };

  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>, agingWarnHours = 0) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1 py-2">No items in this category.</p>;
    }
    return Array.from(groupedData.entries()).map(([page, dateMap]) => {
      const totalItems = Array.from(dateMap.values()).reduce((s, m) => s + Array.from(m.values()).reduce((ss, v) => ss + v.length, 0), 0);
      return (
        <div key={page} className="mb-4">
          <div className="flex items-center gap-2 mb-2 py-1.5 px-3 bg-secondary/40 rounded-lg border border-primary/10">
            {getPageIcon(page)}
            <h3 className="font-cinzel text-xs text-primary tracking-wide uppercase">{page}</h3>
            <div className="h-px flex-1 bg-primary/10" />
            <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
          </div>
          <div className="pl-2 sm:pl-3 space-y-1.5">
            {Array.from(dateMap.entries()).map(([date, minerMap]) => {
              const allItems = Array.from(minerMap.values()).flat();
              const maxAge = allItems.reduce((m, r) => Math.max(m, agingHours(r.dateOfLive)), 0);
              const isUrgent = agingWarnHours > 0 && maxAge >= agingWarnHours;
              const agingEl = agingWarnHours > 0 ? <AgingLabel dateStr={allItems[0]?.dateOfLive} warnAfterHours={agingWarnHours} /> : null;
              return (
                <CollapsibleGroup key={date} label={formatDate(date)} colorClass={isUrgent ? 'text-destructive' : 'text-muted-foreground'} lineClass={isUrgent ? 'bg-destructive/30' : 'bg-border/40'} indent defaultOpen={false} labelSuffix={agingEl}>
                  {Array.from(minerMap.entries()).map(([miner, items]) => (
                    <DispatchClientCard
                      key={miner}
                      minerName={miner}
                      records={items}
                      allRecords={records}
                      onUpdate={onUpdate}
                      userEmail={userEmail}
                    />
                  ))}
                </CollapsibleGroup>
              );
            })}
          </div>
        </div>
      );
    });
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <div className="flex items-center gap-2">
            {hasLayawayAlerts(records) && (
              <Button
                variant="outline"
                size="sm"
                className="border-violet-500/50 text-violet-400 text-xs h-8 relative"
                onClick={() => setShowLayawayAlert(true)}
                title="Layaway Payment Reminders"
              >
                <CreditCard className="h-3.5 w-3.5 mr-1" />
                Layaway Alerts
                <span className="absolute -top-1 -right-1 h-2.5 w-2.5 bg-destructive rounded-full animate-pulse" />
              </Button>
            )}
            <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
              <ClipboardList className="h-3.5 w-3.5 mr-1" />
              Report ({pulloutCount})
            </Button>
          </div>
        }
      />

      <div className="px-4 pt-4 space-y-1">

        <StatusSection
          icon={<Package className="h-4 w-4" />}
          label="For Pullout"
          count={countItems(forPullout)}
          colorClass="text-purple-400"
          borderClass="bg-purple-400"
          badgeClass="bg-purple-400/15 text-purple-400 border border-purple-400/20"
          open={showPullout}
          onToggle={() => setShowPullout(v => !v)}
          urgent={countItems(forPullout) > 0}
        >
          {renderGroupedRecords(forPullout)}
        </StatusSection>

        <StatusSection
          icon={<CreditCard className="h-4 w-4" />}
          label="Layaway"
          count={countItems(layaway)}
          colorClass="text-violet-400"
          borderClass="bg-violet-400"
          badgeClass="bg-violet-400/15 text-violet-400 border border-violet-400/20"
          open={showLayaway}
          onToggle={() => setShowLayaway(v => !v)}
        >
          {renderGroupedRecords(layaway)}
        </StatusSection>

        <StatusSection
          icon={<Users className="h-4 w-4" />}
          label="Reseller"
          count={countItems(reseller)}
          colorClass="text-teal-400"
          borderClass="bg-teal-400"
          badgeClass="bg-teal-400/15 text-teal-400 border border-teal-400/20"
          open={showReseller}
          onToggle={() => setShowReseller(v => !v)}
        >
          {renderGroupedRecords(reseller)}
        </StatusSection>

        <StatusSection
          icon={<Share2 className="h-4 w-4" />}
          label="Outsource"
          count={countItems(outsource)}
          colorClass="text-teal-400"
          borderClass="bg-teal-400"
          badgeClass="bg-teal-400/15 text-teal-400 border border-teal-400/20"
          open={showOutsource}
          onToggle={() => setShowOutsource(v => !v)}
        >
          {renderGroupedRecords(outsource)}
        </StatusSection>

        <StatusSection
          icon={<PauseCircle className="h-4 w-4" />}
          label="Paid/DP but On Hold"
          count={countItems(onHold)}
          colorClass="text-indigo-400"
          borderClass="bg-indigo-400"
          badgeClass="bg-indigo-400/15 text-indigo-400 border border-indigo-400/20"
          open={showHold}
          onToggle={() => setShowHold(v => !v)}
        >
          {renderGroupedRecords(onHold, 72)}
        </StatusSection>

        <StatusSection
          icon={<ShieldCheck className="h-4 w-4" />}
          label="Payment for Verification"
          count={countItems(paymentVerif)}
          colorClass="text-amber-400"
          borderClass="bg-amber-400"
          badgeClass="bg-amber-400/15 text-amber-400 border border-amber-400/20"
          open={showPaymentVerif}
          onToggle={() => setShowPaymentVerif(v => !v)}
        >
          {renderGroupedRecords(paymentVerif, 24)}
        </StatusSection>

        <StatusSection
          icon={<Truck className="h-4 w-4" />}
          label="Dispatched"
          count={countItems(dispatched)}
          colorClass="text-orange-400"
          borderClass="bg-orange-400"
          badgeClass="bg-orange-400/15 text-orange-400 border border-orange-400/20"
          open={showDispatched}
          onToggle={() => setShowDispatched(v => !v)}
        >
          {renderGroupedRecords(dispatched)}
        </StatusSection>

        <StatusSection
          icon={<CheckCircle2 className="h-4 w-4" />}
          label="Delivered"
          count={countItems(delivered)}
          colorClass="text-green-400"
          borderClass="bg-green-400"
          badgeClass="bg-green-400/15 text-green-400 border border-green-400/20"
          open={showDelivered}
          onToggle={() => setShowDelivered(v => !v)}
        >
          {renderGroupedRecords(delivered)}
        </StatusSection>

        <StatusSection
          icon={<XCircle className="h-4 w-4" />}
          label="Cancelled"
          count={countItems(cancelled)}
          colorClass="text-destructive"
          borderClass="bg-destructive"
          badgeClass="bg-destructive/15 text-destructive border border-destructive/20"
          open={showCancelled}
          onToggle={() => setShowCancelled(v => !v)}
        >
          {renderGroupedRecords(cancelled)}
        </StatusSection>

      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
      {showLayawayAlert && <LayawayPaymentAlert records={records} onClose={() => setShowLayawayAlert(false)} />}
    </div>
  );
}

