import { useMemo, useState } from 'react';
import { FileText, ChevronDown, Eye, Edit2, CheckCircle, Info, Layers } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { TabProps, DatabaseRowType } from '@/types';
import InvoiceModal from '@/components/InvoiceModal';
import { calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { toast } from 'sonner';
import TabHeader from '@/components/TabHeader';

const MOP_OPTIONS = [
  { value: 'Bank Transfer AED', label: 'Bank Transfer AED', currency: 'AED' },
  { value: 'Bank Transfer PHP', label: 'Bank Transfer PHP', currency: 'PHP' },
  { value: 'GCash', label: 'GCash', currency: 'PHP' },
  { value: 'COD (Dubai)', label: 'COD (Dubai)', currency: 'AED' },
  { value: 'COD (Abu Dhabi)', label: 'COD (Abu Dhabi)', currency: 'AED' },
  { value: 'COD (Sharjah)', label: 'COD (Sharjah)', currency: 'AED' },
  { value: 'Cash', label: 'Cash', currency: 'AED' },
  { value: 'Credit Card', label: 'Credit Card', currency: 'AED' },
  { value: 'Pick Up Shop', label: 'Pick Up Shop', currency: 'AED' },
  { value: 'Meet Up', label: 'Meet Up', currency: 'AED' },
];

function getMopCurrency(mop: string): string {
  const m = mop.toLowerCase().trim();
  if (m.includes('php') || m === 'gcash') return 'PHP';
  return 'AED';
}

function buildCustomerInvoices(records: DatabaseRowType[]) {
  const customers = new Map<string, Map<string, DatabaseRowType[]>>();
  for (const r of records) {
    const name = (r.minerName || '').trim() || 'Unknown Customer';
    const invoiceNum = String(r.pureWeight ?? '').trim() || '__no_invoice__';
    if (!customers.has(name)) customers.set(name, new Map());
    const byInvoice = customers.get(name)!;
    if (!byInvoice.has(invoiceNum)) byInvoice.set(invoiceNum, []);
    byInvoice.get(invoiceNum)!.push(r);
  }
  return new Map([...customers.entries()].sort((a, b) => a[0].localeCompare(b[0])));
}

// ─── Edit Downpayment Dialog ──────────────────────────────────────────────────
interface EditDownpaymentDialogProps {
  records: DatabaseRowType[];
  invoiceNum: string;
  onUpdate: TabProps['onUpdate'];
  onClose: () => void;
}

function EditDownpaymentDialog({ records, invoiceNum, onUpdate, onClose }: EditDownpaymentDialogProps) {
  const [values, setValues] = useState<Record<number, string>>(
    Object.fromEntries(records.map(r => [r.id, String(r.downpayment ?? '')]))
  );
  const [mops, setMops] = useState<Record<number, string>>(
    Object.fromEntries(records.map(r => [r.id, r.modeOfPayment || 'Bank Transfer AED']))
  );
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    setSaving(true);
    try {
      for (const r of records) {
        const newDp = values[r.id];
        const newMop = mops[r.id];
        const dpChanged = newDp !== String(r.downpayment ?? '');
        const mopChanged = newMop !== (r.modeOfPayment || '');
        if (dpChanged || mopChanged) {
          const fields: Partial<DatabaseRowType> = {};
          if (dpChanged) fields.downpayment = newDp;
          if (mopChanged) fields.modeOfPayment = newMop;
          await onUpdate(r.id, fields);
        }
      }
      toast.success('Downpayment updated');
      onClose();
    } catch {
      toast.error('Failed to update downpayment');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg bg-background border-border" aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle className="text-sm font-bold font-cinzel">
            Edit Downpayment — Invoice {invoiceNum === '__no_invoice__' ? 'N/A' : invoiceNum}
          </DialogTitle>
        </DialogHeader>

        <div className="flex items-start gap-2 text-[10px] text-muted-foreground bg-primary/5 rounded-md px-3 py-2 mb-2 border border-primary/20">
          <Info className="h-3 w-3 mt-0.5 shrink-0 text-primary" />
          <span>Set the <strong>Mode of Payment</strong> so the system knows the DP currency (AED vs PHP).</span>
        </div>

        <div className="space-y-4 mt-1 max-h-80 overflow-y-auto pr-1">
          {records.map(r => {
            const currentMop = mops[r.id] || 'Bank Transfer AED';
            const dpCurr = getMopCurrency(currentMop);
            return (
              <div key={r.id} className="rounded-lg border border-border bg-card p-3 space-y-2">
                <p className="text-xs font-semibold text-foreground truncate">{r.itemDescription || '—'}</p>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground w-24 shrink-0">Mode of Payment</span>
                  <Select value={currentMop} onValueChange={val => setMops(prev => ({ ...prev, [r.id]: val }))}>
                    <SelectTrigger className="h-7 text-xs flex-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {MOP_OPTIONS.map(opt => (
                        <SelectItem key={opt.value} value={opt.value}>
                          <span className="flex items-center gap-2">
                            {opt.label}
                            <span className={`text-[9px] font-bold px-1 rounded ${opt.currency === 'PHP' ? 'bg-green-500/20 text-green-500' : 'bg-primary/20 text-primary'}`}>
                              {opt.currency}
                            </span>
                          </span>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground w-24 shrink-0">Downpayment</span>
                  <div className="flex items-center gap-2 flex-1">
                    <Input
                      type="number"
                      value={values[r.id]}
                      onChange={e => setValues(prev => ({ ...prev, [r.id]: e.target.value }))}
                      className="h-7 text-xs flex-1"
                      placeholder="0"
                    />
                    <Badge variant="outline" className={`text-[9px] font-bold shrink-0 ${dpCurr === 'PHP' ? 'border-green-500/40 text-green-500' : 'border-primary/40 text-primary'}`}>
                      {dpCurr}
                    </Badge>
                  </div>
                </div>
                <div className="text-[9px] text-muted-foreground">Current: DP={String(r.downpayment || '0')} · MOP={r.modeOfPayment || '—'}</div>
              </div>
            );
          })}
        </div>

        <div className="flex gap-2 pt-2 justify-end">
          <Button variant="outline" size="sm" className="h-7 text-xs" onClick={onClose}>Cancel</Button>
          <Button size="sm" className="h-7 text-xs bg-primary text-primary-foreground" onClick={handleSave} disabled={saving}>
            <CheckCircle className="h-3 w-3 mr-1" />
            {saving ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// ─── Invoice Row ──────────────────────────────────────────────────────────────
interface InvoiceRowProps {
  invoiceNum: string;
  records: DatabaseRowType[];
  onUpdate: TabProps['onUpdate'];
}

function InvoiceRow({ invoiceNum, records, onUpdate }: InvoiceRowProps) {
  const [showModal, setShowModal] = useState(false);
  const [showEdit, setShowEdit] = useState(false);

  const displayNum = invoiceNum === '__no_invoice__' ? '—' : invoiceNum;
  const dates = records.map(r => r.dateOfLive).filter(Boolean) as string[];
  const firstDate = dates.length > 0 ? formatDate(dates[0]) : '—';
  const totalBalance = records.reduce((s, r) => s + calcRemainingBalance(r), 0);
  const totalItems = records.length;
  const statuses = [...new Set(records.map(r => r.status || ''))];
  const isPaid = totalBalance <= 0;

  return (
    <>
      <div className="flex items-center gap-2 py-2.5 px-3 rounded-lg border border-border/60 bg-secondary/10 hover:bg-secondary/20 transition-colors">
        <FileText className="h-3.5 w-3.5 text-primary/60 shrink-0" />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-xs font-bold text-foreground font-mono">#{displayNum}</span>
            <span className="text-[10px] text-muted-foreground">{firstDate}</span>
            <span className="text-[10px] bg-muted/60 text-muted-foreground px-1.5 py-0.5 rounded-full">{totalItems} item{totalItems !== 1 ? 's' : ''}</span>
          </div>
          <div className="flex items-center gap-2 mt-0.5 flex-wrap">
            {statuses.slice(0, 2).map(s => (
              <span key={s} className="text-[9px] text-muted-foreground/70">{s}</span>
            ))}
            <span className={`text-[10px] font-semibold ml-auto ${isPaid ? 'text-green-500' : 'text-destructive'}`}>
              {isPaid ? '✓ Paid' : `Balance: ${Math.round(totalBalance).toLocaleString()}`}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-0.5 shrink-0">
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-primary" onClick={() => setShowEdit(true)} title="Edit downpayment">
            <Edit2 className="h-3.5 w-3.5" />
          </Button>
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-primary" onClick={() => setShowModal(true)} title="View invoice">
            <Eye className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>

      {showModal && <InvoiceModal records={records} onClose={() => setShowModal(false)} />}
      {showEdit && (
        <EditDownpaymentDialog records={records} invoiceNum={invoiceNum} onUpdate={onUpdate} onClose={() => setShowEdit(false)} />
      )}
    </>
  );
}

// ─── Customer Card ────────────────────────────────────────────────────────────
interface CustomerCardProps {
  minerName: string;
  invoiceGroups: Map<string, DatabaseRowType[]>;
  onUpdate: TabProps['onUpdate'];
}

function CustomerCard({ minerName, invoiceGroups, onUpdate }: CustomerCardProps) {
  const [expanded, setExpanded] = useState(false);
  const [showAllModal, setShowAllModal] = useState(false);
  const totalInvoices = invoiceGroups.size;
  const allRecords = useMemo(() => [...invoiceGroups.values()].flat(), [invoiceGroups]);
  const totalItems = allRecords.length;
  const totalBalance = allRecords.reduce((s, r) => s + calcRemainingBalance(r), 0);
  const isPaid = totalBalance <= 0;

  return (
    <div className="mb-2 rounded-xl border border-border bg-card overflow-hidden">
      <div className="flex items-center gap-2 px-4 py-3">
        <button
          onClick={() => setExpanded(e => !e)}
          className="flex-1 flex items-center justify-between gap-3 text-left min-w-0"
        >
          <div className="min-w-0">
            <p className="text-sm font-bold text-foreground font-cinzel truncate">{minerName}</p>
            <p className="text-[10px] text-muted-foreground mt-0.5">
              {totalInvoices} invoice{totalInvoices !== 1 ? 's' : ''} · {totalItems} items
            </p>
          </div>
          <span className={`text-xs font-bold shrink-0 px-2 py-0.5 rounded-full border ${isPaid
            ? 'text-green-500 border-green-500/30 bg-green-500/10'
            : 'text-destructive border-destructive/30 bg-destructive/10'}`}>
            {isPaid ? 'Paid' : `Balance: ${Math.round(totalBalance).toLocaleString()}`}
          </span>
        </button>
        <Button
          variant="ghost"
          size="sm"
          className="h-7 px-2 text-[10px] text-primary hover:bg-primary/10 shrink-0 gap-1"
          onClick={e => { e.stopPropagation(); setShowAllModal(true); }}
          title="View all items in one invoice"
        >
          <Layers className="h-3.5 w-3.5" />
          View All
        </Button>
        <button onClick={() => setExpanded(e => !e)} className="shrink-0 p-1">
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`} />
        </button>
      </div>

      {expanded && (
        <div className="px-3 pb-3 space-y-1.5 border-t border-border pt-2 animate-in fade-in slide-in-from-top-1 duration-200">
          {[...invoiceGroups.entries()].map(([invoiceNum, recs]) => (
            <InvoiceRow key={invoiceNum} invoiceNum={invoiceNum} records={recs} onUpdate={onUpdate} />
          ))}
        </div>
      )}

      {showAllModal && <InvoiceModal records={allRecords} onClose={() => setShowAllModal(false)} />}
    </div>
  );
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function InvoicingTab({ records, onUpdate }: TabProps) {
  const [search, setSearch] = useState('');

  const customerMap = useMemo(() => {
    const EXCLUDED = new Set(['Cancelled', 'Returned Item']);
    const nonCancelled = records.filter(r => !EXCLUDED.has(r.status || ''));
    const filtered = search.trim()
      ? nonCancelled.filter(r =>
          (r.minerName || '').toLowerCase().includes(search.toLowerCase()) ||
          String(r.pureWeight ?? '').toLowerCase().includes(search.toLowerCase()) ||
          (r.itemDescription || '').toLowerCase().includes(search.toLowerCase())
        )
      : nonCancelled;
    return buildCustomerInvoices(filtered);
  }, [records, search]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Invoicing"
        subtitle={`${customerMap.size} customers`}
        searchQuery={search}
        onSearchChange={setSearch}
      />

      <div className="px-4 pt-4">
        {customerMap.size === 0 ? (
          <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
            <FileText className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
            <p className="text-sm text-muted-foreground font-medium">No customers found.</p>
          </div>
        ) : (
          [...customerMap.entries()].map(([name, invoiceGroups]) => (
            <CustomerCard key={name} minerName={name} invoiceGroups={invoiceGroups} onUpdate={onUpdate} />
          ))
        )}
      </div>
    </div>
  );
}

src/components/accounts/AddClientModal.t.content:
import { useState, useMemo } from 'react';
import { Loader2, CopyPlus, AlertTriangle, Info } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { createRecord } from 'zite-endpoints-sdk';
import { MOP_OPTIONS, REGION_OPTIONS, normalizeMinerName } from '@/lib/formatters';
import { calcItemCostAED, calcItemPriceAED } from '@/lib/calculations';
import {
  getRatesForDate, saveRatesForDate,
  DEFAULT_PHP_RATE, DEFAULT_SILVER_SELL_RATE, DEFAULT_SILVER_BRANDED_SELL_RATE,
  DEFAULT_SILVER_COST_RATE, DEFAULT_SILVER_BRANDED_COST_RATE,
} from '@/lib/ratesStore';
import { DatabaseRowType } from '@/types';

function generateCustomerId(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let id = 'CUST-';
  for (let i = 0; i < 5; i++) id += chars[Math.floor(Math.random() * chars.length)];
  return id;
}

function resolveCustomerId(minerName: string, existingRecords: DatabaseRowType[]): string {
  // Normalize input name for comparison (Title Case, collapsed spaces)
  const normalized = normalizeMinerName(minerName).toLowerCase();
  // Also try matching on first + last name only (strip middle name) for fuzzy dedup
  const nameParts = normalized.split(' ').filter(Boolean);
  const firstLast = nameParts.length >= 2 ? `${nameParts[0]} ${nameParts[nameParts.length - 1]}` : normalized;

  const match = existingRecords.find(r => {
    if (!r.customerId) return false;
    const existing = normalizeMinerName(r.minerName || '').toLowerCase();
    if (existing === normalized) return true;
    // Fuzzy: match if first+last name matches (handles middle name variations)
    const existingParts = existing.split(' ').filter(Boolean);
    const existingFirstLast = existingParts.length >= 2
      ? `${existingParts[0]} ${existingParts[existingParts.length - 1]}`
      : existing;
    return existingFirstLast === firstLast;
  });
  return match?.customerId || generateCustomerId();
}

interface Props {
  onClose: () => void;
  userFirstName?: string;
  userEmail?: string;
  onRefresh?: () => void;
  existingRecords?: DatabaseRowType[];
}

const LOCATION_OPTIONS = ['Local', 'Pinas', 'International'];
const CURRENCY_OPTIONS = ['AED', 'PHP', 'USD'];
const STATUS_OPTIONS = ['Pending', 'Waiting for Details', 'Paid/DP but Item Hold', 'Payment for Verification', 'Reseller', 'Walk-in', 'In-Store'];
const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash', 'Secured via Tabby', 'Secured via Tamara'];
const CATEGORY_OPTIONS = ['Normal', 'Special Price', 'Special Price EF', 'Silver', 'Silver Branded', 'VCA', 'Per PC', 'Diamond', 'Other'];
const PAGE_OPTIONS = ['MYK', 'EMPIRE GOLD BY ETG'];
const TOG_OPTIONS = ['S-925', '18K', '21K', '24K'];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store', 'Offline', 'Reseller'];
const SOURCE_OPTIONS = ['MYK SHOP', 'CROWN', 'DG', 'MSET SHOP', 'SATWA OFFICE', 'UMAAR SUPPLIER'];

export default function AddClientModal({ onClose, userFirstName, userEmail, onRefresh, existingRecords = [] }: Props) {
  const [saving, setSaving] = useState(false);
  const today = new Date().toISOString().split('T')[0];
  const todayRates = getRatesForDate(today);
  const [phpRate, setPhpRate] = useState(() => String(todayRates.phpRate));
  const [silverSellRate, setSilverSellRateVal] = useState(() => String(todayRates.silverSellRate));
  const [silverBrandedSellRate, setSilverBrandedSellRateVal] = useState(() => String(todayRates.silverBrandedSellRate));
  const [silverCostRate, setSilverCostRateVal] = useState(() => String(todayRates.silverCostRate));
  const [silverBrandedCostRate, setSilverBrandedCostRateVal] = useState(() => String(todayRates.silverBrandedCostRate));
  const [form, setForm] = useState({
    minerName: '',
    itemDescription: '',
    category: '',
    mc: '',
    grams: '',
    clientRate: '',
    goldRate: '',
    orderId: '',
    currency: 'AED',
    modeOfPayment: '',
    modeOfSale: '',
    source: '',
    locationOfMiner: 'Local',
    regions: '',
    status: 'Walk-in',
    remittanceStatus: 'Pending Payment',
    dateOfLive: new Date().toISOString().split('T')[0],
    liverName: userFirstName || '',
    page: '',
    tog: '',
    supplierRateOverride: '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  const isManualSupplierRate = form.category === 'Diamond' || form.category === 'Per PC';
  const autoSupplierRate = useMemo(() => {
    const gr = parseFloat(form.goldRate) || 0;
    const mc = parseFloat(form.mc) || 0;
    return gr > 0 || mc > 0 ? (gr + mc).toFixed(2) : '';
  }, [form.goldRate, form.mc]);
  const supplierRate = isManualSupplierRate ? form.supplierRateOverride : autoSupplierRate;

  const getPerPcSupplierRate = (tog: string, category: string) => {
    if (category === 'Per PC') {
      if (tog === 'S-925') return '32';
      return '115';
    }
    return '';
  };

  const handleCategoryChange = (val: string) => {
    let newMc = form.mc;
    let newGoldRate = form.goldRate;
    let newSupplierRateOverride = form.supplierRateOverride;

    if (val === 'Normal') newMc = '16';
    else if (val === 'Special Price') newMc = '21';
    else if (val === 'Special Price EF') newMc = '25';
    else if (val === 'Silver' || val === 'Silver Branded') newMc = '0';
    else if (val === 'Diamond') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = '';
    } else if (val === 'Per PC') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = getPerPcSupplierRate(form.tog, val);
    }
    setForm(p => ({ ...p, category: val, mc: newMc, goldRate: newGoldRate, supplierRateOverride: newSupplierRateOverride }));
  };

  const handleTogChange = (val: string) => {
    const updates: Partial<typeof form> = { tog: val };
    if (form.category === 'Per PC') {
      updates.supplierRateOverride = getPerPcSupplierRate(val, 'Per PC');
    }
    setForm(p => ({ ...p, ...updates }));
  };

  const isDuplicateBarcode = useMemo(() => {
    if (!form.orderId.trim()) return false;
    const target = form.orderId.trim().toUpperCase();
    return existingRecords.some(r => r.orderId?.trim().toUpperCase() === target);
  }, [form.orderId, existingRecords]);

  // Fuzzy duplicate name detection: warn if a client with same first+last name already exists
  const duplicateNameWarning = useMemo(() => {
    if (!form.minerName.trim()) return null;
    const normalized = normalizeMinerName(form.minerName).toLowerCase();
    const parts = normalized.split(' ').filter(Boolean);
    const firstLast = parts.length >= 2 ? `${parts[0]} ${parts[parts.length - 1]}` : normalized;
    const matches = existingRecords.filter(r => {
      if (!r.minerName) return false;
      const existing = normalizeMinerName(r.minerName).toLowerCase();
      if (existing === normalized) return true;
      const ep = existing.split(' ').filter(Boolean);
      const efl = ep.length >= 2 ? `${ep[0]} ${ep[ep.length - 1]}` : existing;
      return efl === firstLast;
    });
    if (matches.length === 0) return null;
    const uniqueNames = [...new Set(matches.map(r => normalizeMinerName(r.minerName || '')))];
    return `Similar client already exists: ${uniqueNames.slice(0, 2).join(', ')}${uniqueNames.length > 2 ? ` (+${uniqueNames.length - 2} more)` : ''}`;
  }, [form.minerName, existingRecords]);

  const handleSave = async (isBulkAdd: boolean) => {
    if (!form.minerName.trim() || !form.itemDescription.trim()) {
      toast.error('Client name and item description are required');
      return;
    }
    if (!form.page) {
      toast.error('Page is required');
      return;
    }
    if (isDuplicateBarcode) {
      toast.error('Cannot save: This Order ID/Barcode already exists in the system.');
      return;
    }

    setSaving(true);

    const finalMinerName = normalizeMinerName(form.minerName);
    const finalItemDesc = form.itemDescription.trim().toUpperCase();
    const finalOrderId = form.orderId ? form.orderId.trim().toUpperCase() : undefined;

    try {
      const preview: DatabaseRowType = {
        id: 0,
        minerName: finalMinerName,
        itemDescription: finalItemDesc,
        category: form.category,
        mc: form.mc,
        grams: form.grams ? parseFloat(form.grams) : undefined,
        clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
        goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
        supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
        currency: form.currency,
        tog: form.tog || undefined,
      };

      const profit = (calcItemPriceAED(preview) - calcItemCostAED(preview)).toFixed(2);

      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const creator = userEmail ? userEmail.split('@')[0] : (form.liverName || 'unknown');
      const auditTrail = `[Created by ${creator} on ${timestamp}]`;
      const customerId = resolveCustomerId(finalMinerName, existingRecords);

      const safePhpRate = parseFloat(phpRate) > 0 ? parseFloat(phpRate) : DEFAULT_PHP_RATE;
      const safeSilverSell = parseFloat(silverSellRate) > 0 ? parseFloat(silverSellRate) : DEFAULT_SILVER_SELL_RATE;
      const safeSilverBrandedSell = parseFloat(silverBrandedSellRate) > 0 ? parseFloat(silverBrandedSellRate) : DEFAULT_SILVER_BRANDED_SELL_RATE;
      const safeSilverCost = parseFloat(silverCostRate) > 0 ? parseFloat(silverCostRate) : DEFAULT_SILVER_COST_RATE;
      const safeSilverBrandedCost = parseFloat(silverBrandedCostRate) > 0 ? parseFloat(silverBrandedCostRate) : DEFAULT_SILVER_BRANDED_COST_RATE;

      await createRecord({
        phpRate: safePhpRate,
        silverSellRate: safeSilverSell,
        silverBrandedSellRate: safeSilverBrandedSell,
        silverCostRate: safeSilverCost,
        silverBrandedCostRate: safeSilverBrandedCost,
        fields: {
          minerName: finalMinerName,
          itemDescription: finalItemDesc,
          category: form.category,
          orderId: finalOrderId,
          mc: form.mc ? parseFloat(form.mc) : undefined,
          grams: form.grams ? parseFloat(form.grams) : undefined,
          clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
          goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
          supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
          pureWeight: undefined,
          currency: form.currency,
          modeOfPayment: form.modeOfPayment || undefined,
          modeOfSale: form.modeOfSale || undefined,
          source: form.source || undefined,
          locationOfMiner: form.locationOfMiner,
          regions: form.regions || undefined,
          status: form.status,
          remittanceStatus: form.remittanceStatus,
          dateOfLive: form.dateOfLive,
          liverName: form.liverName || undefined,
          page: form.page,
          tog: form.tog || undefined,
          reviewChasing: 'Pending',
          profit,
          auditTrail,
          customerId,
        },
      });
      // Persist the full rate snapshot for this date (historical rate locking)
      saveRatesForDate(form.dateOfLive, {
        phpRate: safePhpRate,
        silverSellRate: safeSilverSell,
        silverBrandedSellRate: safeSilverBrandedSell,
        silverCostRate: safeSilverCost,
        silverBrandedCostRate: safeSilverBrandedCost,
      });

      toast.success(isBulkAdd ? 'Item added! Ready for next item.' : 'Client record created');
      onRefresh?.();

      if (isBulkAdd) {
        setForm(p => ({ 
          ...p, 
          itemDescription: '', 
          grams: '', 
          orderId: '', 
          tog: '', 
          category: '', 
          mc: '', 
          goldRate: '', 
          clientRate: '', 
          supplierRateOverride: '' 
        }));
      } else {
        onClose();
      }

    } catch {
      toast.error('Failed to create record');
    } finally {
      setSaving(false);
    }
  };

  const isPinas = form.locationOfMiner === 'Pinas';

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-md bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Add Client Record</DialogTitle>
        </DialogHeader>

        <div className="space-y-3 text-sm">
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Client Name *</Label>
              <Input
                value={form.minerName}
                onChange={e => set('minerName', e.target.value)}
                onBlur={e => set('minerName', normalizeMinerName(e.target.value))}
                className="h-8 text-xs mt-0.5 bg-background border-border"
                placeholder="e.g. Estella Jimenez"
              />
              {duplicateNameWarning && (
                <div className="flex items-start gap-1 mt-1 text-[10px] text-yellow-500 bg-yellow-500/10 border border-yellow-500/20 rounded px-2 py-1">
                  <Info className="w-3 h-3 mt-0.5 shrink-0" />
                  <span>{duplicateNameWarning} — continuing will link to same Customer ID.</span>
                </div>
              )}
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Item Description *</Label>
              <Input value={form.itemDescription} onChange={e => set('itemDescription', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border uppercase" placeholder="e.g. GOLD RING 18K" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Page *</Label>
              <Select value={form.page} onValueChange={v => set('page', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {PAGE_OPTIONS.map(p => <SelectItem key={p} value={p} className="text-xs">{p}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Liver Name</Label>
              <Input value={form.liverName} onChange={e => set('liverName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Liver name" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Category</Label>
              <Select value={form.category} onValueChange={handleCategoryChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CATEGORY_OPTIONS.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">T.O.G</Label>
              <Select value={form.tog} onValueChange={handleTogChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {TOG_OPTIONS.map(t => <SelectItem key={t} value={t} className="text-xs">{t}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div className="col-span-2">
              <div className="flex items-center justify-between mb-0.5">
                <Label className="text-xs text-muted-foreground">Order ID / Barcode</Label>
                {isDuplicateBarcode && (
                  <span className="text-[10px] font-bold text-destructive flex items-center animate-pulse">
                    <AlertTriangle className="w-3 h-3 mr-1" /> ALREADY EXISTS
                  </span>
                )}
              </div>
              <Input 
                value={form.orderId} 
                onChange={e => set('orderId', e.target.value.toUpperCase())} 
                className={`h-8 text-xs bg-background uppercase transition-colors ${isDuplicateBarcode ? 'border-destructive focus-visible:ring-destructive' : 'border-border'}`} 
                placeholder="e.g. AM-SL-030909" 
              />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Grams (0 = PC)</Label>
              <Input type="number" value={form.grams} onChange={e => set('grams', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">MC (Making Charge)</Label>
              <Input type="number" value={form.mc} onChange={e => set('mc', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Gold Rate</Label>
              <Input type="number" value={form.goldRate} onChange={e => set('goldRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Client Rate</Label>
              <Input type="number" value={form.clientRate} onChange={e => set('clientRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">
                Supplier Rate
              </Label>
              {isManualSupplierRate ? (
                <Input
                  type="number"
                  value={form.supplierRateOverride}
                  onChange={e => set('supplierRateOverride', e.target.value)}
                  className="h-8 text-xs mt-0.5 bg-background border-border"
                  placeholder={form.category === 'Diamond' ? 'Enter supplier rate' : '115'}
                />
              ) : (
                <Input value={supplierRate} readOnly className="h-8 text-xs mt-0.5 bg-muted border-border opacity-70 cursor-not-allowed" placeholder="Auto" />
              )}
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Currency</Label>
              <Select value={form.currency} onValueChange={v => set('currency', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CURRENCY_OPTIONS.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Mode of Sale</Label>
              <Select value={form.modeOfSale} onValueChange={v => set('modeOfSale', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {MODE_OF_SALE_OPTIONS.map(m => <SelectItem key={m} value={m} className="text-xs">{m}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Source</Label>
              <Select value={form.source} onValueChange={v => set('source', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {SOURCE_OPTIONS.map(s => <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Location</Label>
              <Select value={form.locationOfMiner} onValueChange={v => {
                set('locationOfMiner', v);
                if (v === 'Pinas') set('currency', 'PHP');
                else if (v === 'Local') set('currency', 'AED');
              }}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {LOCATION_OPTIONS.map(l => <SelectItem key={l} value={l} className="text-xs">{l}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            {isPinas && (
              <div className="col-span-2 bg-primary/10 border border-primary/20 rounded-lg p-2">
                <Label className="text-xs text-primary font-semibold">PHP Conversion Rate (AED → PHP)</Label>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-xs text-muted-foreground">1 AED =</span>
                  <Input
                    type="number"
                    value={phpRate}
                    onChange={e => setPhpRate(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24"
                    step="0.1"
                  />
                  <span className="text-xs text-muted-foreground">PHP</span>
                </div>
              </div>
            )}

            {(form.category === 'Silver' || form.category === 'Silver Branded') && (
              <div className="col-span-2 bg-secondary/40 border border-border rounded-lg p-2 space-y-2">
                <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">
                  Daily Silver Rates — {form.category}
                </p>
                {form.category === 'Silver' ? (
                  <>
                    <div className="flex items-center gap-2">
                      <Label className="text-xs text-muted-foreground w-28 shrink-0">Sell Rate (AED/g)</Label>
                      <Input type="number" step="0.5" value={silverSellRate}
                        onChange={e => setSilverSellRateVal(e.target.value)}
                        className="h-7 text-xs bg-background border-border w-20" placeholder="45" />
                      <span className="text-[10px] text-muted-foreground">default: 45</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Label className="text-xs text-muted-foreground w-28 shrink-0">Cost Rate (AED/g)</Label>
                      <Input type="number" step="0.5" value={silverCostRate}
                        onChange={e => setSilverCostRateVal(e.target.value)}
                        className="h-7 text-xs bg-background border-border w-20" placeholder="15" />
                      <span className="text-[10px] text-muted-foreground">default: 15</span>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="flex items-center gap-2">
                      <Label className="text-xs text-muted-foreground w-28 shrink-0">Sell Rate (AED/g)</Label>
                      <Input type="number" step="0.5" value={silverBrandedSellRate}
                        onChange={e => setSilverBrandedSellRateVal(e.target.value)}
                        className="h-7 text-xs bg-background border-border w-20" placeholder="60" />
                      <span className="text-[10px] text-muted-foreground">default: 60</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Label className="text-xs text-muted-foreground w-28 shrink-0">Cost Rate (AED/g)</Label>
                      <Input type="number" step="0.5" value={silverBrandedCostRate}
                        onChange={e => setSilverBrandedCostRateVal(e.target.value)}
                        className="h-7 text-xs bg-background border-border w-20" placeholder="32" />
                      <span className="text-[10px] text-muted-foreground">default: 32</span>
                    </div>
                  </>
                )}
              </div>
            )}

            {form.locationOfMiner === 'Local' && (
              <div>
                <Label className="text-xs text-muted-foreground">Region</Label>
                <Select value={form.regions} onValueChange={v => set('regions', v)}>
                  <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                  <SelectContent className="bg-popover border-border">
                    {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div>
              <Label className="text-xs text-muted-foreground">Mode of Payment</Label>
              <Select value={form.modeOfPayment} onValueChange={v => set('modeOfPayment', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {MOP_OPTIONS.map(m => <SelectItem key={m} value={m} className="text-xs">{m}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Status</Label>
              <Select value={form.status} onValueChange={v => set('status', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {STATUS_OPTIONS.map(s => <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Remittance Status</Label>
              <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {REMITTANCE_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Date of Live</Label>
              <Input type="date" value={form.dateOfLive} onChange={e => set('dateOfLive', e.target.value)} max={today} className="h-8 text-xs mt-0.5 bg-background border-border" />
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <Button variant="outline" className="text-xs h-8 border-border w-20 shrink-0" onClick={onClose}>
              Cancel
            </Button>
            <Button onClick={() => handleSave(true)} disabled={saving || isDuplicateBarcode} variant="secondary" className="flex-1 text-xs h-8 border-border">
              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <><CopyPlus className="h-3.5 w-3.5 mr-1" /> Save & Add Another</>}
            </Button>
            <Button onClick={() => handleSave(false)} disabled={saving || isDuplicateBarcode} className="flex-1 text-xs h-8 bg-primary text-primary-foreground">
              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Create Record'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

src/components/accounts/FinancialsForm.t.content:
import { useState, useEffect } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import {
  calcItemPrice, calcItemPriceAED, calcShippingFee, calcCCFee,
  calcTotalPaid, calcProfitAED, roundPrice, getEffectiveCurrency,
  toAED, fromAED, calcRemainingBalance, resolveDownpaymentCurrencyAED
} from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

const REMITTANCE_OPTIONS = [
  'Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer',
  'Secured via Cash', 'SECURED VIA TABBY', 'SECURED VIA TAMARA',
];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store'];

export default function FinancialsForm({ record, onUpdate }: Props) {
  const [saving, setSaving] = useState(false);
  const isLayaway = record.modeOfPayment === 'Layaway';

  const currency = getEffectiveCurrency(record);

  const [form, setForm] = useState({
    goldRate: record.goldRate?.toString() || '',
    mc: record.mc || '',
    supplierRate: record.supplierRate || '',
    additionalCharges: record.additionalCharges || '',
    additionalFeeRemarks: record.liverAdminRemarks || '',
    downpayment: String(record.downpayment || ''),
    amountReceived: String(record.amountReceived || ''),
    la1MonthPayment: String(record.la1MonthPayment || ''),
    la2MonthPayment: String(record.la2MonthPayment || ''),
    la3MonthPayment: String(record.la3MonthPayment || ''),
    la4MonthPayment: String(record.la4MonthPayment || ''),
    remittanceStatus: record.remittanceStatus || '',
    modeOfSale: record.modeOfSale || '',
  });

  useEffect(() => {
    setForm({
      goldRate: record.goldRate?.toString() || '',
      mc: record.mc || '',
      supplierRate: record.supplierRate || '',
      additionalCharges: record.additionalCharges || '',
      additionalFeeRemarks: record.liverAdminRemarks || '',
      downpayment: String(record.downpayment || ''),
      amountReceived: String(record.amountReceived || ''),
      la1MonthPayment: String(record.la1MonthPayment || ''),
      la2MonthPayment: String(record.la2MonthPayment || ''),
      la3MonthPayment: String(record.la3MonthPayment || ''),
      la4MonthPayment: String(record.la4MonthPayment || ''),
      remittanceStatus: record.remittanceStatus || '',
      modeOfSale: record.modeOfSale || '',
    });
  }, [record.id]);

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  const toDisplay = (val: unknown): string => {
    const num = parseFloat(String(val ?? '')) || 0;
    if (!num) return '';
    return String(Math.round(toAED(num, record) * 100) / 100);
  };
  const fromDisplay = (aedStr: string): string => {
    const num = parseFloat(aedStr) || 0;
    if (!num) return '';
    return String(Math.round(fromAED(num, record) * 100) / 100);
  };

  const buildPreview = (): DatabaseRowType => ({
    ...record,
    goldRate: parseFloat(form.goldRate) || record.goldRate,
    supplierRate: form.supplierRate,
    mc: form.mc,
    additionalCharges: form.additionalCharges,
    downpayment: form.downpayment,
    amountReceived: form.amountReceived,
    la1MonthPayment: isLayaway ? form.la1MonthPayment : '',
    la2MonthPayment: isLayaway ? form.la2MonthPayment : '',
    la3MonthPayment: isLayaway ? form.la3MonthPayment : '',
    la4MonthPayment: isLayaway ? form.la4MonthPayment : '',
  });

  const handlePayFull = () => {
    const preview = buildPreview();
    preview.amountReceived = ''; 
    const remainingAED = calcRemainingBalance(preview); 

    if (remainingAED > 0) {
        set('amountReceived', String(fromAED(remainingAED, record)));
        toast.success(`Auto-filled full balance!`);
    } else {
        toast.info('Balance is already fully paid!');
    }
  };

  const handleSave = async () => {
    // Layaway validation: sum of installments must not exceed (total - DP)
    if (isLayaway) {
      const preview = buildPreview();
      const totalAED = calcItemPriceAED(preview) + calcShippingFee(preview) + calcCCFee(preview) + (parseFloat(form.additionalCharges) || 0);
      const dpAED = resolveDownpaymentCurrencyAED(parseFloat(form.downpayment) || 0, record);
      const maxLayawayAED = totalAED - dpAED;
      const layawayRaw = [form.la1MonthPayment, form.la2MonthPayment, form.la3MonthPayment, form.la4MonthPayment]
        .reduce((s, v) => s + (parseFloat(v) || 0), 0);
      const layawayAED = toAED(layawayRaw, record);
      if (layawayAED > maxLayawayAED + 0.01) {
        toast.error(`Layaway total (AED ${layawayAED.toFixed(2)}) exceeds remaining balance (AED ${maxLayawayAED.toFixed(2)}). Please reduce the installment amounts.`);
        return;
      }
    }

    setSaving(true);
    try {
      const previewRecord = buildPreview();
      const computedProfit = calcProfitAED(previewRecord).toFixed(2);

      // Pass the record's dateOfLive so handleUpdate in App.tsx uses the correct historical rates
      await onUpdate(record.id, {
        dateOfLive: record.dateOfLive, // carry dateOfLive so App.tsx can look up locked rates
        goldRate: parseFloat(form.goldRate) || record.goldRate,
        supplierRate: form.supplierRate,
        mc: form.mc,
        additionalCharges: form.additionalCharges,
        liverAdminRemarks: form.additionalFeeRemarks,
        downpayment: form.downpayment,
        amountReceived: form.amountReceived,
        la1MonthPayment: isLayaway ? form.la1MonthPayment : '',
        la2MonthPayment: isLayaway ? form.la2MonthPayment : '',
        la3MonthPayment: isLayaway ? form.la3MonthPayment : '',
        la4MonthPayment: isLayaway ? form.la4MonthPayment : '',
        remittanceStatus: form.remittanceStatus,
        modeOfSale: form.modeOfSale,
        profit: computedProfit,
      });
      toast.success('Financials saved');
    } finally {
      setSaving(false);
    }
  };

  const previewRecord = buildPreview();
  const itemPrice = calcItemPrice(previewRecord);
  const itemPriceAED = calcItemPriceAED(previewRecord);
  const shippingFee = calcShippingFee(previewRecord);
  const ccFee = calcCCFee(previewRecord);
  const additionalAED = parseFloat(form.additionalCharges) || 0;
  const totalAmount = roundPrice(itemPriceAED + shippingFee + ccFee + additionalAED);
  const totalPaid = calcTotalPaid(previewRecord);
  const remaining = roundPrice(totalAmount - totalPaid);
  const profitAED = calcProfitAED(previewRecord);

  const numField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input type="number" value={form[key as keyof typeof form]} onChange={e => set(key, e.target.value)}
        disabled={disabled} className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50" placeholder="0.00" />
    </div>
  );

  const paymentField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input
        type="number"
        value={toDisplay(form[key as keyof typeof form])}
        onChange={e => set(key, fromDisplay(e.target.value))}
        disabled={disabled}
        className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50"
        placeholder="0.00"
      />
    </div>
  );

  return (
    <div className="border-t border-border pt-3 mt-2">
      <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wide">Financials</p>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Mode of Sale</Label>
        <Select value={form.modeOfSale} onValueChange={v => set('modeOfSale', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select mode of sale..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {MODE_OF_SALE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        {numField('Gold Rate', 'goldRate')}
        {numField('MC (Making Charge)', 'mc')}
        <div>
          <Label className="text-xs text-muted-foreground">Supplier Rate</Label>
          <Input type="number" value={form.supplierRate} onChange={e => set('supplierRate', e.target.value)}
            className="h-8 text-xs bg-background border-border mt-0.5" placeholder="0.00" />
        </div>
        {numField('Additional Fees (AED)', 'additionalCharges')}
      </div>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Additional Fee Remarks <span className="text-primary/60">(Col X)</span></Label>
        <Textarea value={form.additionalFeeRemarks} onChange={e => set('additionalFeeRemarks', e.target.value)}
          className="text-xs bg-background border-border mt-0.5 min-h-[60px]" placeholder="Enter remarks about additional fees..." />
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        {paymentField('Downpayment (AED)', 'downpayment')}

        <div>
          <div className="flex items-center justify-between mb-0.5">
            <Label className="text-xs text-muted-foreground">Amount Received (AED)</Label>
            <button 
              onClick={handlePayFull} 
              disabled={isLayaway}
              className="text-[9px] font-bold text-primary bg-primary/10 hover:bg-primary/20 px-1.5 py-0.5 rounded transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              title={isLayaway ? 'PAY FULL is disabled for Layaway — use the monthly payment fields' : 'Auto-fill exact remaining balance'}
            >
              PAY FULL
            </button>
          </div>
          <Input
            type="number"
            value={toDisplay(form.amountReceived)}
            onChange={e => set('amountReceived', fromDisplay(e.target.value))}
            className="h-8 text-xs bg-background border-border disabled:opacity-50"
            placeholder="0.00"
          />
        </div>
      </div>

      <div className={`grid grid-cols-2 gap-2 mb-3 ${!isLayaway ? 'opacity-40' : ''}`}>
        <p className="col-span-2 text-xs text-muted-foreground">
          Layaway Payments <span className="font-bold text-primary">({currency})</span>{!isLayaway ? ' (locked — only active on Layaway MOP)' : ''}
        </p>
        {/* Layaway fields: entered & stored in the record's native currency (e.g. PHP for Pinas) */}
        {(['la1MonthPayment','la2MonthPayment','la3MonthPayment','la4MonthPayment'] as const).map((key, i) => (
          <div key={key}>
            <Label className="text-xs text-muted-foreground">Month {i + 1}</Label>
            <Input
              type="number"
              value={form[key]}
              onChange={e => set(key, e.target.value)}
              disabled={!isLayaway}
              className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50"
              placeholder="0.00"
              min={0}
            />
          </div>
        ))}
      </div>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Remittance Status</Label>
        <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select remittance..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {REMITTANCE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="bg-secondary/50 rounded-lg p-3 mb-3 space-y-1 text-xs">
        <div className="flex justify-between"><span className="text-muted-foreground">Item Price ({currency})</span><span>{currency} {itemPrice.toFixed(2)}</span></div>
        {currency !== 'AED' && <div className="flex justify-between"><span className="text-muted-foreground">Item Price (AED)</span><span>AED {itemPriceAED.toFixed(2)}</span></div>}
        <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>AED {shippingFee.toFixed(2)}</span></div>
        {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Fee</span><span>AED {ccFee.toFixed(2)}</span></div>}
        {additionalAED > 0 && <div className="flex justify-between"><span className="text-muted-foreground">Additional Charges</span><span>AED {additionalAED.toFixed(2)}</span></div>}
        <div className="flex justify-between font-semibold pt-1 border-t border-border">
          <span>Total Amount</span><span>AED {totalAmount.toFixed(2)}</span>
        </div>
        <div className="flex justify-between"><span className="text-muted-foreground">Total Paid</span><span>AED {totalPaid.toFixed(2)}</span></div>
        <div className={`flex justify-between font-bold pt-1 border-t border-border ${remaining > 0 ? 'text-destructive' : remaining < 0 ? 'text-violet-400' : 'text-green-400'}`}>
          <span>{remaining < 0 ? '🎁 Store Credit' : 'Remaining Balance'}</span>
          <span>AED {Math.abs(remaining).toFixed(2)}{remaining < 0 ? ' credit' : ''}</span>
        </div>
        <div className="flex justify-between pt-1 border-t border-border">
          <span className="text-muted-foreground">Expected Profit</span>
          <span className={profitAED >= 0 ? 'text-primary font-medium' : 'text-destructive font-medium'}>AED {profitAED.toFixed(2)}</span>
        </div>
      </div>

      <Button onClick={handleSave} disabled={saving} className="w-full bg-primary text-primary-foreground text-xs h-8">
        {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Save Financials'}
      </Button>
    </div>
  );
}

src/components/admin/MergeClientsModal.t.content:
import { useState, useMemo } from 'react';
import { Merge, AlertTriangle, CheckCircle2, Loader2, Search } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { mergeClients } from 'zite-endpoints-sdk';
import { DatabaseRowType } from '@/types';

interface ClientProfile {
  customerId: string;
  minerName: string;
  recordCount: number;
}

interface Props {
  onClose: () => void;
  onRefresh?: () => void;
  records: DatabaseRowType[];
}

function buildProfiles(records: DatabaseRowType[]): ClientProfile[] {
  const map = new Map<string, { name: string; count: number }>();
  for (const r of records) {
    const id = r.customerId?.trim();
    const name = r.minerName?.trim() || '';
    if (!id) continue;
    if (!map.has(id)) {
      map.set(id, { name, count: 0 });
    }
    map.get(id)!.count++;
  }
  return Array.from(map.entries())
    .map(([customerId, { name, count }]) => ({ customerId, minerName: name, recordCount: count }))
    .sort((a, b) => a.minerName.localeCompare(b.minerName));
}

function ProfilePicker({
  label,
  profiles,
  selected,
  onSelect,
  exclude,
}: {
  label: string;
  profiles: ClientProfile[];
  selected: ClientProfile | null;
  onSelect: (p: ClientProfile) => void;
  exclude?: string;
}) {
  const [search, setSearch] = useState('');
  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return profiles.filter(p =>
      p.customerId !== exclude &&
      (p.minerName.toLowerCase().includes(q) || p.customerId.toLowerCase().includes(q))
    ).slice(0, 80);
  }, [profiles, search, exclude]);

  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">{label}</Label>
      <div className="relative">
        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
        <Input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search name or CUST-ID..."
          className="h-8 text-xs pl-8 bg-background border-border"
        />
      </div>
      <div className="border border-border rounded-md overflow-y-auto max-h-48 bg-background">
        {filtered.length === 0 && (
          <p className="text-xs text-muted-foreground text-center py-4">No profiles found</p>
        )}
        {filtered.map(p => (
          <button
            key={p.customerId}
            onClick={() => onSelect(p)}
            className={`w-full text-left px-3 py-2 text-xs flex justify-between items-center transition-colors border-b border-border last:border-0 hover:bg-secondary/60
              ${selected?.customerId === p.customerId ? 'bg-primary/10 text-primary font-semibold' : 'text-foreground'}`}
          >
            <span className="truncate max-w-[160px]">{p.minerName}</span>
            <span className={`text-[10px] font-mono shrink-0 ml-2 ${selected?.customerId === p.customerId ? 'text-primary' : 'text-muted-foreground'}`}>
              {p.customerId} · {p.recordCount}
            </span>
          </button>
        ))}
      </div>
      {selected && (
        <div className="rounded-md bg-secondary/40 border border-border px-3 py-2 text-xs">
          <span className="text-muted-foreground">Selected: </span>
          <span className="font-semibold text-foreground">{selected.minerName}</span>
          <span className="text-muted-foreground ml-2">({selected.customerId} · {selected.recordCount} records)</span>
        </div>
      )}
    </div>
  );
}

export default function MergeClientsModal({ onClose, onRefresh, records }: Props) {
  const profiles = useMemo(() => buildProfiles(records), [records]);
  const [duplicate, setDuplicate] = useState<ClientProfile | null>(null);
  const [master, setMaster] = useState<ClientProfile | null>(null);
  const [merging, setMerging] = useState(false);
  const [confirm, setConfirm] = useState(false);
  const [result, setResult] = useState<{ success: boolean; message: string; count: number } | null>(null);

  const canMerge = duplicate && master && duplicate.customerId !== master.customerId;

  const handleMerge = async () => {
    if (!duplicate || !master) return;
    setMerging(true);
    setConfirm(false);
    try {
      const res = await mergeClients({
        duplicateCustomerId: duplicate.customerId,
        masterCustomerId: master.customerId,
        masterMinerName: master.minerName,
      });
      setResult({ success: res.success, message: res.message, count: res.updatedCount });
      if (res.success) {
        toast.success(res.message);
        onRefresh?.();
        setDuplicate(null);
        setMaster(null);
      } else {
        toast.error(res.message);
      }
    } catch {
      toast.error('Merge failed. Please try again.');
    } finally {
      setMerging(false);
    }
  };

  return (
    <>
      <Dialog open onOpenChange={onClose}>
        <DialogContent className="max-w-2xl bg-card border-border max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary flex items-center gap-2">
              <Merge className="w-4 h-4" /> Merge Client Profiles
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 text-sm">
            {/* Warning banner */}
            <div className="flex items-start gap-2 rounded-lg bg-destructive/10 border border-destructive/30 px-3 py-2.5">
              <AlertTriangle className="w-4 h-4 text-destructive shrink-0 mt-0.5" />
              <p className="text-xs text-destructive/90 leading-relaxed">
                <strong>Irreversible action.</strong> All records from the <em>Duplicate Profile</em> will be re-assigned to the <em>Master Profile</em> and its name. This cannot be undone — double-check before confirming.
              </p>
            </div>

            {/* Two pickers */}
            <div className="grid grid-cols-2 gap-4">
              <ProfilePicker
                label="① Duplicate Profile (To Delete)"
                profiles={profiles}
                selected={duplicate}
                onSelect={setDuplicate}
                exclude={master?.customerId}
              />
              <ProfilePicker
                label="② Master Profile (To Keep)"
                profiles={profiles}
                selected={master}
                onSelect={setMaster}
                exclude={duplicate?.customerId}
              />
            </div>

            {/* Merge preview */}
            {canMerge && (
              <div className="rounded-lg border border-border bg-secondary/30 p-3 space-y-1.5">
                <p className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Merge Preview</p>
                <div className="flex items-center gap-2 flex-wrap text-xs">
                  <span className="bg-destructive/20 text-destructive px-2 py-0.5 rounded font-mono">{duplicate!.customerId}</span>
                  <span className="text-muted-foreground font-semibold">{duplicate!.minerName}</span>
                  <span className="text-muted-foreground">({duplicate!.recordCount} records)</span>
                  <span className="text-primary font-bold mx-1">→</span>
                  <span className="bg-primary/20 text-primary px-2 py-0.5 rounded font-mono">{master!.customerId}</span>
                  <span className="text-muted-foreground font-semibold">{master!.minerName}</span>
                  <span className="text-muted-foreground">({master!.recordCount} records)</span>
                </div>
                <p className="text-[10px] text-muted-foreground">
                  {duplicate!.recordCount} record(s) will be updated. Names will be normalized to <strong>{master!.minerName}</strong>.
                </p>
              </div>
            )}

            {/* Result banner */}
            {result?.success && (
              <div className="flex items-center gap-2 rounded-lg bg-green-500/10 border border-green-500/30 px-3 py-2.5">
                <CheckCircle2 className="w-4 h-4 text-green-400 shrink-0" />
                <p className="text-xs text-green-400">{result.message}</p>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-2 pt-1">
              <Button variant="outline" className="text-xs h-8 border-border" onClick={onClose}>
                Close
              </Button>
              <Button
                className="flex-1 text-xs h-8 bg-primary text-primary-foreground"
                disabled={!canMerge || merging}
                onClick={() => setConfirm(true)}
              >
                {merging
                  ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1" /> Merging…</>
                  : <><Merge className="w-3.5 h-3.5 mr-1" /> Merge Records</>
                }
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Confirmation dialog */}
      <AlertDialog open={confirm} onOpenChange={setConfirm}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-foreground">Confirm Merge</AlertDialogTitle>
            <AlertDialogDescription className="text-muted-foreground text-sm">
              You are about to move <strong>{duplicate?.recordCount} record(s)</strong> from{' '}
              <span className="font-mono text-destructive">{duplicate?.customerId}</span> ({duplicate?.minerName}) into{' '}
              <span className="font-mono text-primary">{master?.customerId}</span> ({master?.minerName}).{' '}
              This action <strong>cannot be undone</strong>.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="text-xs border-border">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleMerge}
              className="text-xs bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Yes, Merge Now
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

