import { useState, useRef, memo } from 'react';
import { FileText, Truck, Upload, History, ChevronDown, AlertTriangle, Pencil, Check, X, Scissors } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { useCompactMode } from '@/lib/compactMode';
import { calcShippingFee, isFreeSf, isPromoSf, getPromoSf, getQty } from '@/lib/calculations';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';
import SplitItemDialog from '@/components/SplitItemDialog';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

const MOP_OPTIONS = [
  'COD (Dubai)',
  'COD (Sharjah)',
  'COD (Abu Dhabi)',
  'Bank Transfer AED (Dubai)',
  'Bank Transfer AED (Sharjah)',
  'Bank Transfer AED (Abu Dhabi)',
  'Bank Transfer PHP',
  'Bank Transfer USD',
  'GCash',
  'Western Union (US)',
  'Western Union (PH)',
  'Pick Up Shop',
  'Meet Up',
  'International',
];

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.status === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function getDeliveryLabel(record: DatabaseRowType): string {
  const mop = record.modeOfPayment || '';
  const region = record.regions ? `(${record.regions})` : '';
  if (record.status === 'Layaway') return 'Layaway';
  if (mop === 'Pick Up Shop') return 'Pick Up Shop';
  if (mop === 'Meet Up') return 'Meet Up';
  if (region) return `${mop} ${region}`.trim();
  return mop || 'Unknown';
}

function getDeliverySummary(records: DatabaseRowType[]): string {
  const labels = records.map(getDeliveryLabel);
  const unique = [...new Set(labels)];
  if (unique.length === 1) return unique[0];
  return `🔴 MIXED: ${unique.join(', ')}`;
}

function canDispatch(record: DatabaseRowType): boolean {
  const isCOD = (record.modeOfPayment || '').toUpperCase().includes('COD');
  if (isCOD) return true;
  const amountReceived = parseFloat(String(record.amountReceived || '0').replace(/,/g, '')) || 0;
  const clientRate = parseFloat(String(record.clientRate || '0').replace(/,/g, '')) || 0;
  return amountReceived >= clientRate;
}

// ─── Inline field editor for a single record ───────────────────────────────
interface ItemEditState {
  mop: string;
  grams: string;
}

function ItemEditRow({ record, onSave, onCancel, saving }: {
  record: DatabaseRowType;
  onSave: (fields: Partial<DatabaseRowType>) => void;
  onCancel: () => void;
  saving: boolean;
}) {
  const [mop, setMop] = useState(record.modeOfPayment || '');
  const [grams, setGrams] = useState(String(record.grams ?? ''));
  const [freeSf, setFreeSf] = useState(String(record.freeSf).toLowerCase() === 'true');
  const existingPromo = getPromoSf(record);
  const [promoSfVal, setPromoSfVal] = useState(isPromoSf(record) ? String(record.freeSf) : '');
  const [promoSfCurrency, setPromoSfCurrency] = useState(existingPromo?.currency ?? 'AED');
  const [promoSfAmount, setPromoSfAmount] = useState(existingPromo ? String(existingPromo.amount) : '');
  const [itemDesc, setItemDesc] = useState(record.itemDescription || '');
  const isScrewType = (record.category || '').toLowerCase().includes('screw type');

  const handleSave = () => {
    const fields: Partial<DatabaseRowType> = {};
    const descTrimmed = itemDesc.trim().toUpperCase();
    if (descTrimmed && descTrimmed !== (record.itemDescription || '').toUpperCase()) fields.itemDescription = descTrimmed;
    if (mop !== record.modeOfPayment) fields.modeOfPayment = mop;
    if (!isScrewType) {
      const gramsNum = parseFloat(grams);
      if (!isNaN(gramsNum) && gramsNum !== record.grams) fields.grams = gramsNum;
    }
    const currentFreeSf = String(record.freeSf).toLowerCase() === 'true';
    const currentPromoSf = isPromoSf(record) ? String(record.freeSf) : '';
    if (freeSf !== currentFreeSf || promoSfVal !== currentPromoSf) {
      if (promoSfVal) {
        (fields as Record<string, unknown>).freeSf = promoSfVal;
      } else {
        fields.freeSf = freeSf ? 'TRUE' : '';
      }
    }
    onSave(fields);
  };

  return (
    <div className="mt-2 space-y-2 border-t border-border/40 pt-2">
      <div className="flex flex-col gap-1.5">
        <label className="text-[10px] text-muted-foreground uppercase tracking-wide">Item Description</label>
        <Input
          value={itemDesc}
          onChange={e => setItemDesc(e.target.value)}
          className="h-7 text-xs bg-background border-border uppercase"
          placeholder="e.g. GOLD RING 18K"
        />
      </div>
      <div className="flex flex-col gap-1.5">
        <label className="text-[10px] text-muted-foreground uppercase tracking-wide">Mode of Payment</label>
        <Select value={mop} onValueChange={setMop}>
          <SelectTrigger className="h-7 text-xs bg-background border-border">
            <SelectValue placeholder="Select MOP..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {MOP_OPTIONS.map(opt => (
              <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      {!isScrewType && (
        <div className="flex flex-col gap-1.5">
          <label className="text-[10px] text-muted-foreground uppercase tracking-wide">Grams</label>
          <Input
            value={grams}
            onChange={e => setGrams(e.target.value)}
            type="number"
            step="0.01"
            className="h-7 text-xs bg-background border-border"
            placeholder="e.g. 1.71"
          />
        </div>
      )}
      <div className="flex items-center justify-between bg-muted/30 rounded-lg px-3 py-2 border border-border/40">
        <div>
          <p className="text-xs font-medium">Free Shipping</p>
          <p className="text-[10px] text-muted-foreground">Override SF to AED 0</p>
        </div>
        <Switch
          checked={freeSf}
          onCheckedChange={v => { setFreeSf(v); if (v) setPromoSfVal(''); }}
          className="data-[state=checked]:bg-primary"
        />
      </div>
      {/* Promo SF */}
      <div className="rounded-lg border border-orange-400/30 bg-orange-400/5 px-3 py-2 space-y-1.5">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-xs font-medium text-orange-400">Promo SF</p>
            <p className="text-[10px] text-muted-foreground">Set a discounted shipping fee</p>
          </div>
          <Switch
            checked={!!promoSfVal}
            onCheckedChange={v => { if (!v) setPromoSfVal(''); else setFreeSf(false); }}
            className="data-[state=checked]:bg-orange-400"
          />
        </div>
        {!!promoSfVal && (
          <div className="flex items-center gap-1.5">
            <Select value={promoSfCurrency} onValueChange={v => { setPromoSfCurrency(v); setPromoSfVal(`PROMO:${v}:${promoSfAmount}`); }}>
              <SelectTrigger className="h-7 w-16 text-xs bg-background border-orange-400/40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                <SelectItem value="AED" className="text-xs">AED</SelectItem>
                <SelectItem value="PHP" className="text-xs">PHP</SelectItem>
                <SelectItem value="USD" className="text-xs">USD</SelectItem>
              </SelectContent>
            </Select>
            <Input
              type="number"
              value={promoSfAmount}
              onChange={e => { setPromoSfAmount(e.target.value); setPromoSfVal(`PROMO:${promoSfCurrency}:${e.target.value}`); }}
              className="h-7 text-xs flex-1 bg-background border-orange-400/40"
              placeholder="e.g. 20"
            />
          </div>
        )}
      </div>
      <div className="flex gap-2">
        <Button size="sm" className="h-7 text-xs flex-1" onClick={handleSave} disabled={saving}>
          <Check className="h-3 w-3 mr-1" /> Save
        </Button>
        <Button size="sm" variant="outline" className="h-7 text-xs flex-1" onClick={onCancel} disabled={saving}>
          <X className="h-3 w-3 mr-1" /> Cancel
        </Button>
      </div>
    </div>
  );
}

function DispatchClientCard({ minerName, records, allRecords, onUpdate, userEmail }: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});
  const [showHistory, setShowHistory] = useState(false);
  const [splitRecord, setSplitRecord] = useState<DatabaseRowType | null>(null);

  // Inline name editing
  const [editingName, setEditingName] = useState(false);
  const [nameValue, setNameValue] = useState(minerName);
  const [savingName, setSavingName] = useState(false);
  const nameInputRef = useRef<HTMLInputElement>(null);

  // Per-item inline field editing
  const [editingItemId, setEditingItemId] = useState<number | null>(null);
  const [savingItemId, setSavingItemId] = useState<number | null>(null);

  const first = records[0];
  const deliverySummary = getDeliverySummary(records);
  const { isCompact } = useCompactMode();

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }

    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  const startEditName = (e: React.MouseEvent) => {
    e.stopPropagation();
    setNameValue(minerName);
    setEditingName(true);
    setTimeout(() => nameInputRef.current?.focus(), 50);
  };

  const cancelEditName = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setEditingName(false);
    setNameValue(minerName);
  };

  const saveEditName = async (e?: React.MouseEvent) => {
    e?.stopPropagation();
    const trimmed = nameValue.trim();
    if (!trimmed || trimmed === minerName) { cancelEditName(); return; }
    setSavingName(true);
    try {
      await Promise.all(records.map(r => onUpdate(r.id, { minerName: trimmed })));
      toast.success(`Name updated to "${trimmed}"`);
      setEditingName(false);
    } catch {
      toast.error('Failed to update name');
    } finally {
      setSavingName(false);
    }
  };

  const handleItemSave = async (record: DatabaseRowType, fields: Partial<DatabaseRowType>) => {
    if (Object.keys(fields).length === 0) { setEditingItemId(null); return; }
    setSavingItemId(record.id);
    try {
      await onUpdate(record.id, fields);
      toast.success('Item updated');
      setEditingItemId(null);
    } catch {
      toast.error('Failed to update item');
    } finally {
      setSavingItemId(null);
    }
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full px-4 py-2.5 border-b border-border/50 flex items-center justify-between text-left focus:outline-none"
        onClick={() => setIsExpanded(prev => !prev)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            {editingName ? (
              <div className="flex items-center gap-1.5 flex-1" onClick={e => e.stopPropagation()}>
                <Input
                  ref={nameInputRef}
                  value={nameValue}
                  onChange={e => setNameValue(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter') saveEditName();
                    if (e.key === 'Escape') cancelEditName();
                  }}
                  className="h-7 text-sm font-cinzel bg-background border-primary/50 text-primary w-full max-w-[220px]"
                  disabled={savingName}
                />
                <button onClick={saveEditName} disabled={savingName} className="text-green-500 hover:text-green-400 transition-colors" title="Save">
                  <Check className="h-4 w-4" />
                </button>
                <button onClick={cancelEditName} className="text-muted-foreground hover:text-foreground transition-colors" title="Cancel">
                  <X className="h-4 w-4" />
                </button>
              </div>
            ) : (
              <>
                <span className="font-cinzel text-sm text-primary">{minerName}</span>
                <button
                  className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                  title="Edit customer name"
                  onClick={startEditName}
                >
                  <Pencil className="h-3 w-3" />
                </button>
                {first?.customerId && (
                  <button
                    className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                    title="View Lifetime History"
                    onClick={e => { e.stopPropagation(); setShowHistory(true); }}
                  >
                    <History className="h-3.5 w-3.5" />
                  </button>
                )}
              </>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            {!isCompact && (
              <span className={deliverySummary.startsWith('🔴') ? 'text-destructive font-medium' : ''}>
                {deliverySummary}
              </span>
            )}
            {!isCompact && first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 ml-2 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="border-primary/40 text-primary text-xs h-7"
            onClick={e => { e.stopPropagation(); setShowInvoice(true); }}
          >
            <FileText className="h-3 w-3 mr-1" /> Invoice
          </Button>
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {isExpanded && (
        <div className="px-3 py-2 space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          {records.map(record => {
            const givenToShopMode = isGivenToShopMode(record);
            const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;
            const dispatchAllowed = canDispatch(record);
            const isScrewType = (record.category || '').toLowerCase().includes('screw type');
            const isEditingThis = editingItemId === record.id;

            return (
              <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
                <div className="flex items-start justify-between mb-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium">{record.itemDescription}</p>
                    {!isCompact && (
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {record.category} · {isScrewType ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')}
                        <span className="text-foreground font-medium ml-1">
                          · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                        </span>
                      </p>
                    )}
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0 ml-2">
                    {/* Split button for Outsource items with grams */}
                    {record.status === 'Outsource' && (record.grams ?? 0) > 0 && !isEditingThis && (
                      <button
                        className="text-teal-400 hover:text-teal-300 transition-colors"
                        title="Split item (partial dispatch)"
                        onClick={() => setSplitRecord(record)}
                      >
                        <Scissors className="h-3.5 w-3.5" />
                      </button>
                    )}
                    {/* Edit MOP/Grams pencil button */}
                    {!isEditingThis && record.status !== 'Cancelled' && (
                      <button
                        className="text-muted-foreground hover:text-primary transition-colors"
                        title="Edit MOP & Grams"
                        onClick={() => setEditingItemId(record.id)}
                      >
                        <Pencil className="h-3.5 w-3.5" />
                      </button>
                    )}
                    <StatusBadge status={record.status} />
                  </div>
                </div>

                {!isCompact && (
                  <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                    <Truck className="h-3 w-3" />
                    <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                    {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
                    {isPromoSf(record) && (() => { const p = getPromoSf(record); return p ? <span className="text-orange-400">(PROMO {p.currency} {p.amount})</span> : null; })()}
                    {record.source && (
                      <span className="ml-2 text-muted-foreground/70 border-l border-border/40 pl-2">
                        📦 {record.source}
                      </span>
                    )}
                  </div>
                )}

                {!dispatchAllowed && !givenToShopMode && (
                  <div className="flex items-center gap-1.5 mb-2">
                    <Badge variant="destructive" className="text-[10px] px-1.5 py-0 h-5 flex items-center gap-1">
                      <AlertTriangle className="h-2.5 w-2.5" />
                      Balance Pending
                    </Badge>
                    <span className="text-[10px] text-muted-foreground">
                      Received: {record.amountReceived || 0} / {record.clientRate || 0}
                    </span>
                  </div>
                )}

                {!isCompact && record.liverAdminRemarks && (
                  <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                    Remarks: {record.liverAdminRemarks}
                  </p>
                )}

                {!isCompact && latestAudit && (
                  <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                    <History className="h-2.5 w-2.5" />
                    {latestAudit}
                  </p>
                )}

                {/* Inline MOP & Grams editor */}
                {isEditingThis && (
                  <ItemEditRow
                    record={record}
                    saving={savingItemId === record.id}
                    onSave={fields => handleItemSave(record, fields)}
                    onCancel={() => setEditingItemId(null)}
                  />
                )}

                {record.status !== 'Cancelled' && (
                  <Select
                    key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`}
                    onValueChange={v => handleStatusChange(record, v)}
                  >
                    <SelectTrigger className="h-7 text-xs w-full bg-background border-border mt-2">
                      <SelectValue placeholder="Set status..." />
                    </SelectTrigger>
                    <SelectContent className="bg-popover border-border">
                      {givenToShopMode ? (
                        <>
                          <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                          <SelectItem value="Dispatched" className="text-xs">
                            Dispatched{!dispatchAllowed ? ' (Balance Pending)' : ''}
                          </SelectItem>
                          <SelectItem value="Delivered" className="text-xs">
                            Delivered{!dispatchAllowed ? ' (Balance Pending)' : ''}
                          </SelectItem>
                        </>
                      ) : (
                        <>
                          <SelectItem value="Dispatched" className="text-xs">
                            Dispatched{!dispatchAllowed ? ' (Balance Pending)' : ''}
                          </SelectItem>
                          <SelectItem value="Delivered" className="text-xs">
                            Delivered{!dispatchAllowed ? ' (Balance Pending)' : ''}
                          </SelectItem>
                        </>
                      )}
                      <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem>
                      <SelectItem value="Layaway" className="text-xs">Layaway</SelectItem>
                      <SelectItem value="Payment for Verification" className="text-xs">Payment for Verification</SelectItem>
                      <SelectItem value="Reseller" className="text-xs">Reseller</SelectItem>
                      <SelectItem value="Outsource" className="text-xs">Outsource</SelectItem>
                      <SelectItem value="Returned Item" className="text-xs">Returned Item</SelectItem>
                      <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                    </SelectContent>
                  </Select>
                )}
              </div>
            );
          })}
        </div>
      )}

      {showInvoice && (
        <InvoiceModal
          records={allRecords.filter(r => r.minerName?.trim().toLowerCase() === minerName.trim().toLowerCase())}
          onClose={() => setShowInvoice(false)}
        />
      )}

      {splitRecord && (
        <SplitItemDialog
          record={splitRecord}
          onClose={() => setSplitRecord(null)}
          onComplete={() => onUpdate(splitRecord.id, {})}
        />
      )}

      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

