import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { Toaster } from '@/components/ui/sonner';
import { getRecords, getRoles, updateRecord } from 'zite-endpoints-sdk';
import { getUserRole, EMAIL_TO_LIVER_NAME } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import LiverDashboard from '@/pages/LiverDashboard';
import InvoicingTab from '@/components/invoicing/InvoicingTab';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import { RefreshCw, Rows3 } from 'lucide-react';
import { getRatesForDate } from '@/lib/ratesStore';
import { CompactModeProvider, useCompactMode } from '@/lib/compactMode';

type Tab = 'admin' | 'dispatch' | 'accounts' | 'bossing' | 'liver' | 'invoicing';

const TAB_LABELS: Record<Tab, string> = {
  admin: 'Admin',
  dispatch: 'Dispatch',
  accounts: 'Accounts',
  bossing: 'Bossing',
  liver: 'My Sales',
  invoicing: 'Invoicing',
};

function AppInner() {
  const { user, isLoading: authLoading, loginWithRedirect } = useAuth();

  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [dynamicRoles, setDynamicRoles] = useState<any[] | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<Tab>('admin');
  const { isCompact, toggle: toggleCompact } = useCompactMode();

  useEffect(() => {
    if (!authLoading && !user) {
      loginWithRedirect({ redirectUrl: window.location.href });
    }
  }, [authLoading, user, loginWithRedirect]);

  const fetchData = useCallback(async (silent = false) => {
    if (!user) return;
    try {
      if (!silent) setDataLoading(true);
      setRefreshing(true);
      const [recResult, rolesResult] = await Promise.all([
        getRecords({ tailOnly: silent }),
        getRoles({}).catch(() => [] as any[]),
      ]);
      setRecords((recResult as unknown as DatabaseRowType[]) || []);
      setDynamicRoles((rolesResult as unknown as any[]) || []);
    } catch (err) {
      console.error('Failed to load data', err);
    } finally {
      setDataLoading(false);
      setRefreshing(false);
    }
  }, [user]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleUpdate = useCallback(async (rowId: number, fields: Partial<DatabaseRowType>) => {
    // Pass the existing record so the backend skips the expensive Database.findAll() call
    const existing = records.find(r => r.id === rowId);
    // Use the record's actual date to look up historically-correct rates.
    // Fields may contain a new dateOfLive override; otherwise use the stored date.
    const recordDate = (fields as any).dateOfLive ?? existing?.dateOfLive ?? '';
    const rates = getRatesForDate(recordDate);
    await updateRecord({
      rowId,
      fields: fields as Record<string, unknown>,
      existingRecord: existing as Record<string, unknown> | undefined,
      phpRate: rates.phpRate,
      silverSellRate: rates.silverSellRate,
      silverBrandedSellRate: rates.silverBrandedSellRate,
      silverCostRate: rates.silverCostRate,
      silverBrandedCostRate: rates.silverBrandedCostRate,
    });
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
  }, [records]);

  if (authLoading || (!user && !authLoading)) return null;
  if (dataLoading) return <LoadingSkeleton />;

  const email = user!.email;
  const firstName = user!.firstName;
  const roles = getUserRole(email, dynamicRoles);

  // ── Tab visibility ──────────────────────────────────────────────────────────
  // super_admin → ALL tabs
  // admin       → Admin Pipeline + Invoicing ONLY
  // dispatch    → Dispatch only
  // accounts    → Accounts only
  // bossing     → Bossing only
  // liver       → Liver (own records only)
  const isSuperAdmin = roles.includes('super_admin');
  const isAdmin = roles.includes('admin');
  const isDispatch = roles.includes('dispatch');
  const isAccounts = roles.includes('accounts');
  const isBossing = roles.includes('bossing');
  const isLiver = roles.includes('liver');

  const visibleTabs: Tab[] = [];
  if (isSuperAdmin || isAdmin) visibleTabs.push('admin');
  if (isSuperAdmin || isDispatch) visibleTabs.push('dispatch');       // admin excluded
  if (isSuperAdmin || isAccounts) visibleTabs.push('accounts');       // admin excluded
  if (isSuperAdmin || isBossing) visibleTabs.push('bossing');         // admin excluded
  if (isSuperAdmin || isLiver) visibleTabs.push('liver');             // admin excluded
  if (isSuperAdmin || isAdmin) visibleTabs.push('invoicing');

  if (visibleTabs.length === 0) {
    return (
      <>
        <AccessDenied email={email} />
        <Toaster />
      </>
    );
  }

  const currentTab = visibleTabs.includes(activeTab) ? activeTab : visibleTabs[0];

  const lockedLiverName = isLiver && !isSuperAdmin && !isAdmin
    ? (EMAIL_TO_LIVER_NAME[email.toLowerCase()] || null)
    : null;

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: email,
    userFirstName: firstName,
    onRefresh: () => fetchData(true),
    lockedLiverName: lockedLiverName ?? undefined,
  };

  const showUploadFAB = isSuperAdmin || isAdmin;

  return (
    <div className="min-h-screen bg-background text-foreground">
      <Toaster />

      {/* Tab Bar */}
      <div className="sticky top-0 z-30 bg-card border-b border-border flex items-center overflow-x-auto scrollbar-none">
        <div className="flex flex-1 overflow-x-auto">
          {visibleTabs.map(tab => (
            <button
              key={tab}
              onClick={() => { setActiveTab(tab); setSearchQuery(''); }}
              className={`shrink-0 px-4 py-3 text-xs font-semibold uppercase tracking-wider transition-colors border-b-2 ${
                currentTab === tab
                  ? 'border-primary text-primary'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              {TAB_LABELS[tab]}
            </button>
          ))}
        </div>
        <div className="shrink-0 flex items-center gap-1.5 px-2">
          {/* Compact mode toggle */}
          <button
            onClick={toggleCompact}
            className={`p-1.5 rounded-md transition-colors ${isCompact ? 'text-primary bg-primary/10' : 'text-muted-foreground hover:text-primary hover:bg-primary/10'}`}
            title={isCompact ? 'Compact mode ON — click for comfortable view' : 'Switch to compact mode'}
          >
            <Rows3 className="h-3.5 w-3.5" />
          </button>
          {/* Sync indicator */}
          <span className={`h-2 w-2 rounded-full ${refreshing ? 'bg-green-400 animate-pulse' : 'bg-green-400/30'}`} title={refreshing ? 'Syncing…' : 'Up to date'} />
          {/* Refresh button */}
          <button
            onClick={() => fetchData(true)}
            disabled={refreshing}
            className="p-1.5 rounded-md text-muted-foreground hover:text-primary hover:bg-primary/10 transition-colors disabled:opacity-40"
            title="Refresh data"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? 'animate-spin' : ''}`} />
          </button>
          {showUploadFAB && <UploadMasterlistFAB onRefresh={() => fetchData(true)} />}
        </div>
      </div>

      {/* Tab Content */}
      {currentTab === 'admin' && <AdminPipeline {...tabProps} />}
      {currentTab === 'dispatch' && <DispatchBoard {...tabProps} />}
      {currentTab === 'accounts' && <AccountsTracking {...tabProps} />}
      {currentTab === 'bossing' && <BossingDashboard {...tabProps} />}
      {currentTab === 'liver' && <LiverDashboard {...tabProps} />}
      {currentTab === 'invoicing' && <InvoicingTab {...tabProps} />}
    </div>
  );
}

export default function App() {
  return (
    <CompactModeProvider>
      <AppInner />
    </CompactModeProvider>
  );
}

