const USD_TO_AED = 3.67;

const n = (val: any): number => {
  const cleaned = String(val ?? '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
};

interface RateConfig {
  phpRate: number;
  silverSellRate: number;
  silverBrandedSellRate: number;
  silverCostRate: number;
  silverBrandedCostRate: number;
}

function calculateProfit(fields: any, rates: RateConfig): number {
  const status = String(fields.status || '').toLowerCase().trim();
  if (status === 'cancelled' || status === 'returned item') return 0;

  const grams = n(fields.grams);
  const clientRate = n(fields.clientRate);
  const category = String(fields.category || '').toLowerCase();
  const currency = String(fields.currency || 'AED').toUpperCase();
  const qty = n(fields.qty) || 1;

  let rateAED = clientRate;
  if (currency === 'PHP') rateAED = clientRate / rates.phpRate;
  else if (currency === 'USD') rateAED = clientRate * USD_TO_AED;

  let totalSales = 0;
  let totalCost = 0;

  if (category.includes('screw type') || category.includes('per pc')) {
    totalSales = rateAED * qty;
    let sr = n(fields.supplierRate) > 0 ? n(fields.supplierRate) : (n(fields.goldRate) > 0 ? n(fields.goldRate) : 115);
    if (sr === 115 && String(fields.itemDescription || '').toUpperCase().includes('B1T1')) sr *= 2;
    totalCost = sr * qty;
  } else if (category.includes('silver branded')) {
    if (rateAED > 0 && Math.abs(rateAED - rates.silverBrandedSellRate) <= 2) rateAED = rates.silverBrandedSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverBrandedSellRate) * grams;
    totalCost = rates.silverBrandedCostRate * grams;
  } else if (category.includes('silver')) {
    if (rateAED > 0 && Math.abs(rateAED - rates.silverSellRate) <= 2) rateAED = rates.silverSellRate;
    const effectiveSilverRate = clientRate > 0 ? rateAED : rates.silverSellRate;
    totalSales = effectiveSilverRate * grams;
    totalCost = rates.silverCostRate * grams;
  } else if (category.includes('diamond')) {
    totalSales = rateAED * qty;
    totalCost = n(fields.supplierRate) * qty;
  } else {
    totalSales = rateAED * grams;
    const gr = n(fields.goldRate);
    const sr = n(fields.supplierRate);
    const parsedMc = n(fields.mc);
    const effectiveMc = parsedMc > 0 ? parsedMc : (category.includes('special price ef') ? 25 : category.includes('special price') ? 21 : 16);
    if (gr > 0) totalCost = (gr + effectiveMc) * grams;
    else if (sr > 0) totalCost = sr * grams;
  }

  const ccFee = String(fields.modeOfPayment || '') === 'Credit Card' ? totalSales * 0.05 : 0;
  return Math.round(totalSales - totalCost - ccFee);
}

export default createEndpoint({
  description: 'Split an Outsource item into two rows: one with remaining grams, one with split-out grams',
  authenticated: true,
  inputSchema: z.object({
    rowId: z.number(),
    splitGrams: z.number().positive(),
    newStatus: z.string(),
    // The full existing record passed from the frontend (avoids extra DB lookup)
    existingRecord: z.record(z.unknown()),
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean(), remainingGrams: z.number(), splitGrams: z.number() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error('Unauthorized request');
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '').toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error('Forbidden: Your account does not have permission to modify the database.');

    const orig = input.existingRecord as Record<string, any>;
    const originalGrams = parseFloat(String(orig.grams ?? '0')) || 0;

    if (input.splitGrams <= 0 || input.splitGrams >= originalGrams) {
      throw new Error(`Split grams (${input.splitGrams}) must be greater than 0 and less than the original grams (${originalGrams}).`);
    }

    const remainingGrams = Math.round((originalGrams - input.splitGrams) * 10000) / 10000;
    const rates: RateConfig = {
      phpRate: input.phpRate,
      silverSellRate: input.silverSellRate,
      silverBrandedSellRate: input.silverBrandedSellRate,
      silverCostRate: input.silverCostRate,
      silverBrandedCostRate: input.silverBrandedCostRate,
    };

    const now = new Date();
    const today = `${now.getMonth() + 1}/${now.getDate()}/${now.getFullYear()}`;

    // ── 1. Update original row ───────────────────────────────────────────────
    const origRemarksUpdated = `${orig.liverAdminRemarks || ''}[Split: ${input.splitGrams}g moved out to new row on ${today}]`.trim();
    const origForProfit = { ...orig, grams: remainingGrams };
    const origNewProfit = calculateProfit(origForProfit, rates);

    await Database.update({
      rowId: input.rowId,
      row: {
        grams: remainingGrams,
        profit: origNewProfit,
        liverAdminRemarks: origRemarksUpdated,
      },
    });

    // ── 2. Build new split row ───────────────────────────────────────────────
    const splitRemarks = `[Split: from original ${originalGrams}g item on ${today}]${orig.liverAdminRemarks ? ' ' + orig.liverAdminRemarks : ''}`;

    const EXCLUDED_KEYS = new Set(['id']);

    const newRow: Record<string, any> = {};
    for (const [k, v] of Object.entries(orig)) {
      if (EXCLUDED_KEYS.has(k)) continue;
      newRow[k] = v;
    }

    // Set split-specific fields
    newRow.grams = input.splitGrams;
    newRow.status = input.newStatus;

    // Ensure dateOfLive is in M/D/YYYY format (not ISO) to match sheet format
    if (orig.dateOfLive) {
      const rawDate = String(orig.dateOfLive);
      // If it looks like an ISO string, convert it
      if (rawDate.includes('T') || rawDate.includes('Z') || rawDate.match(/^\d{4}-\d{2}-\d{2}/)) {
        const d = new Date(rawDate);
        if (!isNaN(d.getTime())) {
          newRow.dateOfLive = `${d.getMonth() + 1}/${d.getDate()}/${d.getFullYear()}`;
        }
      } else {
        newRow.dateOfLive = rawDate; // already human-readable, keep as-is
      }
    }

    // Append -B to orderId for uniqueness (keep Invoice # same for grouping on invoice)
    if (orig.orderId) {
      newRow.orderId = String(orig.orderId).replace(/-B$/, '') + '-B';
    }

    // ── Edge case #1: Zero out flat fees / payment history on the new row ──
    newRow.downpayment = '0';
    newRow.amountReceived = '0';
    newRow.la1MonthPayment = '0';
    newRow.la2MonthPayment = '0';
    newRow.la3MonthPayment = '0';
    newRow.la4MonthPayment = '0';
    newRow.additionalCharges = '0';

    // ── Edge case #3: Audit trail ───────────────────────────────────────────
    newRow.liverAdminRemarks = splitRemarks;

    // Dispatch date / delivered date: only copy if the new status warrants it
    if (input.newStatus !== 'Dispatched') newRow.dispatchDate = '';
    if (input.newStatus !== 'Delivered' && input.newStatus !== 'Given to Shop') newRow.deliveredDate = '';

    // Recalculate profit for the new row
    newRow.profit = calculateProfit(newRow, rates);

    // Handle freeSf boolean vs string
    if (newRow.freeSf === true || newRow.freeSf === 'TRUE' || newRow.freeSf === 'true') {
      newRow.freeSf = true;
    } else if (String(newRow.freeSf ?? '').toUpperCase().startsWith('PROMO:')) {
      // keep as-is
    } else {
      newRow.freeSf = false;
    }

    await Database.create({ row: newRow });

    return { success: true, remainingGrams, splitGrams: input.splitGrams };
  },
});

import { z } from 'zod';
