// Strict Global Fallback Baseline
const GLOBAL_DEFAULT_PHP_RATE = 16.7;

/**
 * Saves a specific exchange rate for a specific live date.
 */
export function setPhpRate(dateOfLive: string, rate: number) {
  if (!dateOfLive || isNaN(rate) || rate <= 0) return;
  try {
    const key = `phpRate_${dateOfLive}`;
    localStorage.setItem(key, rate.toString());
  } catch (e) {
    console.error('Failed to save PHP rate:', e);
  }
}

/**
 * Retrieves the specific exchange rate for a live date.
 * If none was specifically set by the admin on that computer, it strictly defaults to 16.7
 */
export function getPhpRate(dateOfLive: string): number {
  if (!dateOfLive) return GLOBAL_DEFAULT_PHP_RATE;
  try {
    const key = `phpRate_${dateOfLive}`;
    const stored = localStorage.getItem(key);
    if (stored) {
      const parsed = parseFloat(stored);
      if (!isNaN(parsed) && parsed > 0) return parsed;
    }
  } catch (e) {
    console.error('Failed to read PHP rate:', e);
  }

  // Enforces the Master Anchor fallback
  return GLOBAL_DEFAULT_PHP_RATE;
}

const ones = ['', 'ONE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE',
  'TEN', 'ELEVEN', 'TWELVE', 'THIRTEEN', 'FOURTEEN', 'FIFTEEN', 'SIXTEEN', 'SEVENTEEN', 'EIGHTEEN', 'NINETEEN'];
const tens = ['', '', 'TWENTY', 'THIRTY', 'FORTY', 'FIFTY', 'SIXTY', 'SEVENTY', 'EIGHTY', 'NINETY'];

function chunkToWords(n: number): string {
  if (n === 0) return '';
  if (n < 20) return ones[n];
  if (n < 100) return tens[Math.floor(n / 10)] + (n % 10 ? ' ' + ones[n % 10] : '');
  return ones[Math.floor(n / 100)] + ' HUNDRED' + (n % 100 ? ' ' + chunkToWords(n % 100) : '');
}

export function numberToWords(amount: number, currency: string): string {
  const currencyWords: Record<string, { main: string; sub: string }> = {
    PHP: { main: 'PESOS', sub: 'CENTAVOS' },
    AED: { main: 'DIRHAMS', sub: 'FILS' },
    USD: { main: 'DOLLARS', sub: 'CENTS' },
  };
  const cw = currencyWords[currency] || { main: currency, sub: 'CENTS' };

  const rounded = Math.round(amount * 100) / 100;
  const intPart = Math.floor(rounded);
  const decPart = Math.round((rounded - intPart) * 100);

  const parts: string[] = [];
  if (intPart >= 1_000_000) {
    parts.push(chunkToWords(Math.floor(intPart / 1_000_000)) + ' MILLION');
  }
  if (Math.floor((intPart % 1_000_000) / 1000) > 0) {
    parts.push(chunkToWords(Math.floor((intPart % 1_000_000) / 1000)) + ' THOUSAND');
  }
  if (intPart % 1000 > 0) {
    parts.push(chunkToWords(intPart % 1000));
  }

  let result = (parts.join(' ') || 'ZERO') + ' ' + cw.main;
  if (decPart > 0) {
    result += ' AND ' + chunkToWords(decPart) + ' ' + cw.sub;
  }
  return result + ' ONLY';
}

import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType, Roles } from 'zite-integrations-backend-sdk';

const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "roseannaranez2@gmail.com"
];

// Strict allowlist of fields that can be bulk-updated
const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'status', 'remittanceStatus', 'reviewChasing', 'dispatchDate', 'deliveredDate', 'additionalCharges', 'liverAdminRemarks'
]);

export default createEndpoint({
  description: 'Securely update multiple Database rows in a single background batch',
  authenticated: true,
  inputSchema: z.object({
    updates: z.array(z.object({
      rowId: z.number(),
      fields: z.record(z.unknown()),
    })),
  }),
  outputSchema: z.object({ success: z.boolean(), updatedCount: z.number() }),
  execute: async ({ input, context }) => {
    // 1. Enforce Admin/Dispatch Authorization
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
         const roleStr = (found.role || '').toLowerCase();
         if (['super_admin', 'admin', 'dispatch'].some(r => roleStr.includes(r))) {
            isAuthorized = true;
         }
      }
    }

    if (!isAuthorized) {
      throw new Error("Forbidden: Your account does not have permission for bulk updates.");
    }

    // 2. Safely process the background batch
    let count = 0;
    for (const update of input.updates) {
      const sanitized: Partial<DatabaseRowType> = {};
      for (const [key, value] of Object.entries(update.fields)) {
        if (VALID_FIELDS.has(key as keyof DatabaseRowType)) {
          (sanitized as Record<string, unknown>)[key] = value;
        }
      }

      if (Object.keys(sanitized).length > 0) {
        await Database.update({ rowId: update.rowId, row: sanitized });
        count++;
      }
    }

    return { success: true, updatedCount: count };
  },
});

