  currency: string;
  ccIncludeShipping?: boolean;
}

const MYK_LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';
const EMPIRE_LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/gVXEeVabkZMS2jbPUymu31/pasted-image-1773650297935.png';

function isEmpirePage(page?: string): boolean {
  const p = (page || '').toLowerCase();
  return p.includes('empire gold') || p.includes('empire');
}

const NOTES = [
  'We can hold unpaid items for a maximum of 3 days from the invoice date.',
  'Failure to settle within 3 days may result in additional charges.',
  'Unpaid items will be automatically cancelled after the grace period without prior notice.',
  'All items undergo strict quality checking before dispatch.',
  'An unboxing video is strictly required. No video, no refund, no exchange.',
  'No cash refund. Store credit only.',
  'Non Refundable for LA items once the payments is verified and decided not to continue the purchased. Please decide wisely.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;
const rnd = (v: number) => Math.round(v);

/** Compute item amount in PHP using the same display algorithm (round rate first, then multiply). */
function calcPhpItemAmount(r: DatabaseRowType): number {
  const rRates = getRatesForDate(r.dateOfLive || '');
  const rateAED = clientRateAED(r);
  const phpDisplayRate = rnd(rateAED * rRates.phpRate);
  const cat = (r.category || '').toLowerCase().trim();
  const isScrewType = cat.includes('screw type');
  const isPerPc = cat.includes('per pc');
  const isPc = isPcItem(r);
  const g = n(r.grams);
  const qty = getQty(r);
  if (isScrewType || isPerPc) return rnd(phpDisplayRate * qty);
  if (isPc || g === 0) return phpDisplayRate;
  return rnd(phpDisplayRate * g);
}

export default function InvoicePrintContent({ records, currency, ccIncludeShipping = false }: Props) {
  const first = records[0];

  // Use the most recent record's rate snapshot for invoice-level conversions (e.g. shipping).
  const latestRecord = records.reduce((latest, r) => {
    if (!latest?.dateOfLive) return r;
    if (!r.dateOfLive) return latest;
    return r.dateOfLive > latest.dateOfLive ? r : latest;
  }, first);
  const dailyRates = getRatesForDate(latestRecord?.dateOfLive || '');
  const phpRate = dailyRates.phpRate;

  const convertFromAED = (aedValue: number): number => {
    if (currency === 'PHP') return aedValue * phpRate;
    if (currency === 'USD') return aedValue / USD_TO_AED;
    return aedValue;
  };

  const fmtAmt = (v: number) =>
    `${currency} ${rnd(v).toLocaleString('en-US')}`;

  const items = records.map(r => {
    const category = (r.category || '').toLowerCase().trim();
    const isScrewType = category.includes('screw type');
    const isPerPc = category.includes('per pc');
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = getQty(r);

    // Use per-record rates so each item reflects its own date's PHP rate
    const recordRates = getRatesForDate(r.dateOfLive || '');
    const convertFromAEDForRecord = (aedValue: number): number => {
      if (currency === 'PHP') return aedValue * recordRates.phpRate;
      if (currency === 'USD') return aedValue / USD_TO_AED;
      return aedValue;
    };

    // Display rate: derived from the per-unit AED rate
    const rateAED = clientRateAED(r);
    const displayRate = rnd(convertFromAEDForRecord(rateAED));

    // Amount: rate × grams/qty — always consistent with the displayed Rate column
    let amount: number;
    if (isScrewType || isPerPc) {
      amount = rnd(displayRate * qtyValue);
    } else if (isPc || gramsValue === 0) {
      amount = displayRate;
    } else {
      amount = rnd(displayRate * gramsValue);
    }

    let gramsDisplay = '';
    if (isScrewType || isPerPc) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = (isPc || gramsValue === 0) ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: (isPc || isScrewType || isPerPc),
      rate: displayRate,
      amount,
      liver: r.liverName?.trim() || '',
      date: formatDate(r.dateOfLive),
      mop: (r.modeOfPayment || '').trim().toUpperCase(),
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  // Promo SF takes priority: find the record that has it set (may not be `first`)
  const promoRecord = records.find(r => isPromoSf(r));
  const anyFreeSf = !promoRecord && records.some(r => isFreeSf(r));
  const shippingAED = anyFreeSf ? 0 : calcShippingFee(promoRecord || first);
  const shipping = currency === 'USD' ? Math.ceil(convertFromAED(shippingAED)) : rnd(convertFromAED(shippingAED));
  const additionalAED = n(first?.additionalCharges);
  const additional = rnd(convertFromAED(additionalAED));
  const hasCcItems = records.some(r => (r.modeOfPayment || '') === 'Credit Card');
  const ccItemsTotal = items.reduce((s, item, idx) => {
    const r = records[idx];
    if ((r.modeOfPayment || '') !== 'Credit Card') return s;
    return s + item.amount;
  }, 0);
  // When ccIncludeShipping is true, apply 5% on (cc items + shipping); otherwise just cc items
  const ccBase = ccIncludeShipping && hasCcItems ? ccItemsTotal + shipping : ccItemsTotal;
  const ccFee = rnd(ccBase * 0.05);
  const total = subtotal + shipping + additional + ccFee;

  // Compute total paid (display currency)
  const totalPaidConverted = records.reduce((s, r) => {
    const snap = getRatesForDate(r.dateOfLive || '');
    const rPhpRate = snap.phpRate;

    const convertValue = (val: number, fromCurr: string): number => {
      if (fromCurr === currency) return val;
      let aed = val;
      if (fromCurr === 'PHP') aed = val / rPhpRate;
      else if (fromCurr === 'USD') aed = val * USD_TO_AED;
      return convertFromAED(aed);
    };

    const dpRaw = n(r.downpayment);
    const dpPayCurr = getPaymentCurrency(r);
    let dpConverted: number;
    if (dpRaw <= 0) {
      dpConverted = 0;
    } else if (dpPayCurr === currency) {
      dpConverted = dpRaw;
    } else {
      const dpAED = resolveDownpaymentCurrencyAED(dpRaw, r);
      dpConverted = dpAED > 0 ? convertValue(dpAED, 'AED') : 0;
    }

    const otherRaw = n(r.la1MonthPayment) + n(r.la2MonthPayment) + n(r.la3MonthPayment) + n(r.la4MonthPayment) + n(r.amountReceived);
    const itemCurr = getEffectiveCurrency(r);
    const otherConverted = otherRaw > 0 ? convertValue(otherRaw, itemCurr) : 0;

    return s + dpConverted + otherConverted;
  }, 0);
  const totalPaidConverted_rounded = rnd(totalPaidConverted);

  // ─── PHP CANONICAL BALANCE CHECK ────────────────────────────────────────────
  // When all payments are in PHP (GCash) and we're viewing in AED/USD, rounding
  // artifacts can falsely show a tiny "store credit" (e.g. AED 1, USD 3).
  // Root cause: invoice total in AED = sum of individually-rounded item amounts
  //   (e.g. 248 + 84 = 332), but paid-AED = 5,587 / phpRate = 332.56 → 333.
  // Fix: recompute total in PHP using the exact same display algorithm, compare
  // to raw PHP paid. If PHP balance = 0, the customer is fully paid in all currencies.
  const allPhpPayments = totalPaidConverted_rounded > 0 &&
    records.every(r => getPaymentCurrency(r) === 'PHP');
  let isCanonicallyPaid = false;
  if (allPhpPayments && currency !== 'PHP') {
    const phpItemAmounts = records.map(r => calcPhpItemAmount(r));
    const phpSubtotal = phpItemAmounts.reduce((s, a) => s + a, 0);
    const phpShipping = anyFreeSf ? 0 : rnd(calcShippingFee(promoRecord || first) * phpRate);
    const phpAdditional = rnd(additionalAED * phpRate);
    const phpCcItemsTotal = phpItemAmounts.reduce((s, amt, idx) => {
      const r = records[idx];
      return (r.modeOfPayment || '') === 'Credit Card' ? s + amt : s;
    }, 0);
    const phpCcBase = ccIncludeShipping && hasCcItems ? phpCcItemsTotal + phpShipping : phpCcItemsTotal;
    const phpCcFee = rnd(phpCcBase * 0.05);
    const phpTotal = phpSubtotal + phpShipping + phpAdditional + phpCcFee;
    const phpPaid = records.reduce((s, r) =>
      s + n(r.downpayment) + n(r.la1MonthPayment) + n(r.la2MonthPayment) +
      n(r.la3MonthPayment) + n(r.la4MonthPayment) + n(r.amountReceived), 0);
    isCanonicallyPaid = Math.abs(phpTotal - rnd(phpPaid)) < 1;
  }
  // ────────────────────────────────────────────────────────────────────────────

  // When canonically paid: force displayed paid = total so all 3 rows are consistent.
  // (Avoids showing e.g. Total=332, Paid=333, Balance=0 which looks wrong.)
  const displayedPaid = isCanonicallyPaid ? total : totalPaidConverted_rounded;
  const balanceDue = isCanonicallyPaid ? 0 : total - totalPaidConverted_rounded;

  const totalGrams = records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('diamond')) return s;
    return s + n(r.grams);
  }, 0);

  const isStoreCredit = displayedPaid > 0 && balanceDue < 0;
  const amountForWords = total;
  const amountInWords = numberToWords(amountForWords, currency);

  const uniqueMops = [...new Set(items.map(i => i.mop).filter(Boolean))];
  const mixedMops = uniqueMops.length > 1;

  const isLayaway = records.every(r => r.status === 'Layaway');

  const mopLabel = (() => {
    if (isLayaway) return null;
    if (mixedMops) return null;
    const mop = (first?.modeOfPayment || '').trim();
    if (!mop) return null;
    return mop.toUpperCase();
  })();

  const invoiceDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const invoiceNo = records.map(r => r.pureWeight).find(Boolean);
  const empire = isEmpirePage(first?.page);
  const brandName = empire ? 'EMPIRE GOLD BY ETG' : 'MYKABAYAN JEWELLERY';
  const logoUrl = empire ? EMPIRE_LOGO_URL : MYK_LOGO_URL;
  const watermarkText = empire ? 'EMPIRE GOLD OFFICIAL' : 'MYKABAYAN OFFICIAL';

  const summaryRows: { label: string; value: string; red?: boolean; green?: boolean }[] = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
    ...(displayedPaid > 0 ? [
      { label: 'TOTAL PAID', value: `- ${fmtAmt(displayedPaid)}`, red: true },
      isStoreCredit
        ? { label: '🎁 STORE CREDIT', value: fmtAmt(Math.abs(balanceDue)), red: false, green: true }
        : { label: 'BALANCE DUE', value: fmtAmt(balanceDue), red: true },
    ] : []),
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ position: 'relative', fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>

      <div style={{
        position: 'absolute',
        top: '40%',
        left: '50%',
        transform: 'translate(-50%, -50%) rotate(-35deg)',
        fontSize: '65px',
        color: 'rgba(150, 150, 150, 0.12)',
        fontWeight: 900,
        whiteSpace: 'nowrap',
        pointerEvents: 'none',
        zIndex: 0,
        userSelect: 'none',
        textAlign: 'center'
      }}>
        {watermarkText}<br/>
        {invoiceNo || ''}
      </div>

      <div style={{ position: 'relative', zIndex: 1 }}>
        <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0, background: '#fff' }}>
          <em style={{ fontSize: 14 }}>Statement of Account</em>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '65%', padding: '12px 16px', verticalAlign: 'top', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 24, letterSpacing: 1 }}>{brandName}</div>
                <div style={{ marginTop: 8, textAlign: 'left', fontSize: 11 }}>SATWA, DUBAI, UNITED ARAB EMIRATES</div>
                <div style={{ marginTop: 4, fontSize: 11 }}>WhatsApp &amp; Contact no.: +971 52 825 2405</div>
              </td>
              <td style={{ width: '35%', padding: '12px 16px', verticalAlign: 'middle', textAlign: 'center', border: '1px solid #999' }}>
                <img src={logoUrl} crossOrigin="anonymous" alt="Logo" style={{ width: empire ? '150px' : '80px', height: empire ? '100px' : '80px', objectFit: 'contain', display: 'block', margin: '0 auto' }} />
              </td>
            </tr>
            <tr>
              <td style={{ padding: '10px 16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 700, fontSize: 20, textAlign: 'center', letterSpacing: 1 }}>
                  {(first?.minerName || '').toUpperCase()}
                </div>
              </td>
              <td style={{ padding: '8px', textAlign: 'center', border: '1px solid #999' }}>
                <div style={{ fontWeight: 600, fontSize: 13 }}>{invoiceDate}</div>
                <div style={{ fontSize: 11, marginTop: 4 }}>Date Printed</div>
                {invoiceNo && (
                  <div style={{ marginTop: 8, borderTop: '1px solid #ccc', paddingTop: 6 }}>
                    <div style={{ fontWeight: 700, fontSize: 13, fontFamily: 'monospace', color: '#c00' }}>{invoiceNo}</div>
                    <div style={{ fontSize: 10, color: '#666', marginTop: 2 }}>Account ID / Invoice #</div>
                  </div>
                )}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <thead>
            <tr style={{ background: 'rgba(224, 224, 224, 0.9)' }}>
              {['Date', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
                <th key={h} style={{ border: '1px solid #999', padding: '6px 8px', textAlign: 'center', fontSize: 11 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => (
              <tr key={i}>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#666' }}>{item.date}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, fontWeight: 600 }}>
                  {item.desc.toUpperCase()}
                  {item.liver && <div style={{ fontSize: 9, fontWeight: 400, color: '#888', marginTop: 2 }}>Liver: {item.liver}</div>}
                  {mixedMops && item.mop && (
                    <div style={{ marginTop: 4, display: 'flex', justifyContent: 'center' }}>
                      <span style={{ display: 'inline-block', border: '1.5px solid red', color: 'red', padding: '1px 6px', fontWeight: 900, fontSize: 8, letterSpacing: '1px', transform: 'rotate(-4deg)', transformOrigin: 'center' }}>
                        {item.mop}
                      </span>
                    </div>
                  )}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.tog.toUpperCase()}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: item.isPc ? 'red' : '#111', fontWeight: item.isPc ? 700 : 400 }}>
                  {item.gramsDisplay}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.rate.toLocaleString('en-US')}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'right', fontSize: 11 }}>{fmtAmt(item.amount)}</td>
              </tr>
            ))}
            {Array.from({ length: emptyRows }).map((_, i) => (
              <tr key={`empty-${i}`} style={{ height: 22 }}>
                {[1,2,3,4,5,6].map(c => <td key={c} style={{ border: '1px solid #999' }}>&nbsp;</td>)}
              </tr>
            ))}
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '50%', padding: '16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 26, lineHeight: 1.2, textAlign: 'center' }}>
                  CUSTOMER'S INVOICE<br />COPY
                </div>
                {mopLabel && (
                  <div style={{ marginTop: '8px', textAlign: 'center' }}>
                    <div style={{ display: 'inline-block', border: '2px solid red', color: 'red', padding: '4px 12px', fontWeight: 900, fontSize: '18px', letterSpacing: '2px', textTransform: 'uppercase' }}>
                      {mopLabel}
                    </div>
                  </div>
                )}
                {isLayaway && (
                  <div style={{ marginTop: '8px', textAlign: 'center' }}>
                    <div style={{ display: 'inline-block', border: '3px solid #7c3aed', color: '#7c3aed', padding: '4px 14px', fontWeight: 900, fontSize: '18px', letterSpacing: '3px', transform: 'rotate(-5deg)', transformOrigin: 'center' }}>
                      LAYAWAY
                    </div>
                  </div>
                )}
              </td>
              <td style={{ padding: 0, verticalAlign: 'top', border: '1px solid #999' }}>
                {summaryRows.map((row, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', background: row.green ? 'rgba(220, 252, 231, 0.9)' : row.red ? 'rgba(255, 240, 240, 0.9)' : (i % 2 === 0 ? 'rgba(224, 224, 224, 0.9)' : 'rgba(245, 245, 245, 0.9)'), padding: '5px 10px', borderBottom: '1px solid #ccc' }}>
                    <span style={{ fontWeight: 700, fontSize: 11, color: row.green ? '#166534' : row.red ? '#cc0000' : '#111' }}>{row.label}</span>
                    <span style={{ fontSize: 11, fontWeight: (row.red || row.green) ? 700 : 400, color: row.green ? '#166534' : row.red ? '#cc0000' : '#111' }}>{row.value}</span>
                  </div>
                ))}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ padding: '4px 12px', border: '1px solid #999', borderBottom: 'none' }}>
                <span style={{ color: isStoreCredit ? '#166534' : 'red', fontWeight: 700, fontSize: 11 }}>
                  {isStoreCredit ? '🎁 Store Credit in Words:' : 'Amount in Words:'}
                </span>
              </td>
            </tr>
            <tr>
              <td style={{ padding: '4px 12px 10px', textAlign: 'center', fontWeight: 700, fontSize: 13, border: '1px solid #999' }}>
                {amountInWords}
              </td>
            </tr>
          </tbody>
        </table>

        <div style={{ padding: '8px 12px', border: '1px solid #999', marginTop: -1, background: '#fff' }}>
          <div style={{ color: 'red', fontWeight: 700, fontSize: 12, marginBottom: 4 }}>NOTE:</div>
          {NOTES.map((note, i) => (
            <div key={i} style={{ fontSize: 10, marginBottom: 2 }}>{i + 1}. {note}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useState, useRef } from 'react';
import { Upload, X, Loader2, CheckCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from '@/components/ui/sheet';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { uploadFile } from 'zite-file-upload-sdk';
import { createUpload } from 'zite-endpoints-sdk';

interface Props {
  onRefresh: () => void;
}

export default function UploadMasterlistFAB({ onRefresh }: Props) {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleUpload = async () => {
    if (!selectedFile) { toast.error('Please select a file'); return; }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: selectedFile, filename: selectedFile.name });
      await createUpload({ masterlistFile: fileUrl, status: 'Uploaded' });
      toast.success('File uploaded successfully! Refresh the records when processing is complete.');
      setOpen(false);
      setSelectedFile(null);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>
        <Button size="sm" className="h-7 px-2 text-[10px] sm:text-xs bg-primary text-primary-foreground cursor-pointer">
          <Upload className="h-3 w-3 sm:mr-1" />
          <span className="hidden sm:inline">Upload Masterlist</span>
          <span className="sm:hidden">Upload</span>
        </Button>
      </SheetTrigger>

      <SheetContent side="bottom" className="bg-card border-border pb-8">
        <SheetHeader className="mb-4">
          <SheetTitle className="font-cinzel text-primary">Upload Masterlist</SheetTitle>
        </SheetHeader>
        <div className="space-y-4">
          <div>
            <Label className="text-sm text-muted-foreground mb-2 block">Select Excel / CSV File</Label>
            <div
              className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer"
              onClick={() => fileRef.current?.click()}
            >
              {selectedFile ? (
                <div className="flex items-center justify-center gap-2">
                  <CheckCircle className="h-4 w-4 text-primary" />
                  <span className="text-sm text-foreground">{selectedFile.name}</span>
                  <button onClick={e => { e.stopPropagation(); setSelectedFile(null); }}>
                    <X className="h-4 w-4 text-muted-foreground" />
                  </button>
                </div>
              ) : (
                <div>
                  <Upload className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
                  <p className="text-sm text-muted-foreground">Tap to select file</p>
                </div>
              )}
            </div>
            <input ref={fileRef} type="file" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
          </div>
          <Button onClick={handleUpload} disabled={uploading || !selectedFile} className="w-full bg-primary text-primary-foreground">
            {uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Uploading...</> : 'Upload File'}
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen, Plus, Calendar, Clock, PauseCircle, ShieldCheck, BarChart2, Merge, AlertTriangle, Package } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMiner, groupByMinerName, formatDate } from '@/lib/formatters';
import { isOverdue } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';
import AddClientModal from '@/components/accounts/AddClientModal';
import DailyRatesEditor from '@/components/admin/DailyRatesEditor';
import MergeClientsModal from '@/components/admin/MergeClientsModal';
import { Button } from '@/components/ui/button';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail, userFirstName, onRefresh }: TabProps) {
  const [expandedPages, setExpandedPages] = useState<Record<string, boolean>>({});
  const [expandedResellers, setExpandedResellers] = useState<Record<string, boolean>>({});
  const [expandedOutsources, setExpandedOutsources] = useState<Record<string, boolean>>({});
  const [expandedReviewChasing, setExpandedReviewChasing] = useState<Record<string, boolean>>({});
  const [expandedWFDP, setExpandedWFDP] = useState<Record<string, boolean>>({});
  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});
  const [showAddModal, setShowAddModal] = useState(false);
  const [showMergeModal, setShowMergeModal] = useState(false);
  const [needsActionOnly, setNeedsActionOnly] = useState(false);
  const [showItemHold, setShowItemHold] = useState(false);

  // Pipeline summary counts (global, across all pages)
  const pipelineSummary = useMemo(() => {
    const active = records.filter(r => {
      const s = r.status || '';
      return ['Pending', 'Waiting for Details', 'Waiting for Downpayment', 'Reseller', 'Outsource',

        'Payment for Verification', 'Delivered'].includes(s);
    });
    return {
      pending: active.filter(r => r.status === 'Pending' || r.status === 'Waiting for Details').length,
      wfdp: active.filter(r => r.status === 'Waiting for Downpayment').length,
      verif: active.filter(r => r.status === 'Payment for Verification').length,
      reseller: active.filter(r => r.status === 'Reseller').length,
      outsource: active.filter(r => r.status === 'Outsource').length,
      reviewChasing: active.filter(r => r.status === 'Delivered' && r.reviewChasing !== 'Skipped' && r.reviewChasing !== 'Completed').length,
      itemHold: records.filter(r => r.status === 'Paid/DP but Item Hold').length,
      needsAction: records.filter(r => isOverdue(r)).length,
      total: active.length,
    };
  }, [records]);

  const pageGroups = useMemo(() => {
    const searched = applySearch(records, searchQuery);
    const activeAdminRecords = searched.filter(r => {
      const status = r.status || '';
      if (status === 'Pending' || status === 'Waiting for Details' || status === 'Waiting for Downpayment') return true;
      if (status === 'Reseller' || status === 'Outsource') return true;
      if (status === 'Payment for Verification') return true;
      if (status === 'Delivered') {
        if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
        return true;
      }
      if (showItemHold && status === 'Paid/DP but Item Hold') return true;
      return false;
    });

    // Apply "Needs Action" filter: only show overdue records
    const filtered = needsActionOnly ? activeAdminRecords.filter(r => isOverdue(r)) : activeAdminRecords;

    const groups: Record<string, DatabaseRowType[]> = {};
    filtered.forEach(r => {
      let pageKey = (r.page || 'Other').trim();
      if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
      else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
      if (!groups[pageKey]) groups[pageKey] = [];
      groups[pageKey].push(r);
    });

    return Object.keys(groups)
      .sort((a, b) => {
        if (a === 'MYK') return -1; if (b === 'MYK') return 1;
        if (a === 'Empire Gold By ETG') return -1; if (b === 'Empire Gold By ETG') return 1;
        return a.localeCompare(b);
      })
      .reduce((acc, key) => { acc[key] = groups[key]; return acc; }, {} as Record<string, DatabaseRowType[]>);
  }, [records, searchQuery, needsActionOnly, showItemHold]);

  const togglePage = (page: string) =>
    setExpandedPages(prev => ({ ...prev, [page]: !prev[page] }));

  const toggleDate = (key: string) =>
    setExpandedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const groupMinedByDate = (minedItems: DatabaseRowType[]): Map<string, Map<string, DatabaseRowType[]>> => {
    const byDate = new Map<string, Map<string, DatabaseRowType[]>>();
    for (const r of minedItems) {
      const date = r.dateOfLive || 'Unknown Date';
      const miner = r.minerName?.trim() || 'Unknown Client';
      if (!byDate.has(date)) byDate.set(date, new Map());
      const byMiner = byDate.get(date)!;
      if (!byMiner.has(miner)) byMiner.set(miner, []);
      byMiner.get(miner)!.push(r);
    }
    return new Map([...byDate.entries()].sort((a, b) => b[0].localeCompare(a[0])));
  };

  const renderPageSection = (pageName: string, pageRecords: DatabaseRowType[]) => {
    const isExpanded = expandedPages[pageName] === true;
    const minedItems = pageRecords.filter(r =>
      r.status === 'Pending' || r.status === 'Waiting for Details'
    );
    const wfdpItems = pageRecords.filter(r => r.status === 'Waiting for Downpayment');
    const resellerItems = pageRecords.filter(r => r.status === 'Reseller');
    const outsourceItems = pageRecords.filter(r => r.status === 'Outsource');
    const paymentVerifItems = pageRecords.filter(r => r.status === 'Payment for Verification');
    const paymentVerifByDate = groupMinedByDate(paymentVerifItems);
    const reviewChasingItems = pageRecords.filter(r => r.status === 'Delivered');
    const itemHoldItems = pageRecords.filter(r => r.status === 'Paid/DP but Item Hold');
    const minedByDate = groupMinedByDate(minedItems);
    const wfdpByDate = groupMinedByDate(wfdpItems);
    const resellerGrouped = groupByMiner(resellerItems);
    const outsourceGrouped = groupByMiner(outsourceItems);
    const reviewChasingGroups = groupByMinerName(reviewChasingItems);
    const itemHoldGrouped = groupByMiner(itemHoldItems);

    // Mini status chips for page header
    const statusChips = [
      { label: 'Pending', count: minedItems.length, color: 'bg-primary/20 text-primary' },
      { label: 'WFDP', count: wfdpItems.length, color: 'bg-orange-400/20 text-orange-400' },
      { label: 'Verif', count: paymentVerifItems.length, color: 'bg-cyan-400/20 text-cyan-400' },
      { label: 'Reseller', count: resellerItems.length, color: 'bg-teal-400/20 text-teal-400' },
      { label: 'Outsource', count: outsourceItems.length, color: 'bg-teal-400/20 text-teal-400' },
      { label: 'Review', count: reviewChasingItems.length, color: 'bg-yellow-400/20 text-yellow-400' },
      { label: 'On Hold', count: itemHoldItems.length, color: 'bg-violet-400/20 text-violet-400' },
    ].filter(c => c.count > 0);

    return (
      <div key={pageName} className="mb-6">
        <div
          className="flex items-center gap-3 py-2.5 px-4 bg-secondary/40 rounded-xl cursor-pointer mb-4 border border-primary/10 hover:bg-secondary/60 transition-colors"
          onClick={() => togglePage(pageName)}
        >
          {pageName === 'MYK' ? <Crown className="h-5 w-5 text-yellow-500" />
            : pageName === 'Empire Gold By ETG' ? <BookOpen className="h-5 w-5 text-primary" />
            : <Layout className="h-5 w-5 text-muted-foreground" />}
          <h2 className="font-cinzel text-base font-bold text-primary tracking-widest uppercase">{pageName}</h2>
          <div className="flex items-center gap-1 flex-wrap">
            {statusChips.map(c => (
              <span key={c.label} className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${c.color}`}>
                {c.label} {c.count}
              </span>
            ))}
          </div>
          <div className="h-px flex-1 bg-primary/10" />
          <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{pageRecords.length}</span>
          <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>

        {isExpanded && (
          <div className="pl-2 sm:pl-4 space-y-8 animate-in fade-in slide-in-from-top-2 duration-300">
            {minedByDate.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] pl-1">Mined Items</span>
                  <div className="h-px flex-1 bg-border/60" />
                </div>
                {Array.from(minedByDate.entries()).map(([date, minerMap]) => {
                  const dateKey = `${pageName}__${date}`;
                  const isDateExpanded = expandedDates[dateKey] === true;
                  const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                  return (
                    <div key={date} className="mb-3">
                      <div
                        className="flex items-center gap-2 py-2 px-3 bg-primary/10 rounded-lg cursor-pointer mb-2 border border-primary/20 hover:bg-primary/15 transition-colors"
                        onClick={() => toggleDate(dateKey)}
                      >
                        <Calendar className="h-3.5 w-3.5 text-primary" />
                        <span className="text-xs font-bold text-primary uppercase tracking-widest">{formatDate(date)}</span>
                        <div className="h-px flex-1 bg-primary/20" />
                        <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
                        <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                      </div>
                      {isDateExpanded && (
                        <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                          {Array.from(minerMap.entries()).map(([name, items]) => (
                            <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {wfdpByDate.size > 0 && (() => {
              const isWFDPExpanded = expandedWFDP[pageName] === true;
              const totalWFDP = wfdpItems.length;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-3 cursor-pointer"
                    onClick={() => setExpandedWFDP(prev => ({ ...prev, [pageName]: !prev[pageName] }))}
                  >
                    <Clock className="h-3.5 w-3.5 text-orange-400" />
                    <span className="text-[10px] font-black text-orange-400 uppercase tracking-[0.2em] pl-1">Waiting for Downpayment</span>
                    <div className="h-px flex-1 bg-orange-400/20" />
                    <span className="text-[10px] font-bold bg-orange-400/20 text-orange-400 px-2 py-0.5 rounded-md">{totalWFDP}</span>
                    <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform duration-200 ${isWFDPExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isWFDPExpanded && (
                    <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                      {Array.from(wfdpByDate.entries()).map(([date, minerMap]) => {
                        const dateKey = `wfdp__${pageName}__${date}`;
                        const isDateExpanded = expandedDates[dateKey] === true;
                        const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                        return (
                          <div key={date} className="mb-3">
                            <div
                              className="flex items-center gap-2 py-2 px-3 bg-orange-400/10 rounded-lg cursor-pointer mb-2 border border-orange-400/20 hover:bg-orange-400/15 transition-colors"
                              onClick={() => toggleDate(dateKey)}
                            >
                              <Calendar className="h-3.5 w-3.5 text-orange-400" />
                              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-orange-400/20" />
                              <span className="text-[10px] font-bold bg-orange-400/20 text-orange-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {paymentVerifByDate.size > 0 && (() => {
              const isVerifExpanded = expandedDates[`verif__${pageName}`] === true;
              const totalVerif = paymentVerifItems.length;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-3 cursor-pointer"
                    onClick={() => toggleDate(`verif__${pageName}`)}
                  >
                    <ShieldCheck className="h-3.5 w-3.5 text-cyan-400" />
                    <span className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.2em] pl-1">Payment for Verification</span>
                    <div className="h-px flex-1 bg-cyan-400/20" />
                    <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalVerif}</span>
                    <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isVerifExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isVerifExpanded && (
                    <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                      {Array.from(paymentVerifByDate.entries()).map(([date, minerMap]) => {
                        const dateKey = `verif__${pageName}__${date}`;
                        const isDateExpanded = expandedDates[dateKey] === true;
                        const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                        return (
                          <div key={date} className="mb-3">
                            <div
                              className="flex items-center gap-2 py-2 px-3 bg-cyan-400/10 rounded-lg cursor-pointer mb-2 border border-cyan-400/20 hover:bg-cyan-400/15 transition-colors"
                              onClick={() => toggleDate(dateKey)}
                            >
                              <Calendar className="h-3.5 w-3.5 text-cyan-400" />
                              <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-cyan-400/20" />
                              <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {resellerGrouped.size > 0 && (() => {
              const isResellerExpanded = expandedResellers[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedResellers(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                    <div className="h-px flex-1 bg-teal-500/20" />
                    <span className="text-[10px] font-bold bg-teal-500/20 text-teal-500 px-2 py-0.5 rounded-md">{resellerGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-500 transition-transform duration-200 ${isResellerExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isResellerExpanded && Array.from(resellerGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {outsourceGrouped.size > 0 && (() => {
              const isOutsourceExpanded = expandedOutsources[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedOutsources(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-400 uppercase tracking-[0.2em] pl-1">Outsource</span>
                    <div className="h-px flex-1 bg-teal-400/20" />
                    <span className="text-[10px] font-bold bg-teal-400/20 text-teal-400 px-2 py-0.5 rounded-md">{outsourceGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-400 transition-transform duration-200 ${isOutsourceExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isOutsourceExpanded && Array.from(outsourceGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {reviewChasingGroups.size > 0 && (() => {
              const isReviewExpanded = expandedReviewChasing[pageName] === true;
              // Split: Pending on top, Chased below (collapsible)
              const pendingEntries = Array.from(reviewChasingGroups.entries()).filter(([, items]) => {
                const s = (items[0]?.reviewChasing || 'Pending');
                return s !== 'Chased' && s !== 'Skipped' && s !== 'Completed';
              });
              const chasedEntries = Array.from(reviewChasingGroups.entries()).filter(([, items]) => {
                const s = (items[0]?.reviewChasing || 'Pending');
                return s === 'Chased' || s === 'Skipped' || s === 'Completed';
              });
              const [chasedOpen, setChasedOpen] = expandedReviewChasing[`${pageName}__chased`] !== undefined
                ? [expandedReviewChasing[`${pageName}__chased`], (v: boolean) => setExpandedReviewChasing(prev => ({ ...prev, [`${pageName}__chased`]: v }))]
                : [false, (v: boolean) => setExpandedReviewChasing(prev => ({ ...prev, [`${pageName}__chased`]: v }))];
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedReviewChasing(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-yellow-400 uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                    <div className="h-px flex-1 bg-yellow-400/20" />
                    <span className="text-[10px] font-bold bg-yellow-400/20 text-yellow-400 px-2 py-0.5 rounded-md">{reviewChasingGroups.size}</span>
                    <ChevronDown className={`h-4 w-4 text-yellow-400 transition-transform duration-200 ${isReviewExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isReviewExpanded && (
                    <div className="space-y-3">
                      {/* Pending first */}
                      {pendingEntries.map(([name, items]) => (
                        <ReviewChasingCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} />
                      ))}
                      {/* Chased / done — collapsible */}
                      {chasedEntries.length > 0 && (
                        <div>
                          <button
                            className="flex items-center gap-2 w-full text-left py-1"
                            onClick={() => setChasedOpen(!chasedOpen)}
                          >
                            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wide">Chased / Done ({chasedEntries.length})</span>
                            <div className="h-px flex-1 bg-border/40" />
                            <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform duration-200 ${chasedOpen ? 'rotate-180' : ''}`} />
                          </button>
                          {chasedOpen && (
                            <div className="space-y-3 mt-2">
                              {chasedEntries.map(([name, items]) => (
                                <ReviewChasingCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} />
                              ))}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })()}

            {showItemHold && itemHoldGrouped.size > 0 && (() => {
              const isHoldExpanded = expandedDates[`hold__${pageName}`] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => toggleDate(`hold__${pageName}`)}
                  >
                    <Package className="h-3.5 w-3.5 text-violet-400" />
                    <span className="text-[10px] font-black text-violet-400 uppercase tracking-[0.2em] pl-1">Items on Hold</span>
                    <div className="h-px flex-1 bg-violet-400/20" />
                    <span className="text-[10px] font-bold bg-violet-400/20 text-violet-400 px-2 py-0.5 rounded-md">{itemHoldItems.length}</span>
                    <ChevronDown className={`h-4 w-4 text-violet-400 transition-transform duration-200 ${isHoldExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isHoldExpanded && Array.from(itemHoldGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Admin Pipeline" subtitle="Active Tasks & Pipeline" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <DailyRatesEditor date={new Date().toISOString().split('T')[0]} />

        {/* Pipeline Summary Strip */}
        {pipelineSummary.total > 0 && (
          <div className="flex items-center gap-1.5 flex-wrap mb-3 p-3 rounded-xl bg-secondary/30 border border-border">
            <BarChart2 className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
            <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-wide mr-1">Pipeline:</span>
            {pipelineSummary.pending > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-primary/15 text-primary border border-primary/20">
                Pending {pipelineSummary.pending}
              </span>
            )}
            {pipelineSummary.wfdp > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-400/15 text-orange-400 border border-orange-400/20">
                WFDP {pipelineSummary.wfdp}
              </span>
            )}
            {pipelineSummary.verif > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-400/15 text-cyan-400 border border-cyan-400/20">
                Verif {pipelineSummary.verif}
              </span>
            )}
            {pipelineSummary.reseller > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-teal-400/15 text-teal-400 border border-teal-400/20">
                Reseller {pipelineSummary.reseller}
              </span>
            )}
            {pipelineSummary.outsource > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-teal-400/15 text-teal-400 border border-teal-400/20">
                Outsource {pipelineSummary.outsource}
              </span>
            )}
            {pipelineSummary.reviewChasing > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-yellow-400/15 text-yellow-400 border border-yellow-400/20">
                Review {pipelineSummary.reviewChasing}
              </span>
            )}
            {pipelineSummary.itemHold > 0 && (
              <button
                onClick={() => setShowItemHold(v => !v)}
                className={`text-[10px] font-bold px-2 py-0.5 rounded-full border transition-colors ${showItemHold ? 'bg-violet-400/30 text-violet-300 border-violet-400/40' : 'bg-violet-400/15 text-violet-400 border-violet-400/20'}`}
                title="Toggle Items on Hold visibility"
              >
                <Package className="inline h-2.5 w-2.5 mr-0.5" />
                On Hold {pipelineSummary.itemHold}
              </button>
            )}
            <div className="h-px flex-1" />
            <span className="text-[10px] font-bold text-muted-foreground">{pipelineSummary.total} total</span>
          </div>
        )}

        {/* Quick Filter Bar */}
        <div className="flex items-center gap-2 mb-4 flex-wrap">
          {pipelineSummary.needsAction > 0 && (
            <button
              onClick={() => setNeedsActionOnly(v => !v)}
              className={`flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 rounded-full border transition-all ${
                needsActionOnly
                  ? 'bg-destructive text-destructive-foreground border-destructive shadow-sm'
                  : 'bg-destructive/10 text-destructive border-destructive/30 hover:bg-destructive/20'
              }`}
            >
              <AlertTriangle className="h-3 w-3" />
              {needsActionOnly ? 'Showing Overdue Only' : `${pipelineSummary.needsAction} Needs Action`}
              {needsActionOnly && <span className="ml-1 opacity-70">✕</span>}
            </button>
          )}
          <div className="flex-1" />
          <Button variant="outline" onClick={() => setShowMergeModal(true)} className="border-border text-xs h-9">
            <Merge className="h-4 w-4 mr-1.5" /> Merge Clients
          </Button>
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>
      </div>

      <div className="px-4">
        {needsActionOnly && (
          <div className="mb-4 px-3 py-2 rounded-lg bg-destructive/10 border border-destructive/20 text-xs text-destructive font-medium flex items-center gap-2">
            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
            Filtered to {pipelineSummary.needsAction} overdue record{pipelineSummary.needsAction !== 1 ? 's' : ''} — items past their 24h follow-up window.
          </div>
        )}
        {Object.keys(pageGroups).length > 0
          ? Object.keys(pageGroups).map(page => renderPageSection(page, pageGroups[page]))
          : (
            <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
              {needsActionOnly
                ? <p className="text-sm text-green-400 font-medium">✅ All clear — no overdue records!</p>
                : <p className="text-sm text-muted-foreground font-medium">No records found matching your search.</p>
              }
            </div>
          )}
      </div>
      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} existingRecords={records} />}
      {showMergeModal && <MergeClientsModal onClose={() => setShowMergeModal(false)} onRefresh={onRefresh} records={records} />}
    </div>
  );
}

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { formatDate } from '@/lib/formatters';

interface Props {
  date: string;
  onConfirm: (phpRate: number, silverRate?: number, silverBrandedRate?: number) => void;
  onSkip: () => void;
}

export default function PhpRateDialog({ date, onConfirm, onSkip }: Props) {
  const [phpRate, setPhpRateVal] = useState('');
  const [silverRate, setSilverRateVal] = useState('');
  const [silverBrandedRate, setSilverBrandedRateVal] = useState('');

  const phpParsed = parseFloat(phpRate);
  const isValid = !isNaN(phpParsed) && phpParsed > 0;

  const handleConfirm = () => {
    if (!isValid) return;
    const sr = parseFloat(silverRate);
    const sbr = parseFloat(silverBrandedRate);
    onConfirm(phpParsed, isNaN(sr) ? undefined : sr, isNaN(sbr) ? undefined : sbr);
  };

  return (
    <Dialog open onOpenChange={onSkip}>
      <DialogContent className="bg-card border-border max-w-sm">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary text-base">
            Set Rates for {formatDate(date)}
          </DialogTitle>
        </DialogHeader>
        <div className="py-2 space-y-4">
          <p className="text-xs text-muted-foreground">
            Pinas client detected. Set today's rates — these will be locked for all clients on this date.
          </p>

          <div>
            <Label className="text-xs text-muted-foreground">PHP Conversion Rate (1 AED =)</Label>
            <div className="flex items-center gap-2 mt-1">
              <Input type="number" step="0.01" value={phpRate} onChange={e => setPhpRateVal(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleConfirm()}
