import { useMemo } from 'react';
import { useCompactMode } from '@/lib/compactMode';
import { ShieldCheck, Package, Truck, CheckCircle2, AlertTriangle, Clock } from 'lucide-react';
import { DatabaseRowType, TabProps } from '@/types';
import { formatDate } from '@/lib/formatters';
import { parseDateRobust } from '@/lib/calculations';

const COLUMNS = [
  { status: 'Payment for Verification', label: 'Verif.', icon: ShieldCheck, color: 'text-amber-400', bg: 'border-amber-400/30 bg-amber-400/5', urgencyHours: 24 },
  { status: 'For Pullout', label: 'For Pullout', icon: Package, color: 'text-purple-300', bg: 'border-purple-400/30 bg-purple-400/5', urgencyHours: 48 },
  { status: 'Dispatched', label: 'Dispatched', icon: Truck, color: 'text-orange-400', bg: 'border-orange-400/30 bg-orange-400/5', urgencyHours: 72 },
  { status: 'Delivered', label: 'Delivered', icon: CheckCircle2, color: 'text-green-400', bg: 'border-green-400/30 bg-green-400/5', urgencyHours: 999 },
] as const;

function daysAgo(dateStr?: string): number {
  if (!dateStr) return 0;
  const d = parseDateRobust(dateStr);
  if (!d) return 0;
  return Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24));
}

function AgingBadge({ dateStr, urgencyHours }: { dateStr?: string; urgencyHours: number }) {
  const days = daysAgo(dateStr);
  const hours = days * 24;
  const isUrgent = hours >= urgencyHours;
  const isWarning = hours >= urgencyHours * 0.5;
  if (days === 0) return <span className="text-[9px] text-muted-foreground">Today</span>;
  return (
    <span className={`inline-flex items-center gap-0.5 text-[9px] font-semibold px-1.5 py-0.5 rounded-full ${isUrgent ? 'bg-destructive/20 text-destructive' : isWarning ? 'bg-amber-400/20 text-amber-400' : 'bg-secondary text-muted-foreground'}`}>
      {isUrgent && <AlertTriangle className="h-2.5 w-2.5" />}
      {days}d
    </span>
  );
}

interface Props {
  records: DatabaseRowType[];
  onUpdate: TabProps['onUpdate'];
}

export default function KanbanView({ records, onUpdate }: Props) {
  const { isCompact } = useCompactMode();
  const kanbanData = useMemo(() => {
    const kanbanStatuses = new Set(COLUMNS.map(c => c.status as string));
    // Also include 'Dispatch' as part of 'For Pullout'
    return COLUMNS.map(col => {
      const items = records.filter(r => {
        const s = r.status || '';
        if (col.status === 'For Pullout') return s === 'For Pullout' || s === 'Dispatch';
        return s === col.status;
      });
      return { ...col, items };
    });
  }, [records]);

  const moveToNext = async (record: DatabaseRowType, currentStatus: string) => {
    const idx = COLUMNS.findIndex(c => c.status === currentStatus || (currentStatus === 'Dispatch' && c.status === 'For Pullout'));
    if (idx === -1 || idx >= COLUMNS.length - 1) return;
    const nextStatus = COLUMNS[idx + 1].status;
    await onUpdate(record.id, { status: nextStatus });
  };

  return (
    <div className="flex gap-3 overflow-x-auto pb-4 -mx-4 px-4">
      {kanbanData.map(col => {
        const Icon = col.icon;
        return (
          <div key={col.status} className={`flex-shrink-0 w-64 rounded-xl border ${col.bg} flex flex-col`}>
            {/* Column Header */}
            <div className="p-3 border-b border-border/40 flex items-center gap-2">
              <Icon className={`h-4 w-4 ${col.color} shrink-0`} />
              <span className={`font-cinzel text-xs font-bold ${col.color} uppercase tracking-wide flex-1`}>{col.label}</span>
              <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-white/10 ${col.color}`}>{col.items.length}</span>
            </div>

            {/* Cards */}
            <div className="flex flex-col gap-2 p-2 overflow-y-auto max-h-[60vh]">
              {col.items.length === 0 ? (
                <p className="text-[10px] text-muted-foreground text-center py-4">No items</p>
              ) : (
                col.items.map(r => (
                  <div key={r.id} className="rounded-lg border border-border bg-card p-3 space-y-1.5">
                    <div className="flex items-start justify-between gap-1">
                      <p className="text-xs font-bold text-foreground leading-tight">{r.minerName || '—'}</p>
                      <AgingBadge dateStr={r.dateOfLive} urgencyHours={col.urgencyHours} />
                    </div>
                    <p className="text-[10px] text-muted-foreground line-clamp-2 leading-snug">{r.itemDescription || '—'}</p>
                    {!isCompact && r.dateOfLive && (
                      <p className="text-[9px] text-muted-foreground flex items-center gap-1">
                        <Clock className="h-2.5 w-2.5" />{formatDate(r.dateOfLive)}
                      </p>
                    )}
                    <div className="flex items-center justify-between pt-1 border-t border-border/40">
                      <span className="text-[9px] text-muted-foreground font-mono">{r.orderId || `#${r.id}`}</span>
                      {col.status !== 'Delivered' && (
                        <button
                          onClick={() => moveToNext(r, r.status || '')}
                          className={`text-[9px] font-semibold px-2 py-0.5 rounded border transition-colors ${col.color} border-current hover:bg-white/10`}
                        >
                          Move →
                        </button>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcTotalPaid, parseDateRobust } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { Copy, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';

interface Props {
  customerId: string;
  minerName: string;
  allRecords: DatabaseRowType[];
  onClose: () => void;
}

export default function CustomerHistoryModal({ customerId, minerName, allRecords, onClose }: Props) {
  const customerRecords = useMemo(() => {
    return allRecords
      .filter(r => r.customerId === customerId)
      .sort((a, b) => {
        const dateA = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
        const dateB = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
        return dateB - dateA;
      });
  }, [allRecords, customerId]);

  const summary = useMemo(() => {
    const totalItems = customerRecords.length;
    // Active = not cancelled/returned/delivered. Delivered = fully settled, no outstanding balance.
    const activeItems = customerRecords.filter(r =>
      r.status !== 'Cancelled' && r.status !== 'Returned Item' && r.status !== 'Delivered'
    );
    const totalSpent = activeItems.reduce((sum, r) => sum + calcItemPriceAED(r), 0);
    const totalPaid = activeItems.reduce((sum, r) => sum + calcTotalPaid(r), 0);
    const balance = Math.max(0, totalSpent - totalPaid);
    return { totalItems, activeCount: activeItems.length, totalSpent, balance };
  }, [customerRecords]);

  const handleCopyId = () => {
    navigator.clipboard.writeText(customerId);
    toast.success('Customer ID copied to clipboard!');
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary flex items-center justify-between pr-6">
            <span>Client Ledger: {minerName.toUpperCase()}</span>
            <button 
              onClick={handleCopyId}
              className="group flex items-center gap-1.5 px-2.5 py-1 rounded bg-secondary/50 hover:bg-primary/10 transition-colors border border-border hover:border-primary/30"
              title="Copy Customer ID"
            >
              <span className="text-xs font-mono text-muted-foreground group-hover:text-primary transition-colors">{customerId}</span>
              <Copy className="h-3 w-3 text-muted-foreground group-hover:text-primary transition-colors" />
            </button>
          </DialogTitle>
        </DialogHeader>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 my-4">
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Total Items</p>
            <p className="text-lg font-bold">{summary.totalItems}</p>
          </div>
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Pending Items</p>
            <p className="text-lg font-bold">{summary.activeCount}</p>
          </div>
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Total Value</p>
            <p className="text-lg font-bold text-foreground">AED {summary.totalSpent.toFixed(2)}</p>
          </div>
          <div className="bg-primary/5 border border-primary/20 rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-primary/80 mb-1">Outstanding</p>
            <p className={`text-lg font-bold ${summary.balance > 0 ? 'text-destructive' : 'text-green-500'}`}>
              AED {summary.balance.toFixed(2)}
            </p>
          </div>
        </div>

        <div className="space-y-3">
          {customerRecords.map(record => {
            const price = calcItemPriceAED(record);
            const paid = calcTotalPaid(record);
            const balance = Math.max(0, price - paid);
            const isDead = record.status === 'Cancelled' || record.status === 'Returned Item';
            const isDelivered = record.status === 'Delivered';

            return (
              <div key={record.id} className={`p-4 rounded-xl border ${isDead ? 'border-border/50 bg-background/50 opacity-60' : isDelivered ? 'border-green-500/20 bg-green-500/5' : 'border-border bg-card'}`}>
                <div className="flex flex-col md:flex-row justify-between gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-secondary text-secondary-foreground border border-border">
                        {record.status || 'Unknown'}
                      </span>
                      <span className="text-xs text-muted-foreground">{formatDate(record.dateOfLive)}</span>
                    </div>
                    <p className="text-sm font-medium mt-1">{record.itemDescription}</p>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      {record.orderId && <span>ID: <span className="font-mono">{record.orderId}</span></span>}
                      <span>{record.category || 'N/A'}</span>
                      {record.grams && <span>{Number(record.grams).toFixed(2)}g</span>}
                    </div>
                  </div>

                  <div className="flex flex-col items-end justify-center min-w-[120px] shrink-0">
                    {(!isDead || isDelivered) && (
                      <>
                        <div className="text-right w-full flex justify-between gap-4 mb-0.5">
                          <span className="text-xs text-muted-foreground">Price:</span>
                          <span className="text-sm font-medium">AED {price.toFixed(2)}</span>
                        </div>
                        <div className="text-right w-full flex justify-between gap-4 mb-1">
                          <span className="text-xs text-muted-foreground">Paid:</span>
                          <span className="text-sm font-medium text-green-500">AED {paid.toFixed(2)}</span>
                        </div>
                        <div className="w-full h-px bg-border my-1" />
                        <div className="text-right w-full flex justify-between gap-4">
                          <span className="text-[10px] uppercase tracking-wide text-muted-foreground self-center">Bal:</span>
                          <span className={`text-sm font-bold ${balance > 0 ? 'text-destructive' : 'text-green-500 flex items-center gap-1'}`}>
                            {balance === 0 && <CheckCircle2 className="w-3.5 h-3.5" />}
                            AED {balance.toFixed(2)}
                          </span>
                        </div>
                      </>
                    )}
                  </div>
                </div>
              </div>
            );
          })}

          {customerRecords.length === 0 && (
            <div className="text-center py-8 text-muted-foreground border border-dashed border-border rounded-xl">
              No history found for this customer.
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Calculator, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { getRatesForDate } from '@/lib/ratesStore';

function todayKey(): string {
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

type Category = 'silver' | 'silver_branded' | 'gold';

export default function RateCalculatorWidget() {
  const [open, setOpen] = useState(false);
  const [grams, setGrams] = useState('');
  const [category, setCategory] = useState<Category>('silver');
  const [goldRate, setGoldRate] = useState('');

  const rates = getRatesForDate(todayKey());
  const gramsNum = parseFloat(grams) || 0;
  const goldRateNum = parseFloat(goldRate) || 0;

  let priceAED = 0;
  if (category === 'silver') priceAED = gramsNum * rates.silverSellRate;
  else if (category === 'silver_branded') priceAED = gramsNum * rates.silverBrandedSellRate;
  else if (category === 'gold' && goldRateNum > 0) priceAED = gramsNum * goldRateNum;

  const pricePHP = priceAED * rates.phpRate;
  const hasResult = gramsNum > 0 && priceAED > 0;

  return (
    <div className="relative">
      <button
        onClick={() => setOpen(v => !v)}
        className={`p-1.5 rounded-full transition-colors ${open ? 'text-primary bg-primary/10' : 'text-muted-foreground hover:bg-secondary'}`}
        title="Live Rate Calculator"
      >
        <Calculator className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div className="absolute right-0 top-full mt-2 z-50 w-64 rounded-xl border border-border bg-card shadow-2xl p-4 space-y-3">

            {/* Header */}
            <div className="flex items-center justify-between">
              <p className="text-xs font-semibold text-foreground flex items-center gap-1.5">
                <Calculator className="h-3.5 w-3.5 text-primary" />
                Rate Calculator
              </p>
              <button onClick={() => setOpen(false)} className="text-muted-foreground hover:text-foreground transition-colors">
                <X className="h-3.5 w-3.5" />
              </button>
            </div>

            {/* Category tabs */}
            <div className="flex gap-1">
              {(['silver', 'silver_branded', 'gold'] as Category[]).map(c => (
                <button
                  key={c}
                  onClick={() => setCategory(c)}
                  className={`flex-1 text-[9px] py-1 rounded border transition-colors font-semibold tracking-wide ${
                    category === c
                      ? 'bg-primary text-primary-foreground border-primary'
                      : 'border-border text-muted-foreground hover:border-primary/40'
                  }`}
                >
                  {c === 'silver' ? 'Silver' : c === 'silver_branded' ? 'Ag Branded' : 'Gold'}
                </button>
              ))}
            </div>

            {/* Today's rates strip */}
            <div className="bg-secondary/40 rounded-lg px-3 py-2 text-[10px] space-y-1">
              <div className="flex justify-between text-muted-foreground">
                <span>Silver</span>
                <span className="font-medium text-foreground">AED {rates.silverSellRate}/g</span>
              </div>
              <div className="flex justify-between text-muted-foreground">
                <span>Branded Ag</span>
                <span className="font-medium text-foreground">AED {rates.silverBrandedSellRate}/g</span>
              </div>
              <div className="flex justify-between text-muted-foreground border-t border-border/40 pt-1 mt-0.5">
                <span>PHP Rate</span>
                <span className="font-medium text-foreground">1 AED = {rates.phpRate} PHP</span>
              </div>
            </div>

            {/* Gold rate input */}
            {category === 'gold' && (
              <div>
                <label className="text-[10px] text-muted-foreground block mb-1">Gold Rate (AED/g)</label>
                <Input
                  type="number"
                  placeholder="e.g. 210"
                  value={goldRate}
                  onChange={e => setGoldRate(e.target.value)}
                  className="h-8 text-sm bg-background border-border"
                />
              </div>
            )}

            {/* Grams input */}
            <div>
              <label className="text-[10px] text-muted-foreground block mb-1">Weight (grams)</label>
              <Input
                type="number"
                placeholder="0.00"
                value={grams}
                onChange={e => setGrams(e.target.value)}
                className="h-8 text-sm bg-background border-border"
                autoFocus
              />
            </div>

            {/* Result */}
            {hasResult ? (
              <div className="rounded-lg border border-primary/30 bg-primary/5 p-3">
                <div className="flex justify-between items-baseline mb-1">
                  <span className="text-[10px] text-muted-foreground uppercase tracking-wider">Price (AED)</span>
                  <span className="text-xl font-bold font-cinzel text-primary">
                    AED {Math.round(priceAED).toLocaleString()}
                  </span>
                </div>
                <div className="flex justify-between items-baseline">
                  <span className="text-[10px] text-muted-foreground uppercase tracking-wider">≈ PHP</span>
                  <span className="text-sm font-semibold text-foreground">
                    ₱ {Math.round(pricePHP).toLocaleString()}
                  </span>
                </div>
              </div>
            ) : (
              gramsNum > 0 && category === 'gold' && goldRateNum === 0 ? (
                <p className="text-[10px] text-muted-foreground text-center">Enter gold rate above ↑</p>
              ) : null
            )}
          </div>
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DatabaseRowType } from '@/types';

const LOCATION_OPTIONS = ['Local', 'Pinas', 'Dubai'];
const CURRENCY_OPTIONS = ['AED', 'PHP', 'USD'];

interface Props {
  record: DatabaseRowType;
  onSave: (fields: Partial<DatabaseRowType>) => Promise<void>;
  onClose: () => void;
}

export default function EditItemDialog({ record, onSave, onClose }: Props) {
  const [minerName, setMinerName] = useState(record.minerName || '');
  const [itemDescription, setItemDescription] = useState(record.itemDescription || '');
  const [clientRate, setClientRate] = useState(record.clientRate != null ? String(record.clientRate) : '');
  const [currency, setCurrency] = useState(record.currency || 'AED');
  const [grams, setGrams] = useState(record.grams != null ? String(record.grams) : '');
  const [location, setLocation] = useState(record.locationOfMiner || '');
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    setSaving(true);
    const fields: Partial<DatabaseRowType> = { minerName };
    if (itemDescription.trim()) fields.itemDescription = itemDescription.trim().toUpperCase();
    if (clientRate !== '') fields.clientRate = parseFloat(clientRate) || 0;
    fields.currency = currency;
    if (grams !== '') fields.grams = parseFloat(grams) || 0;
    if (location) fields.locationOfMiner = location;
    await onSave(fields);
    setSaving(false);
    onClose();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="bg-card border-border max-w-sm">
        <DialogHeader>
          <DialogTitle className="text-sm font-semibold">Edit Item Details</DialogTitle>
        </DialogHeader>
        <div className="space-y-3 py-1">
          <div>
            <Label className="text-xs text-muted-foreground">Client / Miner Name</Label>
            <Input
              value={minerName}
              onChange={e => setMinerName(e.target.value)}
              className="h-8 text-xs mt-0.5 bg-background border-border"
              placeholder="Enter name..."
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Item Description</Label>
            <Input
              value={itemDescription}
              onChange={e => setItemDescription(e.target.value)}
              className="h-8 text-xs mt-0.5 bg-background border-border uppercase"
              placeholder="e.g. GOLD RING 18K"
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Client Rate</Label>
            <div className="flex gap-2 mt-0.5">
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger className="h-8 w-20 text-xs bg-background border-border shrink-0">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CURRENCY_OPTIONS.map(c => (
                    <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Input
                type="number"
                value={clientRate}
                onChange={e => setClientRate(e.target.value)}
                className="h-8 text-xs bg-background border-border flex-1"
                placeholder="e.g. 220"
              />
            </div>
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Grams</Label>
            <Input
              type="number"
              value={grams}
              onChange={e => setGrams(e.target.value)}
              className="h-8 text-xs mt-0.5 bg-background border-border"
              placeholder="e.g. 7.28"
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Location of Miner</Label>
            <Select value={location} onValueChange={setLocation}>
              <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border">
                <SelectValue placeholder="Select location..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {LOCATION_OPTIONS.map(opt => (
                  <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
        <DialogFooter className="gap-2">
          <Button variant="outline" size="sm" onClick={onClose} disabled={saving}>Cancel</Button>
          <Button size="sm" onClick={handleSave} disabled={saving} className="bg-primary text-primary-foreground">
            {saving ? 'Saving...' : 'Save'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, memo, useMemo, useEffect } from 'react';
import { useCompactMode } from '@/lib/compactMode';
import { ChevronDown, FileText, MapPin, Upload, History, Copy, Check, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue, calcItemPriceAED, calcRemainingBalance, calcTotalPaid } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { getPhpRate, setPhpRate, hasPhpRate, setSilverRate, setSilverBrandedRate } from '@/lib/ratesStore';
import StatusBadge from '@/components/StatusBadge';
import AdminItemRow from './AdminItemRow';
import PhpRateDialog from './PhpRateDialog';
import InvoiceModal from '@/components/InvoiceModal';
import GroupDownpaymentSection from './GroupDownpaymentSection';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isPinasRecord(r: DatabaseRowType) {
  return r.locationOfMiner === 'Pinas' || r.currency === 'PHP';
}

function AdminClientCard({ minerName, records, allRecords, onUpdate, userEmail }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [phpRateDialogDate, setPhpRateDialogDate] = useState<string | null>(null);
  const [phpRates, setPhpRates] = useState<Record<string, number>>({});
  const [copiedName, setCopiedName] = useState(false);
  const first = records[0];
  const overdueRecords = records.filter(isOverdue);
  const hasOverdue = overdueRecords.length > 0;

  const uniqueDates = useMemo(() => {
    const dates = [...new Set(records.map(r => r.dateOfLive).filter(Boolean) as string[])].sort();
    return dates;
  }, [records]);

  const dateLabel = uniqueDates.length === 1
    ? formatDate(uniqueDates[0])
    : uniqueDates.length > 1
      ? `${formatDate(uniqueDates[0])} – ${formatDate(uniqueDates[uniqueDates.length - 1])}`
      : '—';

  // Quick balance summary for the collapsed header
  const quickSummary = useMemo(() => {
    const activeRecords = records.filter(r => {
      const s = (r.status || '').toLowerCase();
      return s !== 'cancelled' && s !== 'completed' && s !== 'delivered';
    });
    if (activeRecords.length === 0) return null;
    const totalValue = activeRecords.reduce((s, r) => s + calcItemPriceAED(r), 0);
    const totalPaid = activeRecords.reduce((s, r) => s + calcTotalPaid(r), 0);
    const totalOwed = activeRecords.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);
    return { totalValue: Math.round(totalValue), totalPaid: Math.round(totalPaid), totalOwed: Math.round(totalOwed) };
  }, [records]);

  const grouped = useMemo(() => {
    const map: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'Unknown Date';
      const liver = r.liverName?.trim().toUpperCase() || 'UNKNOWN LIVER';
      const status = r.status || 'No Status';
      if (!map[date]) map[date] = {};
      if (!map[date][liver]) map[date][liver] = {};
      if (!map[date][liver][status]) map[date][liver][status] = [];
      map[date][liver][status].push(r);
    }
    return map;
  }, [records]);

  // Newest date first
  const sortedDates = Object.keys(grouped).sort((a, b) => b.localeCompare(a));

  const toggleDate = (date: string) =>
    setCollapsedDates(prev => ({ ...prev, [date]: !prev[date] }));

  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    for (const r of records) {
      await onUpdate(r.id, fields);
      await new Promise(res => setTimeout(res, 300));
    }
  };

  const handleCopyName = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(minerName).then(() => {
      setCopiedName(true);
      setTimeout(() => setCopiedName(false), 1500);
    });
  };

  useEffect(() => {
    if (!expanded) return;
    const hasPinas = records.some(isPinasRecord);
    if (!hasPinas) return;

    const loaded: Record<string, number> = {};
    for (const date of uniqueDates) {
      const r = getPhpRate(date);
      if (r !== null) loaded[date] = r;
    }
    setPhpRates(loaded);

    const pinasRecords = records.filter(isPinasRecord);
    const pinasDates = [...new Set(pinasRecords.map(r => r.dateOfLive).filter(Boolean) as string[])];
    const needsRate = pinasDates.find(d => !hasPhpRate(d));
    if (needsRate) setPhpRateDialogDate(needsRate);
  }, [expanded, records, uniqueDates]);

  const handleRateConfirm = (phpRate: number, silverRate?: number, silverBrandedRate?: number) => {
    if (!phpRateDialogDate) return;
    setPhpRate(phpRateDialogDate, phpRate);
    if (silverRate) setSilverRate(phpRateDialogDate, silverRate);
    if (silverBrandedRate) setSilverBrandedRate(phpRateDialogDate, silverBrandedRate);
    setPhpRates(prev => ({ ...prev, [phpRateDialogDate!]: phpRate }));
    setPhpRateDialogDate(null);
  };

  const invoicePhpRate = useMemo(() => {
    const pinasRecords = records.filter(isPinasRecord);
    if (pinasRecords.length === 0) return undefined;
    const date = pinasRecords[0].dateOfLive;
    if (!date) return undefined;
    return phpRates[date] ?? getPhpRate(date) ?? undefined;
  }, [records, phpRates]);

  const hasInvoiceNumber = first?.pureWeight && String(first.pureWeight).trim() !== '';
  const { isCompact } = useCompactMode();

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {/* Copy name button */}
            <button
              onClick={handleCopyName}
              className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
              title="Copy client name"
            >
              {copiedName ? <Check className="h-3 w-3 text-green-400" /> : <Copy className="h-3 w-3" />}
            </button>
            {hasOverdue && (
              <span className="shrink-0 flex items-center gap-1 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">
                <AlertTriangle className="h-2.5 w-2.5" />
                {overdueRecords.length > 1 ? `${overdueRecords.length} OVERDUE` : 'NEEDS ATTENTION'}
              </span>
            )}
            {first?.customerId && (
              <button
                className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            {!isCompact && <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{first?.locationOfMiner || '—'}</span>}
            {!isCompact && first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
          </div>
          <div className="flex items-center gap-3 mt-0.5">
            {!isCompact && <div className="text-[11px] text-primary/70 font-semibold">📅 {dateLabel}</div>}
            {/* Quick balance summary when collapsed */}
            {!expanded && quickSummary && quickSummary.totalOwed > 0 && (
              <div className="text-[10px] font-bold text-orange-400 bg-orange-400/10 border border-orange-400/20 px-1.5 py-0.5 rounded">
                AED {quickSummary.totalOwed.toLocaleString()} owed
              </div>
            )}
            {!expanded && quickSummary && quickSummary.totalOwed === 0 && quickSummary.totalPaid > 0 && (
              <div className="text-[10px] font-bold text-green-400 bg-green-400/10 border border-green-400/20 px-1.5 py-0.5 rounded">
                ✓ Fully Paid
              </div>
            )}
          </div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {records.some(isPinasRecord) && invoicePhpRate && (
            <div className="flex items-center justify-between mb-2 px-2 py-1.5 rounded-lg bg-amber-500/10 border border-amber-500/20">
              <span className="text-xs text-amber-400 font-medium">
                💱 1 AED = {invoicePhpRate} PHP
              </span>
              <button
                className="text-[10px] text-amber-400/70 underline"
                onClick={() => setPhpRateDialogDate(records.filter(isPinasRecord)[0]?.dateOfLive || null)}
              >
                Change
              </button>
            </div>
          )}

          {/* Balance summary when expanded */}
          {quickSummary && (
            <div className="flex items-center gap-3 mb-3 px-2 py-2 rounded-lg bg-secondary/40 border border-border/60 text-[10px]">
              <div className="flex flex-col items-center">
                <span className="text-muted-foreground">Value</span>
                <span className="font-bold text-foreground">AED {quickSummary.totalValue.toLocaleString()}</span>
              </div>
              <div className="h-6 w-px bg-border" />
              <div className="flex flex-col items-center">
                <span className="text-muted-foreground">Paid</span>
                <span className="font-bold text-green-400">AED {quickSummary.totalPaid.toLocaleString()}</span>
              </div>
              <div className="h-6 w-px bg-border" />
              <div className="flex flex-col items-center">
                <span className="text-muted-foreground">Owed</span>
                <span className={`font-bold ${quickSummary.totalOwed > 0 ? 'text-orange-400' : 'text-green-400'}`}>
                  {quickSummary.totalOwed > 0 ? `AED ${quickSummary.totalOwed.toLocaleString()}` : '✓ Clear'}
                </span>
              </div>
            </div>
          )}

          <Button
            variant="outline"
            size="sm"
            onClick={(e) => {
              if (!hasInvoiceNumber) {
                e.preventDefault();
                e.stopPropagation();
                return;
              }
              setShowInvoice(true);
            }}
            disabled={!hasInvoiceNumber}
            className={`w-full mb-3 text-xs ${!hasInvoiceNumber ? 'opacity-50 cursor-not-allowed pointer-events-none bg-secondary/50 text-muted-foreground border-border' : 'border-primary/40 text-primary hover:bg-primary/10'}`}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" />
            {hasInvoiceNumber ? `Generate Invoice (${records.length} items)` : 'Click "Gen" on an item below to unlock'}
          </Button>

          {sortedDates.map(date => {
            const isDateCollapsed = collapsedDates[date];
            const dateAllItems = Object.values(grouped[date]).flatMap(s => Object.values(s)).flat();
            const dateRecordCount = dateAllItems.length;
            const dateHasOverdue = dateAllItems.some(isOverdue);

            // Updates EVERY item in this date group — used for invoice # assignment
            const handleDateGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
              for (const r of dateAllItems) {
                await onUpdate(r.id, fields);
                await new Promise(res => setTimeout(res, 150));
              }
            };

            return (
              <div key={date} className="mb-3 rounded-lg border border-border/40 overflow-hidden">
                <button
                  className="w-full flex items-center justify-between px-3 py-2 bg-secondary/30 text-left"
                  onClick={() => toggleDate(date)}
                >
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] font-bold text-primary uppercase tracking-widest">
                      📅 {formatDate(date)}
                    </span>
                    {dateHasOverdue && (
                      <span className="text-[9px] font-bold text-destructive bg-destructive/10 border border-destructive/20 px-1 py-0.5 rounded">
                        OVERDUE
                      </span>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] text-muted-foreground">{dateRecordCount} item{dateRecordCount !== 1 ? 's' : ''}</span>
                    <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform ${isDateCollapsed ? '' : 'rotate-180'}`} />
                  </div>
                </button>

                {!isDateCollapsed && (
                  <div className="px-3 pt-2 pb-2">
                    {Object.entries(grouped[date]).map(([liver, statuses]) => (
                      <div key={liver} className="mb-2">
                        <div className="text-[10px] font-semibold text-primary/70 uppercase tracking-wide mb-1 px-0.5">
                          🧑 {liver}
                        </div>
                        {Object.entries(statuses).map(([status, items]) => {
                          const groupHasDP = items.some(r => {
                            const v = String(r.downpayment || '').trim();
                            return v !== '' && (v === 'acknowledged' || parseFloat(v) > 0);
                          });
                          return (
                            <div key={status} className="mb-2 ml-2">
                              <div className="flex items-center gap-1.5 mb-1">
                                <StatusBadge status={status} />
                                <span className="text-[10px] text-muted-foreground">({items.length})</span>
                                <div className="h-px flex-1 bg-border/30" />
                              </div>
                              {status === 'Waiting for Downpayment' && (
                                <GroupDownpaymentSection items={items} onUpdate={onUpdate} />
                              )}
                              {items.map(record => (
                                <AdminItemRow
                                  key={record.id}
                                  record={record}
                                  onUpdate={onUpdate}
                                  onGroupUpdate={handleGroupUpdate}
                                  onDateGroupUpdate={handleDateGroupUpdate}
                                  groupHasDP={groupHasDP}
                                  userEmail={userEmail}
                                />
                              ))}
                            </div>
                          );
                        })}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {phpRateDialogDate && (
        <PhpRateDialog
          date={phpRateDialogDate}
          onConfirm={handleRateConfirm}
          onSkip={() => setPhpRateDialogDate(null)}
        />
      )}

      {showInvoice && (
        <InvoiceModal
          records={allRecords.filter(r => r.minerName?.trim().toLowerCase() === minerName.trim().toLowerCase())}
          onClose={() => setShowInvoice(false)}
        />
      )}

      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

export default memo(AdminClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useState, useEffect } from 'react';
import { ChevronDown, Settings2, Lock, LockOpen, ShieldAlert, Pin, RefreshCw } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useAuth } from 'zite-auth-sdk';
import {
  getRatesForDate,
  saveRatesForDate,
  getStickyRates,
  setStickyRates,
  DEFAULT_RATES,
  isRateLockedForDate,
  lockRatesForDate,
  unlockRatesForDate,
  hasRatesSnapshotForDate,
} from '@/lib/ratesStore';
import { SUPER_ADMIN_EMAILS } from '@/config/roles';

interface Props {
  date: string;
}

export default function DailyRatesEditor({ date }: Props) {
  const { user } = useAuth();
  const isSuperAdmin = user?.email
    ? SUPER_ADMIN_EMAILS.map(e => e.toLowerCase()).includes(user.email.toLowerCase())
    : false;

  const [open, setOpen] = useState(false);
  const [selectedRateDate, setSelectedRateDate] = useState(date || new Date().toISOString().split('T')[0]);
  const [phpRate, setPhpRateVal] = useState('');
  const [silverSell, setSilverSellVal] = useState('');
  const [silverBrandedSell, setSilverBrandedSellVal] = useState('');
  const [isLocked, setIsLocked] = useState(false);
  const [stickySnap, setStickySnap] = useState(getStickyRates());
  const [editingSticky, setEditingSticky] = useState(false);
  const [stickyPhp, setStickyPhp] = useState('');
  const [stickySilver, setStickySilver] = useState('');
  const [stickySilverBranded, setStickySilverBranded] = useState('');

  useEffect(() => {
    if (date) setSelectedRateDate(date);
  }, [date]);

  useEffect(() => {
    const snap = getRatesForDate(selectedRateDate);
    setPhpRateVal(String(snap.phpRate));
    setSilverSellVal(String(snap.silverSellRate));
    setSilverBrandedSellVal(String(snap.silverBrandedSellRate));
    setIsLocked(isRateLockedForDate(selectedRateDate));
  }, [selectedRateDate, open]);

  useEffect(() => {
    const s = getStickyRates();
    setStickySnap(s);
    setStickyPhp(String(s.phpRate));
    setStickySilver(String(s.silverSellRate));
    setStickySilverBranded(String(s.silverBrandedSellRate));
  }, [open]);

  const saveSticky = () => {
    const php = parseFloat(stickyPhp);
    const ss = parseFloat(stickySilver);
    const sbs = parseFloat(stickySilverBranded);
    if ([php, ss, sbs].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }
    setStickyRates({
      ...getStickyRates(),
      phpRate: php,
      silverSellRate: ss,
      silverBrandedSellRate: sbs,
    });
    setStickySnap(getStickyRates());
    setEditingSticky(false);
    toast.success('Default rate updated and locked in 📌 — all future dates will use this rate');
  };

  const save = () => {
    if (isLocked) {
      toast.error('Rates are locked. Only a Super Admin can unlock them.');
      return;
    }
    const php = parseFloat(phpRate);
    const ss = parseFloat(silverSell);
    const sbs = parseFloat(silverBrandedSell);
    if ([php, ss, sbs].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }
    const existing = getRatesForDate(selectedRateDate);
    saveRatesForDate(selectedRateDate, { ...existing, phpRate: php, silverSellRate: ss, silverBrandedSellRate: sbs });
    lockRatesForDate(selectedRateDate);
    setIsLocked(true);
    toast.success(`Rates locked for ${selectedRateDate} 🔒`);
    setOpen(false);
  };

  const handleUnlock = () => {
    if (!isSuperAdmin) {
      toast.error('Only Super Admins can unlock rates.');
      return;
    }
    unlockRatesForDate(selectedRateDate);
    setIsLocked(false);
    toast.success(`Rates unlocked for ${selectedRateDate} 🔓`);
  };

  const snap = getRatesForDate(selectedRateDate);
  const isToday = selectedRateDate === new Date().toISOString().split('T')[0];
  const hasDateOverride = hasRatesSnapshotForDate(selectedRateDate);

  return (
    <div className="mb-4">
      {/* Collapsed Summary Bar */}
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center gap-2 px-3 py-2 rounded-lg bg-card border border-border hover:bg-secondary/40 transition-colors text-left"
      >
        <Settings2 className="h-3.5 w-3.5 text-primary shrink-0" />
        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Daily Rates</span>
        <span className="text-[10px] text-foreground ml-1">
          PHP <span className="text-primary font-semibold">{snap.phpRate}</span>
          &nbsp;·&nbsp; Ag <span className="text-primary font-semibold">{snap.silverSellRate}</span>
          &nbsp;·&nbsp; Ag★ <span className="text-primary font-semibold">{snap.silverBrandedSellRate}</span>
        </span>
        {!hasDateOverride && (
          <Pin className="h-3 w-3 text-blue-500 ml-1 shrink-0" />
        )}
        {isRateLockedForDate(selectedRateDate) && (
          <Lock className="h-3 w-3 text-amber-500 ml-1 shrink-0" />
        )}
        <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground ml-auto transition-transform duration-200 ${open ? 'rotate-180' : ''}`} />
      </button>

      {open && (
        <div className="mt-2 px-3 py-3 rounded-lg bg-card border border-border space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">

          {/* ── STICKY DEFAULT RATE SECTION ── */}
          <div className="rounded-md border border-blue-500/30 bg-blue-500/5 px-3 py-2.5 space-y-2">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Pin className="h-3.5 w-3.5 text-blue-500" />
                <span className="text-xs font-bold text-blue-500">Default Rate (Sticky)</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-muted-foreground">
                  PHP <strong>{stickySnap.phpRate}</strong> · Ag <strong>{stickySnap.silverSellRate}</strong> · Ag★ <strong>{stickySnap.silverBrandedSellRate}</strong>
                </span>
                <Button
                  variant="outline"
                  size="sm"
                  className="text-[10px] h-6 border-blue-500/40 text-blue-500 hover:bg-blue-500/10"
                  onClick={() => setEditingSticky(e => !e)}
                >
                  {editingSticky ? 'Cancel' : <><RefreshCw className="h-2.5 w-2.5 mr-1" /> Change</>}
                </Button>
              </div>
            </div>

            <p className="text-[10px] text-muted-foreground">
              This rate applies to <strong>all dates</strong> that don't have a specific override. Set it once and it stays until you change it.
            </p>

            {editingSticky && (
              <div className="space-y-2 pt-1 border-t border-blue-500/20">
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">PHP Rate (1 AED =)</span>
                  <Input type="number" step="0.01" value={stickyPhp} onChange={e => setStickyPhp(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                  <span className="text-[10px] text-muted-foreground">PHP</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">Silver Rate (AED/g)</span>
                  <Input type="number" step="0.5" value={stickySilver} onChange={e => setStickySilver(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">Silver Branded (AED/g)</span>
                  <Input type="number" step="0.5" value={stickySilverBranded} onChange={e => setStickySilverBranded(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                </div>
                <Button size="sm" className="text-xs h-7 bg-blue-500 text-white hover:bg-blue-600" onClick={saveSticky}>
                  <Pin className="h-3 w-3 mr-1" /> Save as Default
                </Button>
              </div>
            )}
          </div>

          <div className="h-px bg-border" />

          {/* ── DATE-SPECIFIC OVERRIDE ── */}
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider shrink-0">Date Override</span>
            <input
              type="date"
              value={selectedRateDate}
              onChange={e => setSelectedRateDate(e.target.value)}
              className="h-7 text-xs rounded-md border border-border bg-background text-foreground px-2 focus:outline-none focus:ring-1 focus:ring-primary"
            />
