function agingHours(dateStr?: string): number {
  if (!dateStr) return 0;
  const d = parseDateRobust(dateStr);
  if (!d) return 0;
  return Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60));
}

function AgingLabel({ dateStr, warnAfterHours }: { dateStr?: string; warnAfterHours: number }) {
  const hours = agingHours(dateStr);
  const days = Math.floor(hours / 24);
  const isUrgent = hours >= warnAfterHours;
  if (!dateStr) return null;
  return (
    <span className={`inline-flex items-center gap-0.5 text-[9px] font-bold px-1.5 py-0.5 rounded-full border ml-1 ${isUrgent ? 'bg-destructive/20 text-destructive border-destructive/30' : 'bg-secondary text-muted-foreground border-border'}`}>
      {isUrgent && <AlertTriangle className="h-2.5 w-2.5" />}
      {days === 0 ? 'today' : `${days}d`}
    </span>
  );
}

function hasLayawayAlerts(records: DatabaseRowType[]): boolean {
  const n = (v: unknown) => parseFloat(String(v ?? '0')) || 0;
  for (const r of records) {
    if (r.status !== 'Layaway') continue;
    const d = parseDateRobust(r.dateOfLive);
    if (!d) continue;
    const payments = [n(r.la1MonthPayment), n(r.la2MonthPayment), n(r.la3MonthPayment), n(r.la4MonthPayment)];
    for (let i = 0; i < payments.length; i++) {
      if (payments[i] > 0) continue;
      const due = new Date(d.getTime() + (i + 1) * 30 * 24 * 60 * 60 * 1000);
      const days = Math.ceil((due.getTime() - Date.now()) / (1000 * 60 * 60 * 24));
      if (days <= 5 && days >= -3) return true;
      break;
    }
  }
  return false;
}

