              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <><CopyPlus className="h-3.5 w-3.5 mr-1" /> Save & Add Another</>}
            </Button>
            <Button onClick={() => handleSave(false)} disabled={saving || isDuplicateBarcode} className="flex-1 text-xs h-8 bg-primary text-primary-foreground">
              {saving ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : 'Create Record'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import {
  calcItemPrice, calcItemPriceAED, calcShippingFee, calcCCFee,
  calcTotalPaid, calcProfitAED, roundPrice, getEffectiveCurrency,
  toAED, fromAED, calcRemainingBalance, resolveDownpaymentCurrencyAED
} from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

const REMITTANCE_OPTIONS = [
  'Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer',
  'Secured via Cash', 'SECURED VIA TABBY', 'SECURED VIA TAMARA',
];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store'];

export default function FinancialsForm({ record, onUpdate }: Props) {
  const [saving, setSaving] = useState(false);
  const isLayaway = record.modeOfPayment === 'Layaway';

  const currency = getEffectiveCurrency(record);

  const [form, setForm] = useState({
    goldRate: record.goldRate?.toString() || '',
    mc: record.mc || '',
    supplierRate: record.supplierRate || '',
    additionalCharges: record.additionalCharges || '',
    additionalFeeRemarks: record.liverAdminRemarks || '',
    downpayment: String(record.downpayment || ''),
    amountReceived: String(record.amountReceived || ''),
    la1MonthPayment: String(record.la1MonthPayment || ''),
    la2MonthPayment: String(record.la2MonthPayment || ''),
    la3MonthPayment: String(record.la3MonthPayment || ''),
    la4MonthPayment: String(record.la4MonthPayment || ''),
    remittanceStatus: record.remittanceStatus || '',
    modeOfSale: record.modeOfSale || '',
  });

  useEffect(() => {
    setForm({
      goldRate: record.goldRate?.toString() || '',
      mc: record.mc || '',
      supplierRate: record.supplierRate || '',
      additionalCharges: record.additionalCharges || '',
      additionalFeeRemarks: record.liverAdminRemarks || '',
      downpayment: String(record.downpayment || ''),
      amountReceived: String(record.amountReceived || ''),
      la1MonthPayment: String(record.la1MonthPayment || ''),
      la2MonthPayment: String(record.la2MonthPayment || ''),
      la3MonthPayment: String(record.la3MonthPayment || ''),
      la4MonthPayment: String(record.la4MonthPayment || ''),
      remittanceStatus: record.remittanceStatus || '',
      modeOfSale: record.modeOfSale || '',
    });
  }, [record.id]);

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  const toDisplay = (val: unknown): string => {
    const num = parseFloat(String(val ?? '')) || 0;
    if (!num) return '';
    return String(Math.round(toAED(num, record) * 100) / 100);
  };
  const fromDisplay = (aedStr: string): string => {
    const num = parseFloat(aedStr) || 0;
    if (!num) return '';
    return String(Math.round(fromAED(num, record) * 100) / 100);
  };

  const buildPreview = (): DatabaseRowType => ({
    ...record,
    goldRate: parseFloat(form.goldRate) || record.goldRate,
    supplierRate: form.supplierRate,
    mc: form.mc,
    additionalCharges: form.additionalCharges,
    downpayment: form.downpayment,
    amountReceived: form.amountReceived,
    la1MonthPayment: isLayaway ? form.la1MonthPayment : '',
    la2MonthPayment: isLayaway ? form.la2MonthPayment : '',
    la3MonthPayment: isLayaway ? form.la3MonthPayment : '',
    la4MonthPayment: isLayaway ? form.la4MonthPayment : '',
  });

  const handlePayFull = () => {
    const preview = buildPreview();
    preview.amountReceived = ''; 
    const remainingAED = calcRemainingBalance(preview); 

    if (remainingAED > 0) {
        set('amountReceived', String(fromAED(remainingAED, record)));
        toast.success(`Auto-filled full balance!`);
    } else {
        toast.info('Balance is already fully paid!');
    }
  };

  const handleSave = async () => {
    // Layaway validation: sum of installments must not exceed (total - DP)
    if (isLayaway) {
      const preview = buildPreview();
      const totalAED = calcItemPriceAED(preview) + calcShippingFee(preview) + calcCCFee(preview) + (parseFloat(form.additionalCharges) || 0);
      const dpAED = resolveDownpaymentCurrencyAED(parseFloat(form.downpayment) || 0, record);
      const maxLayawayAED = totalAED - dpAED;
      const layawayRaw = [form.la1MonthPayment, form.la2MonthPayment, form.la3MonthPayment, form.la4MonthPayment]
        .reduce((s, v) => s + (parseFloat(v) || 0), 0);
      const layawayAED = toAED(layawayRaw, record);
      if (layawayAED > maxLayawayAED + 0.01) {
        toast.error(`Layaway total (AED ${layawayAED.toFixed(2)}) exceeds remaining balance (AED ${maxLayawayAED.toFixed(2)}). Please reduce the installment amounts.`);
        return;
      }
    }

    setSaving(true);
    try {
      const previewRecord = buildPreview();
      const computedProfit = calcProfitAED(previewRecord).toFixed(2);

      // Pass the record's dateOfLive so handleUpdate in App.tsx uses the correct historical rates
      await onUpdate(record.id, {
        dateOfLive: record.dateOfLive, // carry dateOfLive so App.tsx can look up locked rates
        goldRate: parseFloat(form.goldRate) || record.goldRate,
        supplierRate: form.supplierRate,
        mc: form.mc,
        additionalCharges: form.additionalCharges,
        liverAdminRemarks: form.additionalFeeRemarks,
        downpayment: form.downpayment,
        amountReceived: form.amountReceived,
        la1MonthPayment: isLayaway ? form.la1MonthPayment : '',
        la2MonthPayment: isLayaway ? form.la2MonthPayment : '',
        la3MonthPayment: isLayaway ? form.la3MonthPayment : '',
        la4MonthPayment: isLayaway ? form.la4MonthPayment : '',
        remittanceStatus: form.remittanceStatus,
        modeOfSale: form.modeOfSale,
        profit: computedProfit,
      });
      toast.success('Financials saved');
    } finally {
      setSaving(false);
    }
  };

  const previewRecord = buildPreview();
  const itemPrice = calcItemPrice(previewRecord);
  const itemPriceAED = calcItemPriceAED(previewRecord);
  const shippingFee = calcShippingFee(previewRecord);
  const ccFee = calcCCFee(previewRecord);
  const additionalAED = parseFloat(form.additionalCharges) || 0;
  const totalAmount = roundPrice(itemPriceAED + shippingFee + ccFee + additionalAED);
  const totalPaid = calcTotalPaid(previewRecord);
  const remaining = roundPrice(totalAmount - totalPaid);
  const profitAED = calcProfitAED(previewRecord);

  const numField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input type="number" value={form[key as keyof typeof form]} onChange={e => set(key, e.target.value)}
        disabled={disabled} className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50" placeholder="0.00" />
    </div>
  );

  const paymentField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input
        type="number"
        value={toDisplay(form[key as keyof typeof form])}
        onChange={e => set(key, fromDisplay(e.target.value))}
        disabled={disabled}
        className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50"
        placeholder="0.00"
      />
    </div>
  );

  return (
    <div className="border-t border-border pt-3 mt-2">
      <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wide">Financials</p>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Mode of Sale</Label>
        <Select value={form.modeOfSale} onValueChange={v => set('modeOfSale', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select mode of sale..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {MODE_OF_SALE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        {numField('Gold Rate', 'goldRate')}
        {numField('MC (Making Charge)', 'mc')}
        <div>
          <Label className="text-xs text-muted-foreground">Supplier Rate</Label>
          <Input type="number" value={form.supplierRate} onChange={e => set('supplierRate', e.target.value)}
            className="h-8 text-xs bg-background border-border mt-0.5" placeholder="0.00" />
        </div>
        {numField('Additional Fees (AED)', 'additionalCharges')}
      </div>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Additional Fee Remarks <span className="text-primary/60">(Col X)</span></Label>
        <Textarea value={form.additionalFeeRemarks} onChange={e => set('additionalFeeRemarks', e.target.value)}
          className="text-xs bg-background border-border mt-0.5 min-h-[60px]" placeholder="Enter remarks about additional fees..." />
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        {paymentField('Downpayment (AED)', 'downpayment')}

        <div>
          <div className="flex items-center justify-between mb-0.5">
            <Label className="text-xs text-muted-foreground">Amount Received (AED)</Label>
            <button 
              onClick={handlePayFull} 
              disabled={isLayaway}
              className="text-[9px] font-bold text-primary bg-primary/10 hover:bg-primary/20 px-1.5 py-0.5 rounded transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              title={isLayaway ? 'PAY FULL is disabled for Layaway — use the monthly payment fields' : 'Auto-fill exact remaining balance'}
            >
              PAY FULL
            </button>
          </div>
          <Input
            type="number"
            value={toDisplay(form.amountReceived)}
            onChange={e => set('amountReceived', fromDisplay(e.target.value))}
            className="h-8 text-xs bg-background border-border disabled:opacity-50"
            placeholder="0.00"
          />
        </div>
      </div>

      <div className={`grid grid-cols-2 gap-2 mb-3 ${!isLayaway ? 'opacity-40' : ''}`}>
        <p className="col-span-2 text-xs text-muted-foreground">
          Layaway Payments <span className="font-bold text-primary">({currency})</span>{!isLayaway ? ' (locked — only active on Layaway MOP)' : ''}
        </p>
        {/* Layaway fields: entered & stored in the record's native currency (e.g. PHP for Pinas) */}
        {(['la1MonthPayment','la2MonthPayment','la3MonthPayment','la4MonthPayment'] as const).map((key, i) => (
          <div key={key}>
            <Label className="text-xs text-muted-foreground">Month {i + 1}</Label>
            <Input
              type="number"
              value={form[key]}
              onChange={e => set(key, e.target.value)}
              disabled={!isLayaway}
              className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50"
              placeholder="0.00"
              min={0}
            />
          </div>
        ))}
      </div>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Remittance Status</Label>
        <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select remittance..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {REMITTANCE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="bg-secondary/50 rounded-lg p-3 mb-3 space-y-1 text-xs">
        <div className="flex justify-between"><span className="text-muted-foreground">Item Price ({currency})</span><span>{currency} {itemPrice.toFixed(2)}</span></div>
        {currency !== 'AED' && <div className="flex justify-between"><span className="text-muted-foreground">Item Price (AED)</span><span>AED {itemPriceAED.toFixed(2)}</span></div>}
        <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>AED {shippingFee.toFixed(2)}</span></div>
        {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Fee</span><span>AED {ccFee.toFixed(2)}</span></div>}
        {additionalAED > 0 && <div className="flex justify-between"><span className="text-muted-foreground">Additional Charges</span><span>AED {additionalAED.toFixed(2)}</span></div>}
        <div className="flex justify-between font-semibold pt-1 border-t border-border">
          <span>Total Amount</span><span>AED {totalAmount.toFixed(2)}</span>
        </div>
        <div className="flex justify-between"><span className="text-muted-foreground">Total Paid</span><span>AED {totalPaid.toFixed(2)}</span></div>
        <div className={`flex justify-between font-bold pt-1 border-t border-border ${remaining > 0 ? 'text-destructive' : remaining < 0 ? 'text-violet-400' : 'text-green-400'}`}>
          <span>{remaining < 0 ? '🎁 Store Credit' : 'Remaining Balance'}</span>
          <span>AED {Math.abs(remaining).toFixed(2)}{remaining < 0 ? ' credit' : ''}</span>
        </div>
        <div className="flex justify-between pt-1 border-t border-border">
          <span className="text-muted-foreground">Expected Profit</span>
          <span className={profitAED >= 0 ? 'text-primary font-medium' : 'text-destructive font-medium'}>AED {profitAED.toFixed(2)}</span>
        </div>
      </div>

      <Button onClick={handleSave} disabled={saving} className="w-full bg-primary text-primary-foreground text-xs h-8">
        {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Save Financials'}
      </Button>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Merge, AlertTriangle, CheckCircle2, Loader2, Search } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { mergeClients } from 'zite-endpoints-sdk';
import { DatabaseRowType } from '@/types';

interface ClientProfile {
  customerId: string;
  minerName: string;
  recordCount: number;
}

interface Props {
  onClose: () => void;
  onRefresh?: () => void;
  records: DatabaseRowType[];
}

function buildProfiles(records: DatabaseRowType[]): ClientProfile[] {
  const map = new Map<string, { name: string; count: number }>();
  for (const r of records) {
    const id = r.customerId?.trim();
    const name = r.minerName?.trim() || '';
    if (!id) continue;
    if (!map.has(id)) {
      map.set(id, { name, count: 0 });
    }
    map.get(id)!.count++;
  }
  return Array.from(map.entries())
    .map(([customerId, { name, count }]) => ({ customerId, minerName: name, recordCount: count }))
    .sort((a, b) => a.minerName.localeCompare(b.minerName));
}

function ProfilePicker({
  label,
  profiles,
  selected,
  onSelect,
  exclude,
}: {
  label: string;
  profiles: ClientProfile[];
  selected: ClientProfile | null;
  onSelect: (p: ClientProfile) => void;
  exclude?: string;
}) {
  const [search, setSearch] = useState('');
  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return profiles.filter(p =>
      p.customerId !== exclude &&
      (p.minerName.toLowerCase().includes(q) || p.customerId.toLowerCase().includes(q))
    ).slice(0, 80);
  }, [profiles, search, exclude]);

  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">{label}</Label>
      <div className="relative">
        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
        <Input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Search name or CUST-ID..."
          className="h-8 text-xs pl-8 bg-background border-border"
        />
      </div>
      <div className="border border-border rounded-md overflow-y-auto max-h-48 bg-background">
        {filtered.length === 0 && (
          <p className="text-xs text-muted-foreground text-center py-4">No profiles found</p>
        )}
        {filtered.map(p => (
          <button
            key={p.customerId}
            onClick={() => onSelect(p)}
            className={`w-full text-left px-3 py-2 text-xs flex justify-between items-center transition-colors border-b border-border last:border-0 hover:bg-secondary/60
              ${selected?.customerId === p.customerId ? 'bg-primary/10 text-primary font-semibold' : 'text-foreground'}`}
          >
            <span className="truncate max-w-[160px]">{p.minerName}</span>
            <span className={`text-[10px] font-mono shrink-0 ml-2 ${selected?.customerId === p.customerId ? 'text-primary' : 'text-muted-foreground'}`}>
              {p.customerId} · {p.recordCount}
            </span>
          </button>
        ))}
      </div>
      {selected && (
        <div className="rounded-md bg-secondary/40 border border-border px-3 py-2 text-xs">
          <span className="text-muted-foreground">Selected: </span>
          <span className="font-semibold text-foreground">{selected.minerName}</span>
          <span className="text-muted-foreground ml-2">({selected.customerId} · {selected.recordCount} records)</span>
        </div>
      )}
    </div>
  );
}

export default function MergeClientsModal({ onClose, onRefresh, records }: Props) {
  const profiles = useMemo(() => buildProfiles(records), [records]);
  const [duplicate, setDuplicate] = useState<ClientProfile | null>(null);
  const [master, setMaster] = useState<ClientProfile | null>(null);
  const [merging, setMerging] = useState(false);
  const [confirm, setConfirm] = useState(false);
  const [result, setResult] = useState<{ success: boolean; message: string; count: number } | null>(null);

  const canMerge = duplicate && master && duplicate.customerId !== master.customerId;

  const handleMerge = async () => {
    if (!duplicate || !master) return;
    setMerging(true);
    setConfirm(false);
    try {
      const res = await mergeClients({
        duplicateCustomerId: duplicate.customerId,
        masterCustomerId: master.customerId,
        masterMinerName: master.minerName,
      });
      setResult({ success: res.success, message: res.message, count: res.updatedCount });
      if (res.success) {
        toast.success(res.message);
        onRefresh?.();
        setDuplicate(null);
        setMaster(null);
      } else {
        toast.error(res.message);
      }
    } catch {
      toast.error('Merge failed. Please try again.');
    } finally {
      setMerging(false);
    }
  };

  return (
    <>
      <Dialog open onOpenChange={onClose}>
        <DialogContent className="max-w-2xl bg-card border-border max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary flex items-center gap-2">
              <Merge className="w-4 h-4" /> Merge Client Profiles
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-4 text-sm">
            {/* Warning banner */}
            <div className="flex items-start gap-2 rounded-lg bg-destructive/10 border border-destructive/30 px-3 py-2.5">
              <AlertTriangle className="w-4 h-4 text-destructive shrink-0 mt-0.5" />
              <p className="text-xs text-destructive/90 leading-relaxed">
                <strong>Irreversible action.</strong> All records from the <em>Duplicate Profile</em> will be re-assigned to the <em>Master Profile</em> and its name. This cannot be undone — double-check before confirming.
              </p>
            </div>

            {/* Two pickers */}
            <div className="grid grid-cols-2 gap-4">
              <ProfilePicker
                label="① Duplicate Profile (To Delete)"
                profiles={profiles}
                selected={duplicate}
                onSelect={setDuplicate}
                exclude={master?.customerId}
              />
              <ProfilePicker
                label="② Master Profile (To Keep)"
                profiles={profiles}
                selected={master}
                onSelect={setMaster}
                exclude={duplicate?.customerId}
              />
            </div>

            {/* Merge preview */}
            {canMerge && (
              <div className="rounded-lg border border-border bg-secondary/30 p-3 space-y-1.5">
                <p className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider">Merge Preview</p>
                <div className="flex items-center gap-2 flex-wrap text-xs">
                  <span className="bg-destructive/20 text-destructive px-2 py-0.5 rounded font-mono">{duplicate!.customerId}</span>
                  <span className="text-muted-foreground font-semibold">{duplicate!.minerName}</span>
                  <span className="text-muted-foreground">({duplicate!.recordCount} records)</span>
                  <span className="text-primary font-bold mx-1">→</span>
                  <span className="bg-primary/20 text-primary px-2 py-0.5 rounded font-mono">{master!.customerId}</span>
                  <span className="text-muted-foreground font-semibold">{master!.minerName}</span>
                  <span className="text-muted-foreground">({master!.recordCount} records)</span>
                </div>
                <p className="text-[10px] text-muted-foreground">
                  {duplicate!.recordCount} record(s) will be updated. Names will be normalized to <strong>{master!.minerName}</strong>.
                </p>
              </div>
            )}

            {/* Result banner */}
            {result?.success && (
              <div className="flex items-center gap-2 rounded-lg bg-green-500/10 border border-green-500/30 px-3 py-2.5">
                <CheckCircle2 className="w-4 h-4 text-green-400 shrink-0" />
                <p className="text-xs text-green-400">{result.message}</p>
              </div>
            )}

            {/* Actions */}
            <div className="flex gap-2 pt-1">
              <Button variant="outline" className="text-xs h-8 border-border" onClick={onClose}>
                Close
              </Button>
              <Button
                className="flex-1 text-xs h-8 bg-primary text-primary-foreground"
                disabled={!canMerge || merging}
                onClick={() => setConfirm(true)}
              >
                {merging
                  ? <><Loader2 className="w-3.5 h-3.5 animate-spin mr-1" /> Merging…</>
                  : <><Merge className="w-3.5 h-3.5 mr-1" /> Merge Records</>
                }
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Confirmation dialog */}
      <AlertDialog open={confirm} onOpenChange={setConfirm}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-foreground">Confirm Merge</AlertDialogTitle>
            <AlertDialogDescription className="text-muted-foreground text-sm">
              You are about to move <strong>{duplicate?.recordCount} record(s)</strong> from{' '}
              <span className="font-mono text-destructive">{duplicate?.customerId}</span> ({duplicate?.minerName}) into{' '}
              <span className="font-mono text-primary">{master?.customerId}</span> ({master?.minerName}).{' '}
              This action <strong>cannot be undone</strong>.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="text-xs border-border">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleMerge}
              className="text-xs bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Yes, Merge Now
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import { memo, useState } from 'react';
import { History } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { formatDate } from '@/lib/formatters';
import { toast } from 'sonner';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (id: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function ReviewChasingCard({ minerName, records, allRecords, onUpdate }: Props) {
  const [showHistory, setShowHistory] = useState(false);
  // Use the first record to dictate display values
  const firstRecord = records[0];
  const status = firstRecord.reviewChasing || 'Pending';
  const isChased = status === 'Chased';

  const handleStatusChange = async (val: string) => {
    // Update sequentially to avoid Google Sheets rate limits
    for (const r of records) {
      await onUpdate(r.id, { reviewChasing: val });
      await new Promise(res => setTimeout(res, 300));
    }
    toast.success(`Marked ${minerName} as ${val}`);
  };

  return (
    <div className={`bg-card border border-border rounded-lg p-4 transition-all duration-500 ease-in-out ${isChased ? 'opacity-50 scale-[0.98] py-2.5' : ''}`}>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className={`font-medium truncate ${isChased ? 'text-xs' : 'text-sm'}`}>
              {minerName || 'Unknown Client'}
            </h3>
            {firstRecord.customerId && (
              <button
                className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={() => setShowHistory(true)}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>

          {/* Hide the item descriptions when chased to save space (auto-minimize) */}
          {!isChased && (
            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
              {records.map(r => r.itemDescription).join(', ')}
            </p>
          )}

          <p className="text-[10px] text-muted-foreground mt-1">
            Delivered: {firstRecord.deliveredDate ? formatDate(firstRecord.deliveredDate) : 'Unknown'}
            {records.length > 1 && ` · ${records.length} items`}
          </p>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <Select
            value={status}
            onValueChange={handleStatusChange}
          >
            <SelectTrigger className={`w-[130px] border-border bg-secondary/30 ${isChased ? 'h-7 text-[10px]' : 'h-8 text-xs'}`}>
              <SelectValue placeholder="Select status" />
            </SelectTrigger>
            <SelectContent className="border-border">
              <SelectItem value="Pending">Pending</SelectItem>
              <SelectItem value="Chased">Chased</SelectItem>
              <SelectItem value="Skipped">Skipped</SelectItem>
              <SelectItem value="Completed">Completed</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
      {showHistory && firstRecord.customerId && (
        <CustomerHistoryModal
          customerId={firstRecord.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

// MEMO: Prevent re-rendering unchanged clients for performance
export default memo(ReviewChasingCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer, History, TrendingUp } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { TabProps, DatabaseRowType } from '@/types';
import {
  calcProfitAED,
  calcRemainingBalance,
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED,
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';
type Metal = 'Gold' | 'Silver' | 'Other';

function getMetal(record: DatabaseRowType): Metal {
  const cat = (record.category || '').toLowerCase();
  const src = (record.source || '').toLowerCase();
  const item = (record.itemDescription || '').toLowerCase();
  if (cat.includes('silver') || src.includes('silver') || item.includes('silver')) return 'Silver';
  if (cat.includes('gold') || src.includes('gold') || item.includes('gold')) return 'Gold';
  return 'Other';
}

const METAL_ORDER: Metal[] = ['Gold', 'Silver', 'Other'];
const METAL_COLORS: Record<Metal, string> = {
  Gold: 'text-primary',
  Silver: 'text-muted-foreground',
  Other: 'text-foreground',
};
const METAL_BG: Record<Metal, string> = {
  Gold: 'bg-primary/10 border-primary/30',
  Silver: 'bg-secondary/30 border-border',
  Other: 'bg-muted/20 border-border/50',
};

const STATUS_SORT: Record<string, number> = {
  'Delivered': 1,
  'Given to Shop': 2,
  'Dispatched': 3,
  'Payment for Verification': 4,
  'Paid/DP but Item Hold': 5,
  'For Pullout': 6,
  'Dispatch': 7,
  'Reseller': 8,
  'Outsource': 8,
  'Pending': 9,
  'Waiting for Details': 10,
  'Waiting for Downpayment': 11,
  'Returned Item': 12,
  'Cancelled': 13,
};

const DEAD_STATUSES = new Set(['Cancelled', 'Returned Item']);

const RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All Time' },
  { key: 'week', label: 'This Week' },
  { key: 'month', label: 'This Month' },
  { key: '3months', label: '3 Months' },
  { key: 'custom', label: 'Custom' },
];

function calcGrams(record: DatabaseRowType): number {
  const cat = (record.category || '').toLowerCase();
  if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return 0;
  return Number(record.grams) || 0;
}

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [selectedPrintStatuses, setSelectedPrintStatuses] = useState<Set<string>>(new Set());
  const [printMetalFilter, setPrintMetalFilter] = useState<'both' | 'gold' | 'silver'>('both');
  const [historyCustomer, setHistoryCustomer] = useState<{ id: string, name: string } | null>(null);

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    if (range === 'all') return records;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return records.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      const t = d.getTime();
      if (t < from.getTime()) return false;
      if (to) {
        const end = new Date(to); end.setHours(23, 59, 59, 999);
        if (t > end.getTime()) return false;
      }
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    const activeRecords = filtered.filter(r => !DEAD_STATUSES.has(r.status || ''));
    const deliveredRecords = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const confirmedProfit = deliveredRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = deliveredRecords.length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

    const goldGrams = activeRecords.filter(r => getMetal(r) === 'Gold').reduce((s, r) => s + calcGrams(r), 0);
    const silverGrams = activeRecords.filter(r => getMetal(r) === 'Silver').reduce((s, r) => s + calcGrams(r), 0);
    const totalGrams = activeRecords.reduce((s, r) => s + calcGrams(r), 0);

    const goldProfit = activeRecords.filter(r => getMetal(r) === 'Gold').reduce((s, r) => s + calcProfitAED(r), 0);
    const silverProfit = activeRecords.filter(r => getMetal(r) === 'Silver').reduce((s, r) => s + calcProfitAED(r), 0);

    const layawayRecords = activeRecords.filter(r => r.status === 'Layaway');
    const layawayCount = layawayRecords.length;
    const layawayOutstanding = layawayRecords.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);
    const layawayProfit = layawayRecords.reduce((s, r) => s + calcProfitAED(r), 0);

    return { totalProfit, confirmedProfit, totalSold, outstanding, activeCount: activeRecords.length, totalGrams, goldGrams, silverGrams, goldProfit, silverProfit, layawayCount, layawayOutstanding, layawayProfit };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const sortedStatusEntries = useMemo(() =>
    [...statusGroups.entries()].sort((a, b) => {
      const ao = STATUS_SORT[a[0]] ?? 99;
      const bo = STATUS_SORT[b[0]] ?? 99;
      return ao - bo;
    }),
    [statusGroups]
  );

  const toggleStatus = (status: string) =>
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));

  const toggleDate = (key: string) =>
    setCollapsedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const openPrintDialog = () => {
    setSelectedPrintStatuses(new Set(statusGroups.keys()));
    setPrintMetalFilter('both');
    setShowPrintDialog(true);
  };

  const togglePrintStatus = (status: string) => {
    setSelectedPrintStatuses(prev => {
      const next = new Set(prev);
      if (next.has(status)) next.delete(status); else next.add(status);
      return next;
    });
  };

  const handlePrintReport = () => {
    setShowPrintDialog(false);
    const win = window.open('', '_blank');
    if (!win) return;
    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';
    const metalLabel = printMetalFilter === 'gold' ? 'Gold Only' : printMetalFilter === 'silver' ? 'Silver Only' : 'Gold & Silver';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        * { box-sizing: border-box; }
        body { font-family: Arial, sans-serif; color: #111; background: #fff; margin: 0; padding: 20px; font-size: 11px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin: 0 0 4px; font-size: 22px; }
        .summary { margin-bottom: 20px; padding: 12px 16px; background: #f9f9f9; border-radius: 6px; border: 1px solid #ddd; display: flex; flex-wrap: wrap; gap: 12px 32px; }
        .summary-item { font-size: 12px; }
        .summary-item span { font-weight: bold; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
        .gold { color: #C9A84C; }
        .silver { color: #888; }
        .meta { font-size: 10px; color: #888; margin-bottom: 20px; }
        .status-section { margin-bottom: 28px; break-inside: avoid; }
        .status-header { font-size: 15px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px; margin: 0 0 10px; }
        .status-totals { font-size: 11px; color: #555; margin-bottom: 10px; }
        .metal-header { font-size: 13px; font-weight: bold; padding: 4px 8px; border-radius: 4px; margin: 12px 0 6px; }
        .metal-gold { background: #FDF6E3; border-left: 3px solid #C9A84C; color: #7a6020; }
        .metal-silver { background: #F5F5F5; border-left: 3px solid #888; color: #444; }
        .brand-block { margin-bottom: 16px; }
        .brand-header { font-size: 12px; font-weight: bold; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; margin-bottom: 6px; }
        .client-header { background: #444; color: #fff; padding: 5px 10px; font-size: 11px; font-weight: bold; display: flex; justify-content: space-between; align-items: center; }
        .client-meta { font-size: 9px; font-weight: normal; color: #ccc; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 0; page-break-inside: auto; }
        thead tr { background: #444; color: #fff; }
        th { padding: 6px 8px; text-align: left; font-size: 10px; font-weight: bold; white-space: nowrap; }
        td { padding: 5px 8px; vertical-align: top; font-size: 10px; }
        tbody tr:nth-child(even) { background: #f5f5f5; }
        tbody tr:nth-child(odd) { background: #fff; }
        tr.subtotal-row { background: #e8e8e8 !important; border-top: 2px solid #111; font-weight: bold; }
        .r { text-align: right; }
      </style></head><body>
      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>
      <p class="meta">Date Range: ${dateRangeLabel} &nbsp;|&nbsp; Metal: ${metalLabel} &nbsp;|&nbsp; Generated: ${new Date().toLocaleString()}</p>
      <div class="summary">
        <div class="summary-item">Confirmed Profit (Delivered): <span class="profit-pos">AED ${kpis.confirmedProfit.toFixed(2)}</span></div>
        <div class="summary-item">Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></div>
        <div class="summary-item">Items Delivered: <span>${kpis.totalSold}</span></div>
        <div class="summary-item">Outstanding: <span>AED ${kpis.outstanding.toFixed(2)}</span></div>
        <div class="summary-item">Gold Grams: <span class="gold">${kpis.goldGrams.toFixed(2)}g</span></div>
        <div class="summary-item">Silver Grams: <span class="silver">${kpis.silverGrams.toFixed(2)}g</span></div>
      </div>
      `;

    [...statusGroups.entries()]
      .filter(([status]) => selectedPrintStatuses.has(status))
      .sort((a, b) => (STATUS_SORT[a[0]] ?? 99) - (STATUS_SORT[b[0]] ?? 99))
      .forEach(([status, rawItems]) => {
        const items = rawItems.filter(r => {
          const m = getMetal(r);
          if (printMetalFilter === 'gold') return m === 'Gold';
          if (printMetalFilter === 'silver') return m === 'Silver';
          return true;
        });
        if (items.length === 0) return;
        const isDead = DEAD_STATUSES.has(status);
        const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
        const statusPrice = items.reduce((s, r) => s + calcItemPriceAED(r), 0);
        const statusCost = items.reduce((s, r) => s + calcItemCostAED(r), 0);

        html += `<div class="status-section">`;
        html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} &nbsp; <small style="font-size:12px;font-weight:normal;">(${items.length} items)</small></h2>`;
        if (!isDead) {
          html += `<p class="status-totals">Price: AED ${statusPrice.toFixed(2)} &nbsp;|&nbsp; Cost: AED ${statusCost.toFixed(2)} &nbsp;|&nbsp; <strong class="${statusProfit >= 0 ? 'profit-pos' : 'profit-neg'}">Profit: AED ${statusProfit.toFixed(2)}</strong></p>`;
        }

        // Group by metal → brand → client
        const allowedMetals = printMetalFilter === 'gold' ? ['Gold'] : printMetalFilter === 'silver' ? ['Silver'] : METAL_ORDER;
        for (const metal of allowedMetals as Metal[]) {
          const metalItems = items.filter(r => getMetal(r) === metal);
          if (metalItems.length === 0) continue;
          const mGrams = metalItems.reduce((s, r) => s + calcGrams(r), 0);
          const mProfit = metalItems.reduce((s, r) => s + calcProfitAED(r), 0);
          html += `<div class="metal-header metal-${metal.toLowerCase()}">${metal === 'Gold' ? '🥇' : metal === 'Silver' ? '🥈' : '📦'} ${metal} — ${metalItems.length} items · ${mGrams.toFixed(2)}g${!isDead ? ` · Profit: AED ${mProfit.toFixed(2)}` : ''}</div>`;

          const byBrand = new Map<string, DatabaseRowType[]>();
          for (const r of metalItems) {
            let pk = (r.page || 'Other').trim();
            if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
            else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
            if (!byBrand.has(pk)) byBrand.set(pk, []);
            byBrand.get(pk)!.push(r);
          }
          [...byBrand.entries()].sort((a, b) => a[0].localeCompare(b[0])).forEach(([brand, brandRows]) => {
            const bGrams = brandRows.reduce((s, r) => s + calcGrams(r), 0);
            const bProfit = brandRows.reduce((s, r) => s + calcProfitAED(r), 0);
            html += `<div class="brand-block"><div class="brand-header">${brand} &nbsp; <span style="font-weight:normal;font-size:10px;">${brandRows.length} items · ${bGrams.toFixed(2)}g</span></div>`;
            const colCount = isDead ? 4 : 5;
            const profitTh = isDead ? '' : `<th class="r">Profit</th>`;
            html += `<table><thead><tr><th>Client</th><th>Item</th><th class="r">Grams</th><th class="r">Price</th><th class="r">Cost</th>${profitTh}</tr></thead><tbody>`;
            // Group by date for separator rows
            const byDate = new Map<string, typeof brandRows>();
            for (const r of brandRows) {
              const dk = r.dateOfLive || '—';
              if (!byDate.has(dk)) byDate.set(dk, []);
              byDate.get(dk)!.push(r);
            }
            const formatPrintDate = (raw: string): string => {
              try {
                const d = new Date(raw);
                if (isNaN(d.getTime())) return raw;
                const m = String(d.getUTCMonth() + 1).padStart(2, '0');
                const day = String(d.getUTCDate()).padStart(2, '0');
                const y = d.getUTCFullYear();
                return `${m}/${day}/${y}`;
              } catch { return raw; }
            };
            [...byDate.entries()].sort((a, b) => b[0].localeCompare(a[0])).forEach(([dk, dateRows]) => {
              const formattedDate = dk === '—' ? '—' : formatPrintDate(dk);
              html += `<tr style="background:#ddd !important;"><td colspan="${colCount}" style="padding:4px 8px;font-size:10px;font-weight:bold;color:#333;">📅 ${formattedDate}</td></tr>`;
              dateRows.forEach(r => {
                const gr = calcGrams(r);
                const grStr = gr > 0 ? `${gr.toFixed(2)}g` : 'PC';
                const pr = calcProfitAED(r);
                const pCell = isDead ? '' : `<td class="r ${pr >= 0 ? 'profit-pos' : 'profit-neg'}">${pr.toFixed(2)}</td>`;
                html += `<tr><td>${r.minerName || '—'}</td><td>${r.itemDescription || '—'}</td><td class="r">${grStr}</td><td class="r">${calcItemPriceAED(r).toFixed(2)}</td><td class="r">${calcItemCostAED(r).toFixed(2)}</td>${pCell}</tr>`;
              });
            });
            const brandProfitCell = isDead ? '' : `<td class="r ${bProfit >= 0 ? 'profit-pos' : 'profit-neg'}">${bProfit.toFixed(2)}</td>`;
            html += `<tr class="subtotal-row"><td colspan="2">${brand} Total</td><td class="r">${bGrams.toFixed(2)}g</td><td class="r">${brandRows.reduce((s,r)=>s+calcItemPriceAED(r),0).toFixed(2)}</td><td class="r">${brandRows.reduce((s,r)=>s+calcItemCostAED(r),0).toFixed(2)}</td>${brandProfitCell}</tr>`;
            html += `</tbody></table></div>`;
          });
        }
        html += `</div>`;
      });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
