            <p className="text-[10px] font-semibold uppercase tracking-widest text-primary/70">🥇 Gold Grams</p>
            <p className="text-xl font-bold font-cinzel text-primary leading-none">{kpis.goldGrams.toFixed(2)}g</p>
            <p className="text-[10px] text-muted-foreground">Profit AED {kpis.goldProfit.toFixed(2)}</p>
          </div>

          {/* Silver Grams */}
          <div className="rounded-xl border border-border bg-secondary/20 p-3 flex flex-col gap-1">
