// ─── ACCOUNTS SCOPE ───────────────────────────────────────────────────────────
const ACCOUNTS_STATUSES = [
  'Delivered', 'Given to Shop', 'Paid/DP but Item Hold',
  'Dispatched', 'Payment for Verification', 'Layaway',
  'Reseller', 'Outsource',
];

function isAccountsRelevant(r: DatabaseRowType): boolean {
  const status = r.status || '';
  if (status === 'Cancelled' || status === 'Returned Item') return false;
  if (ACCOUNTS_STATUSES.includes(status)) return true;
  return false;
}

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';
const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' }, { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' }, { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

// ─── Section header component ─────────────────────────────────────────────────
interface SectionHeaderProps {
  icon: React.ReactNode;
  label: string;
  count: number;
  pages: number;
  balance?: number;
  expanded: boolean;
  onToggle: () => void;
  colorClass: string;
  borderClass: string;
  bgClass: string;
}

function SectionHeader({ icon, label, count, pages, balance, expanded, onToggle, colorClass, borderClass, bgClass }: SectionHeaderProps) {
  return (
    <button
      className={`flex w-full items-center gap-2 mb-3 p-3 rounded-lg border ${borderClass} ${bgClass} text-left focus:outline-none hover:opacity-90 transition-opacity`}
      onClick={onToggle}
    >
      <span className={`shrink-0 ${colorClass}`}>{icon}</span>
      <span className={`font-cinzel text-sm font-bold ${colorClass} tracking-wide`}>{label}</span>
      <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${colorClass} bg-white/5 border-current/20`}>
        {pages > 1 ? `${pages} pages · ` : ''}{count} item{count !== 1 ? 's' : ''}
      </span>
      {balance !== undefined && balance > 0 && (
        <span className="text-[10px] font-bold text-destructive bg-destructive/10 px-2 py-0.5 rounded-full border border-destructive/20">
          AED {balance.toFixed(0)}
        </span>
      )}
      <div className={`h-px flex-1 opacity-20 ${bgClass.includes('amber') ? 'bg-amber-400' : bgClass.includes('orange') ? 'bg-orange-400' : bgClass.includes('indigo') ? 'bg-indigo-400' : bgClass.includes('violet') ? 'bg-violet-400' : 'bg-green-500'}`} />
      <ChevronDown className={`h-4 w-4 shrink-0 ${colorClass} transition-transform ${expanded ? 'rotate-180' : ''}`} />
    </button>
  );
}

// ─── Group renderer ───────────────────────────────────────────────────────────
function RenderGroups({ groups, records, onUpdate }: {
  groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>;
  records: DatabaseRowType[];
  onUpdate: TabProps['onUpdate'];
}) {
  if (groups.size === 0) {
    return (
      <div className="text-center py-6 text-muted-foreground text-sm border border-dashed border-border rounded-lg">
        No records in this section.
      </div>
    );
  }
  return (
    <div>
      {Array.from(groups.entries()).map(([page, dateMap]) => (
        <CollapsibleGroup key={page} label={page} colorClass="text-primary/70" lineClass="bg-primary/10" defaultOpen={false}>
          {Array.from(dateMap.entries()).map(([date, minerMap]) => (
            <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
              <div className="space-y-3">
                {Array.from(minerMap.entries()).map(([minerName, items]) => (
                  <AccountsClientCard key={minerName} minerName={minerName} records={items} allRecords={records} onUpdate={onUpdate} />
                ))}
              </div>
            </CollapsibleGroup>
          ))}
        </CollapsibleGroup>
      ))}
    </div>
  );
}

const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
  Array.from(g.values()).reduce((s, dm) =>
    s + Array.from(dm.values()).reduce((ss, mm) =>
      ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

const sumBalance = (records: DatabaseRowType[]) =>
  records.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);

// ─── Main Component ───────────────────────────────────────────────────────────
export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [verifExpanded, setVerifExpanded] = useState(true);
  const [dispatchedExpanded, setDispatchedExpanded] = useState(true);
  const [onHoldExpanded, setOnHoldExpanded] = useState(true);
  const [layawayExpanded, setLayawayExpanded] = useState(true);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [resellerExpanded, setResellerExpanded] = useState(true);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(
      records.filter(isAccountsRelevant).map(r => r.liverName?.trim().toUpperCase()).filter(Boolean)
    )) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    let base = records.filter(isAccountsRelevant);
    if (liverFilter !== 'all') base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;
      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) { const end = new Date(to); end.setHours(23, 59, 59, 999); if (d.getTime() > end.getTime()) return false; }
        return true;
      });
    }
    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  // ── Split into FIVE clearly separated status sections ──────────────────────
  const sections = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);
    const active: DatabaseRowType[] = [];
    const cleared: DatabaseRowType[] = [];

    searched.forEach(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase().trim();
      const remittanceConfirmed = remStatus.includes('secured') || remStatus.includes('received');
      const balanceZero = calcRemainingBalance(r) <= 0;
      const isPendingRemittance = remStatus === '' || remStatus === 'pending' || remStatus === 'n/a';
      const isCleared = remittanceConfirmed || (balanceZero && !isPendingRemittance);
      if (isCleared) cleared.push(r);
      else active.push(r);
    });

    // ── Section 1: Payment for Verification ──────────────────────────────
    const verif = active.filter(r => r.status === 'Payment for Verification');

    // ── Section 2: Dispatched (in transit, balance still outstanding) ─────
    const dispatched = active.filter(r => r.status === 'Dispatched');

    // ── Section 3: Paid/DP but Item Hold (layaway installments) ──────────
    const onHold = active.filter(r => r.status === 'Paid/DP but Item Hold');

    // ── Section 4: Layaway STATUS ───────────────────────────────────────
    const layaway = active.filter(r => r.status === 'Layaway');

    // ── Section 5: Delivered / Given to Shop ─────────────────────────────
    const delivered = active.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    // ── Section 6: Reseller / Outsource ──────────────────────────────────
    const resellerOutsource = active.filter(r => r.status === 'Reseller' || r.status === 'Outsource');

    return {
      verifGroups: groupByPageDateMiner(verif),
      dispatchedGroups: groupByPageDateMiner(dispatched),
      onHoldGroups: groupByPageDateMiner(onHold),
      layawayGroups: groupByPageDateMiner(layaway),
      deliveredGroups: groupByPageDateMiner(delivered),
      resellerGroups: groupByPageDateMiner(resellerOutsource),
      clearedGroups: groupByPageDateMiner(cleared),
      activeRecords: active,
      verifRecords: verif,
      dispatchedRecords: dispatched,
      onHoldRecords: onHold,
      layawayRecords: layaway,
      deliveredRecords: delivered,
      resellerRecords: resellerOutsource,
    };
  }, [filteredRecords, searchQuery]);

  const {
    verifGroups, dispatchedGroups, onHoldGroups, layawayGroups, deliveredGroups, resellerGroups, clearedGroups,
    activeRecords, verifRecords, dispatchedRecords, onHoldRecords, layawayRecords, deliveredRecords, resellerRecords,
  } = sections;

  const totalOutstanding = useMemo(() => sumBalance(activeRecords), [activeRecords]);
  const activeClientCount = useMemo(() => new Set(activeRecords.map(r => r.minerName || '').filter(Boolean)).size, [activeRecords]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeClientCount} clients · AED ${totalOutstanding.toFixed(0)} outstanding`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* Filters */}
        <div className="flex flex-wrap gap-2 mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key} size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Outstanding ({activeRecords.length})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* Summary Strip */}
            <div className="grid grid-cols-3 gap-2 mb-5">
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Users className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Clients</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeClientCount}</span>
              </div>
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Package className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Items</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeRecords.length}</span>
              </div>
              <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-destructive/70">
                  <TrendingDown className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Due</span>
                </div>
                <span className="text-sm font-bold text-destructive font-cinzel leading-tight">
                  {totalOutstanding > 0 ? `AED ${totalOutstanding.toFixed(0)}` : 'AED 0'}
                </span>
              </div>
            </div>

            {/* ── SECTION 1: PAYMENT FOR VERIFICATION ── */}
            {verifGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<ShieldCheck className="h-4 w-4" />}
                  label="PAYMENT FOR VERIFICATION"
                  count={countItems(verifGroups)}
                  pages={verifGroups.size}
                  balance={sumBalance(verifRecords)}
                  expanded={verifExpanded}
                  onToggle={() => setVerifExpanded(v => !v)}
                  colorClass="text-amber-400"
                  borderClass="border-amber-500/30"
                  bgClass="bg-amber-500/5"
                />
                {verifExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={verifGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 2: DISPATCHED (in transit, balance outstanding) ── */}
            {dispatchedGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<Truck className="h-4 w-4" />}
                  label="DISPATCHED — IN TRANSIT"
                  count={countItems(dispatchedGroups)}
                  pages={dispatchedGroups.size}
                  balance={sumBalance(dispatchedRecords)}
                  expanded={dispatchedExpanded}
                  onToggle={() => setDispatchedExpanded(v => !v)}
                  colorClass="text-orange-400"
                  borderClass="border-orange-400/30"
                  bgClass="bg-orange-400/5"
                />
                {dispatchedExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={dispatchedGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 3: ON HOLD (Paid/DP but Item Hold) ── */}
            {onHoldGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<Clock className="h-4 w-4" />}
                  label="ON HOLD — PAID / DP RECEIVED"
                  count={countItems(onHoldGroups)}
                  pages={onHoldGroups.size}
                  balance={sumBalance(onHoldRecords)}
                  expanded={onHoldExpanded}
                  onToggle={() => setOnHoldExpanded(v => !v)}
                  colorClass="text-indigo-300"
                  borderClass="border-indigo-400/30"
                  bgClass="bg-indigo-400/5"
                />
                {onHoldExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={onHoldGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 4: LAYAWAY PAYMENT PLANS ── */}
            <div className="mb-4">
              <SectionHeader
                icon={<CreditCard className="h-4 w-4" />}
                label="LAYAWAY — INSTALLMENT PLANS"
                count={countItems(layawayGroups)}
                pages={layawayGroups.size}
                balance={sumBalance(layawayRecords)}
                expanded={layawayExpanded}
                onToggle={() => setLayawayExpanded(v => !v)}
                colorClass="text-violet-400"
                borderClass="border-violet-400/30"
                bgClass="bg-violet-400/5"
              />
              {layawayExpanded && (
                <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                  {layawayGroups.size === 0
                    ? <div className="text-center py-4 text-xs text-muted-foreground border border-dashed border-violet-400/20 rounded-lg">No active layaway installment plans.</div>
                    : <RenderGroups groups={layawayGroups} records={records} onUpdate={onUpdate} />
                  }
                </div>
              )}
            </div>

            {/* ── SECTION 5: DELIVERED / GIVEN TO SHOP ── */}
            {deliveredGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<CheckCircle2 className="h-4 w-4" />}
                  label="DELIVERED / GIVEN TO SHOP"
                  count={countItems(deliveredGroups)}
                  pages={deliveredGroups.size}
                  balance={sumBalance(deliveredRecords)}
                  expanded={deliveredExpanded}
                  onToggle={() => setDeliveredExpanded(v => !v)}
                  colorClass="text-green-400"
                  borderClass="border-green-500/20"
                  bgClass="bg-green-500/5"
                />
                {deliveredExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={deliveredGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 6: RESELLER / OUTSOURCE ── */}
            {resellerGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<Share2 className="h-4 w-4" />}
                  label="RESELLER / OUTSOURCE"
                  count={countItems(resellerGroups)}
                  pages={resellerGroups.size}
                  balance={sumBalance(resellerRecords)}
                  expanded={resellerExpanded}
                  onToggle={() => setResellerExpanded(v => !v)}
                  colorClass="text-teal-400"
                  borderClass="border-teal-500/30"
                  bgClass="bg-teal-500/5"
                />
                {resellerExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={resellerGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {activeRecords.length === 0 && (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <CheckCircle2 className="h-8 w-8 text-green-500/40 mx-auto mb-2" />
                <p className="text-sm text-muted-foreground font-medium">All clear! No outstanding balances.</p>
              </div>
            )}
          </TabsContent>

          <TabsContent value="cleared">
            {clearedGroups.size === 0 ? (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No cleared records yet.</p>
              </div>
            ) : (
              <div className="space-y-3">
                <RenderGroups groups={clearedGroups} records={records} onUpdate={onUpdate} />
              </div>
            )}
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && (
        <AddClientModal
          onClose={() => setShowAddModal(false)}
          userFirstName={userFirstName}
          userEmail={userEmail}
          onRefresh={onRefresh}
          existingRecords={records}
        />
      )}
    </div>
  );
}

import { useState, memo, useMemo, useCallback, useRef } from 'react';
import { ChevronDown, FileText, History, Pencil, Copy, Check, Clock, AlertTriangle } from 'lucide-react';

function LayawayAgingBadge({ dateStr }: { dateStr?: string }) {
  if (!dateStr) return null;
  const d = parseDateRobust(dateStr);
  if (!d) return null;
  const days = Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24));
  if (days < 0) return null;
  const color = days > 30 ? 'bg-destructive/20 text-destructive border-destructive/30'
    : days > 14 ? 'bg-amber-400/20 text-amber-400 border-amber-400/30'
    : 'bg-secondary text-muted-foreground border-border';
  const Icon = days > 14 ? AlertTriangle : Clock;
  return (
    <span className={`inline-flex items-center gap-0.5 text-[9px] font-semibold px-1.5 py-0.5 rounded-full border ${color}`}>
      <Icon className="h-2.5 w-2.5" />
      {days === 0 ? 'Today' : `${days}d on layaway`}
    </span>
  );
}
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DatabaseRowType } from '@/types';
import { calcRemainingBalance, calcShippingFee, calcCCFee, calcItemPrice, calcDueDate, getQty, parseDateRobust } from '@/lib/calculations';
import { formatDateObj, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import FinancialsForm from './FinancialsForm';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';
import { toast } from 'sonner';
import { useCompactMode } from '@/lib/compactMode';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function AccountsClientCard({ minerName, records, allRecords, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [expandedItem, setExpandedItem] = useState<number | null>(null);
  const [copiedId, setCopiedId] = useState<number | null>(null);
  const [statusResetKeys, setStatusResetKeys] = useState<Record<number, number>>({});
  const statusChangingRef = useRef<Record<number, boolean>>({});

  const handleStatusChange = useCallback(async (record: DatabaseRowType, newStatus: string) => {
    if (statusChangingRef.current[record.id]) return;
    statusChangingRef.current[record.id] = true;
    setStatusResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    try {
      await onUpdate(record.id, { status: newStatus });
      toast.success(`Status: ${newStatus}`);
    } catch {
      toast.error('Failed to update status');
    } finally {
      statusChangingRef.current[record.id] = false;
    }
  }, [onUpdate]);

  const copyRecord = useCallback((record: DatabaseRowType) => {
    const bal = calcRemainingBalance(record);
    const text = [
      record.itemDescription,
      record.grams ? `${record.grams}g` : '',
      `AED ${calcItemPrice(record).toFixed(2)}`,
      bal > 0 ? `Bal: AED ${bal.toFixed(2)}` : 'Paid',
    ].filter(Boolean).join(' · ');
    navigator.clipboard.writeText(text).catch(() => {});
    setCopiedId(record.id);
    setTimeout(() => setCopiedId(null), 1500);
  }, []);

  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));
  const { isCompact } = useCompactMode();
  const totalRemaining = records.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

  // Group records by Date → Liver → Status
  const grouped = useMemo(() => {
    const byDate: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'No Date';
      const liver = r.liverName || 'Unknown Liver';
      const status = r.status || 'No Status';
      if (!byDate[date]) byDate[date] = {};
      if (!byDate[date][liver]) byDate[date][liver] = {};
      if (!byDate[date][liver][status]) byDate[date][liver][status] = [];
      byDate[date][liver][status].push(r);
    }
    return byDate;
  }, [records]);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button className="w-full text-left px-4 py-3 flex items-center justify-between" onClick={() => setExpanded(e => !e)}>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-cinzel text-sm text-primary">{minerName}</span>
            {first?.customerId && (
              <button
                className="text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            {!isCompact && <span>Due: {dueDate}</span>}
          </div>
          {totalRemaining > 0 && (
            <span className="text-xs font-medium text-destructive">Balance: AED {totalRemaining.toFixed(2)}</span>
          )}
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {/* Generate Invoice at the TOP */}
          <Button
            variant="outline"
            size="sm"
            className="w-full mb-3 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>

          {/* Grouped by Date → Liver → Status */}
          {Object.entries(grouped).sort().map(([date, livers]) => (
            <div key={date} className="mb-3">
              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2 px-1">
                📅 {formatDate(date)}
              </div>
              {Object.entries(livers).map(([liver, statuses]) => (
                <div key={liver} className="mb-2 ml-2">
                  <div className="text-xs font-medium text-primary/80 mb-1 px-1">🧑 {liver}</div>
                  {Object.entries(statuses).map(([status, items]) => (
                    <div key={status} className="mb-2 ml-2">
                      <div className="text-xs text-muted-foreground mb-1 px-1 flex items-center gap-1">
                        <StatusBadge status={status} /> <span className="ml-1">({items.length})</span>
                      </div>
                      {items.map(record => (
                        <div key={record.id} className="mb-2 rounded-lg border border-border/50 bg-secondary/20 overflow-hidden group/item">
                          <button
                            className="w-full text-left p-3 flex items-start justify-between"
                            onClick={() => setExpandedItem(expandedItem === record.id ? null : record.id)}
                          >
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-medium truncate mb-1">{record.itemDescription}</p>
                              {!isCompact && (
                                <div className="text-xs text-muted-foreground">
                                  {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')} · {record.modeOfPayment}
                                </div>
                              )}
                              {!isCompact && (record.modeOfPayment || '').toLowerCase() === 'layaway' && (
                                <div className="mt-1">
                                  <LayawayAgingBadge dateStr={record.dateOfLive} />
                                </div>
                              )}
                              {!isCompact && (
                                <div className="flex gap-3 text-xs mt-1">
                                  <span className="text-muted-foreground">Price: <span className="text-foreground">{record.currency || 'AED'} {calcItemPrice(record).toFixed(2)}</span></span>
                                  <span className="text-muted-foreground">SF: <span className="text-foreground">AED {calcShippingFee(record).toFixed(2)}</span></span>
                                  {calcCCFee(record) > 0 && <span className="text-muted-foreground">CC: <span className="text-foreground">AED {calcCCFee(record).toFixed(2)}</span></span>}
                                </div>
                              )}
                              <div className="text-xs mt-0.5">
                                <span className={`font-medium ${calcRemainingBalance(record) > 0 ? 'text-destructive' : 'text-green-400'}`}>
                                  Balance: AED {calcRemainingBalance(record).toFixed(2)}
                                </span>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 ml-2 mt-0.5 shrink-0">
                              {/* Quick actions — visible on hover */}
                              <button
                                title="Copy item summary"
                                onClick={e => { e.stopPropagation(); copyRecord(record); }}
                                className="opacity-0 group-hover/item:opacity-100 transition-opacity p-1 rounded hover:bg-secondary text-muted-foreground hover:text-foreground"
                              >
                                {copiedId === record.id
                                  ? <Check className="h-3 w-3 text-green-400" />
                                  : <Copy className="h-3 w-3" />}
                              </button>
                              <button
                                title="Edit financials"
                                onClick={e => { e.stopPropagation(); setExpandedItem(expandedItem === record.id ? null : record.id); }}
                                className="opacity-0 group-hover/item:opacity-100 transition-opacity p-1 rounded hover:bg-primary/10 text-muted-foreground hover:text-primary"
                              >
                                <Pencil className="h-3 w-3" />
                              </button>
                              <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform ${expandedItem === record.id ? 'rotate-180' : ''}`} />
                            </div>
                          </button>

                          {expandedItem === record.id && (
                            <div className="px-3 pb-3 animate-in fade-in slide-in-from-top-2 duration-200">
                              <div className="mb-2">
                                <p className="text-[10px] text-muted-foreground uppercase tracking-wide mb-1">Change Status</p>
                                <Select
                                  key={`acc-status-${record.id}-${statusResetKeys[record.id] || 0}`}
                                  onValueChange={v => handleStatusChange(record, v)}
                                >
                                  <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                                    <SelectValue placeholder="Set status..." />
                                  </SelectTrigger>
                                  <SelectContent className="bg-popover border-border">
                                    <SelectItem value="Reseller" className="text-xs">Reseller</SelectItem>
                                    <SelectItem value="Outsource" className="text-xs">Outsource</SelectItem>
                                    <SelectItem value="Payment for Verification" className="text-xs">Payment for Verification</SelectItem>
                                    <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem>
                                    <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                                    <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                                    <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                                    <SelectItem value="Layaway" className="text-xs">Layaway</SelectItem>
                                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                                  </SelectContent>
                                </Select>
                              </div>
                              <FinancialsForm record={record} onUpdate={onUpdate} />
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          ))}
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

export default memo(AccountsClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useState, useRef, memo } from 'react';
import { FileText, Truck, Upload, History, ChevronDown, AlertTriangle, Pencil, Check, X, Scissors } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { useCompactMode } from '@/lib/compactMode';
import { calcShippingFee, isFreeSf, isPromoSf, getPromoSf, getQty } from '@/lib/calculations';
import StatusBadge from '@/components/StatusBadge';
