export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { AlertTriangle, Clock, CreditCard, X } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { parseDateRobust } from '@/lib/calculations';
import { Button } from '@/components/ui/button';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

interface LayawayAlert {
  record: DatabaseRowType;
  monthLabel: string;   // e.g. "Month 1 Payment"
  daysUntilDue: number; // negative = overdue
  dueDate: Date;
}

const n = (v: unknown) => parseFloat(String(v ?? '0')) || 0;

function getNextDueAlert(record: DatabaseRowType): LayawayAlert | null {
  const dateOfLive = parseDateRobust(record.dateOfLive);
  if (!dateOfLive) return null;

  const payments = [
    { label: 'Month 1 Payment', value: n(record.la1MonthPayment) },
    { label: 'Month 2 Payment', value: n(record.la2MonthPayment) },
    { label: 'Month 3 Payment', value: n(record.la3MonthPayment) },
    { label: 'Month 4 Payment', value: n(record.la4MonthPayment) },
  ];

  const now = Date.now();

  for (let i = 0; i < payments.length; i++) {
    if (payments[i].value > 0) continue; // already paid

    // Due date: dateOfLive + (i+1) * 30 days
    const dueDate = new Date(dateOfLive.getTime() + (i + 1) * 30 * 24 * 60 * 60 * 1000);
    const msUntilDue = dueDate.getTime() - now;
    const daysUntilDue = Math.ceil(msUntilDue / (1000 * 60 * 60 * 24));

    // Alert if 5 days or fewer away (including overdue up to 3 days)
    if (daysUntilDue <= 5 && daysUntilDue >= -3) {
      return {
        record,
        monthLabel: payments[i].label,
        daysUntilDue,
        dueDate,
      };
    }
    break; // Only check the FIRST unpaid month
  }

  return null;
}

function urgencyConfig(days: number): { color: string; bg: string; border: string; label: string } {
  if (days < 0) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/40', label: 'OVERDUE' };
  if (days === 0) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/40', label: 'DUE TODAY' };
  if (days === 1) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/30', label: '1 DAY LEFT' };
  if (days === 2) return { color: 'text-orange-400', bg: 'bg-orange-400/10', border: 'border-orange-400/30', label: '2 DAYS LEFT' };
  if (days === 3) return { color: 'text-amber-400', bg: 'bg-amber-400/10', border: 'border-amber-400/30', label: '3 DAYS LEFT' };
  if (days === 4) return { color: 'text-amber-400', bg: 'bg-amber-400/10', border: 'border-amber-400/30', label: '4 DAYS LEFT' };
  return { color: 'text-yellow-400', bg: 'bg-yellow-400/10', border: 'border-yellow-400/30', label: '5 DAYS LEFT' };
}

export default function LayawayPaymentAlert({ records, onClose }: Props) {
  const alerts = useMemo(() => {
    const result: LayawayAlert[] = [];
    for (const r of records) {
      if (r.status !== 'Layaway') continue;
      const alert = getNextDueAlert(r);
      if (alert) result.push(alert);
    }
    // Sort: overdue first, then soonest
    return result.sort((a, b) => a.daysUntilDue - b.daysUntilDue);
  }, [records]);

  if (alerts.length === 0) return null;

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="bg-card border-border max-w-md max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Layaway Payment Reminders
            <Badge variant="destructive" className="ml-auto text-xs">{alerts.length} alert{alerts.length !== 1 ? 's' : ''}</Badge>
          </DialogTitle>
        </DialogHeader>

        <p className="text-xs text-muted-foreground -mt-2 mb-2">
          The following layaway customers have upcoming or overdue monthly payments.
        </p>

        <div className="space-y-3">
          {alerts.map((alert, idx) => {
            const cfg = urgencyConfig(alert.daysUntilDue);
            return (
              <div
                key={`${alert.record.id}-${idx}`}
                className={`rounded-xl border p-3 ${cfg.bg} ${cfg.border}`}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <AlertTriangle className={`h-3.5 w-3.5 shrink-0 ${cfg.color}`} />
                      <span className={`text-xs font-bold font-cinzel ${cfg.color}`}>
                        {alert.record.minerName?.toUpperCase() || 'UNKNOWN'}
                      </span>
                    </div>
                    <p className="text-xs text-foreground font-medium truncate mb-0.5">
                      {alert.record.itemDescription}
                    </p>
                    <p className="text-[10px] text-muted-foreground">
                      {alert.record.category} · {alert.record.page}
                      {alert.record.liverName && ` · ${alert.record.liverName}`}
                    </p>
                    <div className="flex items-center gap-1.5 mt-1.5">
                      <Clock className={`h-3 w-3 ${cfg.color}`} />
                      <span className={`text-xs font-semibold ${cfg.color}`}>{alert.monthLabel}</span>
                      <span className="text-[10px] text-muted-foreground">
                        due {alert.dueDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                      </span>
                    </div>
                  </div>
                  <span className={`shrink-0 text-[9px] font-bold px-2 py-1 rounded-full border ${cfg.bg} ${cfg.color} ${cfg.border}`}>
                    {cfg.label}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <Button
          className="w-full mt-2 bg-primary text-primary-foreground"
          onClick={onClose}
        >
          <X className="h-4 w-4 mr-1.5" /> Dismiss
        </Button>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DatabaseRowType } from '@/types';
import { getRatesForDate } from '@/lib/ratesStore';

interface Props {
  items: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

/** Infer the payment currency from Mode of Payment — this determines how the stored amount is interpreted by calcTotalPaid */
function inferDpCurrency(mop?: string): string {
  const m = (mop || '').toLowerCase().trim();
  if (m === 'gcash' || m === 'bank transfer php') return 'PHP';
  if (m.includes('usd') || m.includes('western union (us)')) return 'USD';
  // Credit card, COD, AED bank transfer, Tabby, Tamara, Pick Up, Meet Up → AED
  return 'AED';
}

function getPrimaryDP(items: DatabaseRowType[]): { item: DatabaseRowType | null; amount: string } {
  for (const r of items) {
    const v = String(r.downpayment || '').trim();
    if (v && v !== 'acknowledged' && !isNaN(parseFloat(v))) {
      return { item: r, amount: v };
    }
  }
  return { item: null, amount: '' };
}

function hasSavedDP(items: DatabaseRowType[]): boolean {
  return getPrimaryDP(items).amount !== '';
}

export default function GroupDownpaymentSection({ items, onUpdate }: Props) {
  const { amount: initialAmount } = getPrimaryDP(items);
  const inferredCurrency = inferDpCurrency(items[0]?.modeOfPayment);

  const [checked, setChecked] = useState(() => hasSavedDP(items));
  const [amount, setAmount] = useState(initialAmount);
  const [dpCurrency, setDpCurrency] = useState(inferredCurrency);
  const [saving, setSaving] = useState(false);
  const userActed = useRef(false);

  // Sync from external record updates
  useEffect(() => {
    const { amount: ext } = getPrimaryDP(items);
    if (ext) {
      setAmount(ext);
      setChecked(true);
    } else if (!userActed.current) {
      setChecked(false);
      setAmount('');
    }
    // Update inferred currency if MOP changes
    setDpCurrency(inferDpCurrency(items[0]?.modeOfPayment));
    userActed.current = false;
  }, [items]);

  /** Convert entered amount to the currency the system expects (inferred from MOP), then save */
  const resolveAmountToSave = (val: string, selectedCurrency: string): string => {
    const num = parseFloat(val);
    if (isNaN(num) || num <= 0) return val;
    if (selectedCurrency === inferredCurrency) return val; // no conversion needed

    // Convert to AED first, then to the inferred currency
    const rates = getRatesForDate(items[0]?.dateOfLive || '');
    let aed = num;
    if (selectedCurrency === 'PHP') aed = num / rates.phpRate;
    else if (selectedCurrency === 'USD') aed = num * 3.67;

    // Now convert AED to inferred currency
    if (inferredCurrency === 'PHP') return String(Math.round(aed * rates.phpRate));
    if (inferredCurrency === 'USD') return String((aed / 3.67).toFixed(2));
    return String(Math.round(aed)); // AED
  };

  /** Display the converted hint when currency differs from inferred */
  const getConversionHint = (): string | null => {
    if (dpCurrency === inferredCurrency) return null;
    const num = parseFloat(amount);
    if (isNaN(num) || num <= 0) return null;
    const converted = resolveAmountToSave(amount, dpCurrency);
    const convNum = parseFloat(converted);
    if (isNaN(convNum)) return null;
    return `Saves as ${inferredCurrency} ${convNum.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const conversionHint = getConversionHint();

  const saveGroupDP = useDebouncedCallback(async (val: string, currency: string) => {
    if (!val || isNaN(parseFloat(val))) return;
    const valueToSave = resolveAmountToSave(val, currency);
    setSaving(true);
    for (let i = 0; i < items.length; i++) {
      const dpVal = i === 0 ? valueToSave : 'acknowledged';
      await onUpdate(items[i].id, { downpayment: dpVal });
      await new Promise(res => setTimeout(res, 80));
    }
    setSaving(false);
  }, 600);

  const handleCheck = async (on: boolean) => {
    userActed.current = true;
    setChecked(on);
    if (!on) {
      setAmount('');
      setSaving(true);
      for (const r of items) {
        await onUpdate(r.id, { downpayment: '' });
        await new Promise(res => setTimeout(res, 80));
      }
      setSaving(false);
    }
  };

  const handleAmount = (val: string) => {
    userActed.current = true;
    setAmount(val);
    saveGroupDP(val, dpCurrency);
  };

  const handleCurrencyChange = (newCurrency: string) => {
    setDpCurrency(newCurrency);
    if (amount) saveGroupDP(amount, newCurrency);
  };

  const invoiceNo = items.find(r => r.pureWeight)?.pureWeight;

  return (
    <div className="mx-1 mb-2 rounded-lg border border-primary/20 bg-primary/5 px-3 py-2">
      <div className="flex items-center gap-2 flex-wrap">
        <Checkbox
          id={`group-dp-${items[0]?.id}`}
          checked={checked}
          disabled={saving}
          onCheckedChange={(v) => handleCheck(!!v)}
        />
        <Label htmlFor={`group-dp-${items[0]?.id}`} className="text-xs cursor-pointer font-semibold">
          Downpayment
          <span className="text-muted-foreground font-normal ml-1">
            (applies to all {items.length} item{items.length !== 1 ? 's' : ''}{invoiceNo ? ` · Invoice ${invoiceNo}` : ''})
          </span>
        </Label>
        {checked && amount && !conversionHint && (
          <span className="text-xs text-primary font-bold ml-auto">
            {dpCurrency} {parseFloat(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        )}
      </div>
      {checked && (
        <div className="mt-2 space-y-1.5">
          <div className="flex gap-1.5">
            {/* Currency selector */}
            <Select value={dpCurrency} onValueChange={handleCurrencyChange}>
              <SelectTrigger className="h-8 w-20 text-xs bg-background border-border shrink-0">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                <SelectItem value="AED" className="text-xs">
                  AED
                </SelectItem>
                <SelectItem value="PHP" className="text-xs">
                  PHP
                </SelectItem>
                <SelectItem value="USD" className="text-xs">
                  USD
                </SelectItem>
              </SelectContent>
            </Select>
            <Input
              type="number"
              value={amount}
              onChange={e => handleAmount(e.target.value)}
              className="h-8 text-xs bg-background border-border flex-1"
              placeholder={`Enter ${dpCurrency} downpayment...`}
              disabled={saving}
              autoFocus
            />
          </div>
          {conversionHint && (
            <p className="text-[10px] text-amber-400 flex items-center gap-1">
              ↳ {conversionHint} (converted from {dpCurrency} to match {inferredCurrency} payment method)
            </p>
          )}
        </div>
      )}
    </div>
  );
}

